-- 科目Ⅱ 財務分析 追加問題（第1〜5回・各180問）。既存の seed_finance.sql の後に実行する
-- dev/build_finance_extra.py で自動生成
insert into public.questions (id, point_code, level, stem, answer, explanation, sort) values
('f1-021','2001','基礎','証券アナリストの主な仕事は、企業の将来業績を予測して投資価値を評価することであり、この点はセルサイドでもバイサイドでも変わらない。',true,
 '正しい。証券会社に属して投資家に情報を仲介するセルサイドも、機関投資家に属して自ら運用のための調査を行うバイサイドも、将来業績を予測して投資価値を見極めることが中心業務である。',3121),
('f1-022','2001','基礎','セルサイドのアナリストは通常、銀行や生命保険会社といった機関投資家に所属し、自社の資金運用のための調査を担当する。',false,
 '誤り。機関投資家に属して自ら運用のための調査を行うのはバイサイドのアナリストである。セルサイドのアナリストは通常、証券会社に属し、投資家に証券投資に必要な情報を仲介・提供する。',3122),
('f1-023','2001','標準','証券のファンダメンタル価値とは、投資家が公表情報を適切に分析して将来業績の予測に有用な内容を取り出したときに成立するはずの価格をいう。',true,
 '正しい。本源的な価値とも呼ばれるファンダメンタル価値は、証券の価格形成の理論に照らして本来付くはずの価格であり、これを見出すための分析がファンダメンタル分析である。',3123),
('f1-024','2001','標準','ファンダメンタル分析が意味を持つのは、市場価格が常にファンダメンタル価値と一致しており、ミスプライスされた銘柄が存在しないからである。',false,
 '誤り。少なくとも短期的には実際の価格とファンダメンタル価値が食い違い得るからこそ、割安な銘柄を買い割高な銘柄を売る判断に意味がある。全情報が瞬時に無コストで価格に織り込まれるなら、分析は意味を失う。',3124),
('f1-025','2001','標準','ペンマンが示すファンダメンタル分析の5つのプロセスのうち、全体の中核をなすのは最初の「事業内容の理解」である。',false,
 '誤り。中核をなすのは3番目の「予測の展開」であり、集めたデータを基に企業価値の基礎となる将来のキャッシュフローを見積もる。事業内容の理解と情報の分析は、その前段の基礎データ収集・分析にあたる。',3125),
('f1-026','2001','基礎','特別損失のため当期は純損失となった企業でも、経常利益が過去数期にわたり高い水準で推移していれば、潜在的な収益力は高いと判断できる場合がある。',true,
 '正しい。損益計算書の多段階表示から、一過性の特別損失と毎期継続的な活動の成果である経常利益を分けて見れば、純利益の大小だけによる投資判断が変わることがある。',3126),
('f1-027','2001','応用','利益800・総資産4,000のX社と、利益300・総資産1,000のY社を比べると、利益の絶対額は小さいY社の方が資本利益率は高い。',true,
 '正しい。資本利益率（利益÷資本）はX社が800÷4,000＝20％、Y社が300÷1,000＝30％でY社が高い。絶対額だけでなく資金運用の効率性を表す比率も重視する必要がある。',3127),
('f1-028','2001','応用','クリーンサープラスの制約とは、増資・配当・自社株買いなどがない状況で、株主資本の増減が営業キャッシュ・フローと一致する関係をいう。',false,
 '誤り。クリーンサープラスの制約とは、資本取引がない状況で、株主資本の増減額が損益計算書の利益（損失）に等しくなる関係、すなわち貸借対照表と損益計算書がつながっていることをいう。',3128),
('f1-029','2001','標準','多くの実証研究では、将来のキャッシュフローを見積もるには、利益情報よりも過去のキャッシュフロー実績を直接用いる方が有用だと指摘されている。',false,
 '誤り。将来のキャッシュフローを見積もるうえでは、キャッシュフローの実績より利益情報の方が役立つことが多くの実証研究で示されており、その事実を合理的に説明するモデルもある。',3129),
('f1-030','2002','基礎','利益の計算と開示は、所有と経営の分離が進んだ現代の大企業が登場したことをきっかけに始められた。',false,
 '誤り。企業会計の歴史は古く、大企業の出現以前から、出資者の資金を預かった者の説明責任を果たす手段や、借入先である銀行を意識した形で利益の計算・開示が行われてきた。',3130),
('f1-031','2002','標準','投資家と経営者の間の情報の非対称性を和らげ、資本市場での資金の円滑な循環を促す企業会計の役割は、情報提供機能あるいは意思決定支援機能と呼ばれる。',true,
 '正しい。投資家の意思決定に役立つ情報を提供するこの役割を情報提供機能（意思決定支援機能）といい、公開企業の利益情報が果たす主要な機能とされる。',3131),
('f1-032','2002','標準','自己資本比率や負債比率が所定の水準に達したときに債務の即時返済を義務付ける財務上の特約は、利益情報を私的契約による利害調整に用いる例である。',true,
 '正しい。経営者の債権者を害する行動を一つずつ契約で禁じるのは難しいため、債権者の利害と結び付く会計数値を用いた財務上の特約が結ばれる。利益情報の副次的な用途の一つである。',3132),
('f1-033','2002','標準','会計利益連動型の報酬契約は、債権者と経営者の間で結ばれ、経営者に債権者の利害に沿った行動をとらせるための仕組みである。',false,
 '誤り。会計利益連動型の報酬契約は株主と経営者の間で結ばれる。利益の一定割合を報酬とすることで、報酬を増やしたい経営者の努力が自動的に株主の望む方向に向かうよう工夫したものである。',3133),
('f1-034','2002','応用','債権者の利害を犠牲にするつもりのない経営者には、財務上の特約を自ら受け入れる誘因はない。',false,
 '誤り。そうした経営者が特約に応じないと、債権者を害しかねない経営者と受け止められ、より高い借入コストを求められるおそれがある。このため経営者の側にも特約を結ぶ誘因がある。',3134),
('f1-035','2002','標準','会社法の配当規制は、多数の企業が債権者と似た私的契約を個別に結ぶ交渉コストを、社会全体として節約するという観点から説明される。',true,
 '正しい。配当限度額を抑える私的契約が広く求められるなら、標準的な契約を不特定多数の企業に適用する公的規制に組み込んでおく方が効率的であり、配当規制はこの観点から説明される。',3135),
('f1-036','2002','基礎','法人税の申告期限は、原則として事業年度終了日の翌日から3ヵ月以内と定められている。',false,
 '誤り。法人税の申告は事業年度終了日の翌日から2ヵ月以内に行う必要があり、3月決算なら5月31日が期限となる。原則3ヵ月以内の有価証券報告書より期限の扱いが厳しい。',3136),
('f1-037','2002','標準','損益計算書に計上される税金の費用と、キャッシュ・フロー計算書に記載される税金の支出額は、一般に一致しない。',true,
 '正しい。税金支出は課税所得に税率を掛けた現金支出額であるのに対し、損益計算書の税金費用はそれを基礎に発生主義の考え方で期間配分して算定されるため、両者は異なる。',3137),
('f1-038','2002','応用','有価証券の時価評価差額を期間損益に含めることは、投資家への情報提供の観点からも、配当規制による債権者保護の観点からも、同様に望ましいと評価される。',false,
 '誤り。情報提供の観点では有用でも、値上がり益を含む利益を基準に配当すると、配当の原資を追加借入で賄う必要が生じ返済リスクを高め得る。利害調整の観点からは望ましいとはいい切れない。',3138),
('f1-039','2002','標準','利益を増やす方向の会計基準を新たに導入する場合、課税所得を通じて納税額が増える影響も勘案して、導入するかどうかが判断されることがある。',true,
 '正しい。利益に基づいて課税所得を決める仕組みの下では、基準変更による名目的な増益にも課税され得る。増税の悪影響が深刻なら、基準改訂の提案が取り下げられることもあり得る。',3139),
('f1-040','2002','基礎','開示される利益は副次的な用途にも配慮して決められている面があるため、アナリストは必要に応じてその影響を取り除くよう公表数値を修正する必要がある。',true,
 '正しい。情報提供の観点で最善の利益が常に開示されているとは限らないので、副次的な用途への配慮がどう影響しているかを把握し、分析目的に合わせて組み替える必要がある。',3140),
('f1-041','2003','基礎','財務諸表の数値からは、企業がどのような経営方針や戦略の文脈で利益を生む活動を行ったのかという情報も直接読み取ることができる。',false,
 '誤り。いつ・どの活動でいくら利益が生じたかは取引記録から把握し得るが、なぜその活動を行ったかという文脈に関わる情報を財務諸表の数値から直接読み取るのは難しく、定性的情報で補う必要がある。',3141),
('f1-042','2003','標準','出てきた利益の水準に経営者が満足しているか、まだ増益の余地があるかといった評価に関する情報は、財務諸表には反映できない。',true,
 '正しい。こうした評価に関する情報は定量的な財務諸表には反映できないため、ファンダメンタル分析で利益情報を使う際は、抜け落ちた情報を定性的な情報などで補う必要がある。',3142),
('f1-043','2003','応用','ある項目の価値を客観的に定量化できることは、その項目を財務諸表に計上するための十分条件とされている。',false,
 '誤り。客観的に定量化できることは計上の必要条件にとどまる。計上の可否は、その項目を載せることで利益がどんな意味を持つか、会計情報の有用性が高まるかという観点から決まる。',3143),
('f1-044','2003','標準','仕訳帳に当たる生の取引データを開示すれば、得意先別などの細かな情報が得られる利点があるが、外部の投資家がそのデータを自ら集計するのは実際には難しい。',true,
 '正しい。生データの開示は集計過程での情報の脱落を避けられる点で優れるが、内部情報を持たない外部の投資家が集計作業を肩代わりするのは困難なため、集計は財務諸表を作る企業が担っている。',3144),
('f1-045','2003','基礎','現行の会計基準では、事業部門別や地域別のセグメント情報の開示は求められているが、得意先別や個別製品別のような極めて細かい区分の情報は開示されない。',true,
 '正しい。財務諸表の作成過程でデータは集計・統合され、一部の要素は失われる。セグメント情報は開示されるが、得意先別・支店別・製品別といった細かな区分の情報までは得られない。',3145),
('f1-046','2003','標準','現行の会計ルールは、同一の活動を行った企業の利益は一致すべきであり、一致しなければどちらかの計算が誤っていると考える立場に立っている。',false,
 '誤り。現行ルールは、事実に忠実な利益が複数併存し得ると考えている。同じ活動でも将来見通しや会計方針の選択の違いで利益は食い違うのが普通であり、いずれも正しい利益とみなされる。',3146),
('f1-047','2003','標準','事実に忠実な利益が複数あり得るとみる立場は、利益の真実性を相対的なものとみる立場であり、利益は一つしかないとみる絶対的真実性の立場と対比される。',true,
 '正しい。事実を忠実に描いた利益は一つだけとみるのが利益の真実性を絶対的なものとみる立場であり、複数あり得るとみるのは真実性を相対的なものとする立場である。現行ルールは後者に立つ。',3147),
('f1-048','2003','標準','製造物責任訴訟で敗訴の可能性がある企業について、引当金を計上する慎重な経営者の利益だけが会計基準上正しく、計上しない経営者の利益は誤りとされる。',false,
 '誤り。勝訴するか敗訴するかの見通しは経営者の判断次第であり、事前にはどちらが正しいともいえない。損失を前倒しで計上するか否かで利益は異なるが、いずれも会計基準に照らして正しい利益とみなされる。',3148),
('f1-049','2003','基礎','後入先出法は、会計基準の国際的な調和を進める流れの中で、2010年4月1日以降に開始する事業年度から採用が新たに認められた。',false,
 '誤り。以前は認められていた後入先出法は、国際的な調和・収斂を求める動きの中で、2010年4月1日以降に開始する事業年度から採用が禁止された。',3149),
('f1-050','2003','応用','減価償却方法を定額法だけに統一すれば処理の画一性は高まるが、実態の異なる企業に同じ処理を強いることで、比較可能性がかえって損なわれる場合もある。',true,
 '正しい。画一性が高まることと比較可能性が高まることは別の問題である。直面する事実が違うのに一律の処理を強制すると、かえって比較可能性を損なう場合がある。',3150),
('f1-051','2003','標準','将来事象の見積り方法や選択できる会計方針の幅を狭めることは技術的に不可能であるため、経営者の裁量の余地が残されている。',false,
 '誤り。幅を狭めることは少なくとも技術的には可能である。それでも統一がある程度に抑えられているのは、過度の画一化が実態に合わない見積りや会計方針を強いられる企業を生むためである。',3151),
('f1-052','2004','基礎','金融商品取引法は投資者の保護を目的の一つに掲げ、上場会社等に対して事業年度ごとに有価証券報告書の提出を求めている。',true,
 '正しい。金融商品取引法は投資家保護を立法趣旨とし、上場会社や有価証券の募集・売出しを行った会社に有価証券報告書の提出を求めている（第24条）。財務諸表はこの報告書に収められる。',3152),
('f1-053','2004','標準','財務諸表等規則は、財務諸表の作成に用いる会計処理の内容を網羅的かつ詳細に定めており、会計基準に委ねている事項はない。',false,
 '誤り。財務諸表等規則は用語・様式・作成方法など形式面の規定が中心で、それも概括的である。定めのない事項は「一般に公正妥当と認められる企業会計の基準」に従うとされ、詳細は会計基準に委ねられている。',3153),
('f1-054','2004','標準','民間団体であるASBJが公表した会計基準は、金融庁長官の告示による指定を通じて「一般に公正妥当と認められる企業会計の基準」として扱われる。',true,
 '正しい。ASBJが新たに公表した会計基準は、2009年12月の金融庁公告第69号・第70号の一部改正という形で追加指定され、一般に公正妥当と認められる企業会計の基準と認められている。',3154),
('f1-055','2004','応用','ASBJの公表物の一つである移管指針は、企業会計審議会が公表してきた企業会計原則をASBJが包括的に引き継いだものである。',false,
 '誤り。移管指針は、ASBJ設立前に日本公認会計士協会が公表していた会計に関する実務指針（Q&Aを含む）を、ASBJが2024年7月に包括的に継承したものである。',3155),
('f1-056','2004','標準','ASBJが2024年3月以降に公表している「補足文書」は、会計基準の解釈や適用を実務上補うためのもので、会計基準のような規範性は持たない。',true,
 '正しい。補足文書は規範性を持たない点で会計基準と異なり、基準の解釈や適用を実務面で補う目的で公表されている。',3156),
('f1-057','2004','基礎','会社法の適用対象は、株式を公開している会社など、一定規模以上の株式会社に限定されている。',false,
 '誤り。上場会社等を対象とする金融商品取引法と異なり、会社法は規模や上場の有無にかかわらずすべての会社を対象とする。立法趣旨も異なり、会社法は当事者間の利害調整、特に債権者保護にあるとされる。',3157),
('f1-058','2004','標準','会社法は利益の具体的な計算方法を本文で詳しく定めておらず、計算に関する規定は法務省令である会社計算規則に委ねている。',true,
 '正しい。会社法の本文には資本金の額などや剰余金の配当に関する規定があるだけで、用語・様式・作成方法などの比較的詳細な規定は会社計算規則に置かれている。',3158),
('f1-059','2004','基礎','会社計算規則で定めていない事項について、会社法は税法の規定に従うことを求めている。',false,
 '誤り。会社計算規則でカバーしきれない部分は、「一般に公正妥当と認められる企業会計の慣行」に従うものとされている（会社法第431条）。',3159),
('f1-060','2004','標準','会社法の開示規制は、株主や債権者が資金の提供・引上げや経営者の選任・解任を判断するのに要る情報の提供を義務付けるもので、中小企業にも及ぶ。',true,
 '正しい。資金の提供や引上げの判断は将来キャッシュフローに左右され、その予測に役立つ利益情報の提供は大企業だけでなく中小企業にも求められる。期間利益の計算は開示規制の面からも会社法の規制を受ける。',3160),
('f1-061','2004','基礎','企業会計上の利益を基に課税所得を計算し、確定した決算に基づいて法人税の申告書を作成する考え方を確定決算主義という。',true,
 '正しい。法人税法第74条は確定した決算に基づく申告を求めている。会計上の利益を出発点に課税所得を求めるこの考え方が確定決算主義であり、損金経理要件はその表れである。',3161),
('f1-062','2004','標準','米国では、課税所得と会計上の利益を原則として一体で計算する「税会一致」の考え方がとられている。',false,
 '誤り。米国では課税所得と会計上の利益を原則として別々に計算しており、税会分離と呼ばれる。各法の趣旨は達成しやすいが、企業は似た計算を繰り返すコストを負う。',3162),
('f1-063','2004','標準','企業会計・会社法・税法が協調して会計規定を統一する日本の「トライアングル体制」は、IFRSとの共通化が進むほど一層強固になると考えられている。',false,
 '誤り。IFRSは公正価値の見積りなど会社法や税法の趣旨になじみにくい手続きを多く求めるといわれ、企業会計と関係法令の関係は少しずつ変化していくと予想されている。体制が保たれる保証はない。',3163),
('f1-064','2005','基礎','金融商品取引法に基づく有価証券報告書と会社法に基づく計算書類は、いずれも法定開示書類の典型例である。',true,
 '正しい。法定開示書類の典型は有価証券報告書（金融商品取引法）と計算書類（会社法）であり、独立した公認会計士などの確認を経るため信頼性が高く、詳細な情報を含む。',3164),
('f1-065','2005','標準','法定開示書類は信頼性が高い反面、作成に多くのコストがかかるため開示の回数が限られ、これを補う形で法の定めによらない適時開示が行われている。',true,
 '正しい。投資家の意思決定には適時性も求められるため、厳密さを多少犠牲にしても重要な事実を速やかかつ公平に伝える適時開示が、法定開示と併存している。',3165),
('f1-066','2005','標準','決算短信で次年度の業績予想の開示が広く求められている点は、米国など海外の主要国と共通する国際的に標準的な実務である。',false,
 '誤り。アナリストが必要とする次年度の業績予想が取引所の規則に基づき広く求められている点は、海外主要国にはみられない日本固有の特徴とされている。',3166),
('f1-067','2005','応用','四半期開示制度の廃止に伴い、四半期決算短信では、それまで任意または簡素化が認められていたセグメント情報に関して一定水準の開示が義務付けられた。',true,
 '正しい。2024年4月1日以降に開始する事業年度から四半期決算短信に一本化され、セグメント情報、継続企業の前提に関する注記、株主資本の著しい変動に関する注記が義務付けられた。',3167),
('f1-068','2005','応用','四半期開示制度の廃止後は、すべての上場企業の四半期決算短信について、監査人のレビューを受けることが義務となっている。',false,
 '誤り。四半期決算短信のレビューは原則として任意である。過去に不正な会計処理をした企業や内部統制に重大な欠陥がある企業などに限り、例外的にレビューが求められる。',3168),
('f1-069','2005','標準','四半期開示制度が廃止されたことにより、第2四半期報告書に当たる半期報告書の提出も不要となった。',false,
 '誤り。四半期開示制度は廃止されたが、第2四半期報告書に当たる半期報告書は、改正後も引き続き提出が求められている。',3169),
('f1-070','2005','基礎','EDINETは、企業が自主的に開示したIR資料を含め、企業が公表するあらゆる開示資料を閲覧できるシステムである。',false,
 '誤り。EDINETは金融商品取引法に基づく有価証券報告書などの開示書類を電子的に開示するシステムで、登録されるのは法定の開示書類である。有価証券報告書の全文検索機能も備える。',3170),
('f1-071','2005','基礎','決算短信は、公認会計士または監査法人による監査を受けることが求められていない書類である。',true,
 '正しい。決算短信は取引所の適時開示ルールに基づく決算の速報値であり、参考様式にも監査の対象外である旨が明記されている。',3171),
('f1-072','2005','標準','日本証券アナリスト協会による「ディスクロージャー優良企業」の選定や、日本IR協議会による「IR優良企業賞」は、企業の自主開示を促す取組みといえる。',true,
 '正しい。財務諸表の作成過程で抜け落ちる重要な情報をIR情報で補う動きがあり、こうした選定や調査結果の公表は、投資家により親切な自主開示を促すと考えられている。',3172),
('f1-073','2006','基礎','非財務情報は概ね、企業が開示する情報のうち財務諸表で開示されるもの以外を指し、その典型例として有価証券報告書のMD&Aが挙げられる。',true,
 '正しい。MD&A（経営者が財政状態や経営成績を検討・分析したもの）は、有価証券報告書のうち財務諸表以外の部分で開示される非財務情報の典型例である。',3173),
('f1-074','2006','標準','有価証券報告書のMD&Aは財務諸表のパートに含まれるため、財務諸表と同様に監査人の監査対象とされる。',false,
 '誤り。MD&Aなどの非財務情報は有価証券報告書の財務諸表以外の部分に記載され、監査人の監査対象外である。監査対象である財務情報とは厳格に区分されている。',3174),
('f1-075','2006','標準','2018年のディスクロージャーワーキング・グループ報告は、記述情報には、投資家が経営者の目線で企業を理解できるようにする役割があるとしている。',true,
 '正しい。同報告は、記述情報が経営者の視点からの理解を助け、財務情報全体を分析する文脈を与え、収益やキャッシュ・フローを生む基盤の情報を通じて将来業績の確度の判断に役立つとしている。',3175),
('f1-076','2006','応用','2022年のディスクロージャーワーキング・グループ報告は、サステナビリティ情報のうち「戦略」と「指標と目標」を全企業に開示させ、「リスク管理」と「ガバナンス」は重要性の判断に委ねるよう提言した。',false,
 '誤り。提言は逆で、「リスク管理」と「ガバナンス」はすべての企業が開示し、「戦略」と「指標と目標」は各企業が重要性を判断して開示するとされた。',3176),
('f1-077','2006','標準','2022年の報告を受けて、有価証券報告書の記載項目には、男女間賃金格差や女性管理職比率など多様性に関する指標が加えられた。',true,
 '正しい。人的資本については人材育成方針や社内環境整備方針、多様性については男女間賃金格差・女性管理職比率・男性育児休業取得率が記載項目に追加された。',3177),
('f1-078','2006','標準','SSBJ基準の適用義務化は、プライム市場上場企業のうち、過去5事業年度末の平均時価総額が3兆円以上の企業から段階的に始めることが検討されている。',true,
 '正しい。テキストによれば、3兆円以上は2027年3月期、1兆円以上は2028年3月期、5,000億円以上は2029年3月期の報告から順に義務化する方向で検討されている（2026年3月期から任意適用可）。',3178),
('f1-079','2006','基礎','サステナビリティ情報の第三者保証については、監査法人だけが保証業務の実施者として登録できる制度とすることが検討されている。',false,
 '誤り。保証業務の実施者は法人の登録制とし、監査法人だけでなく、要件を満たせば監査法人以外も登録できるとされている。保証は国際基準と整合する基準に準拠して行う。',3179),
('f1-080','2006','標準','財務情報と非財務情報を一つの報告書で有機的に結び付ける統合報告書は、金融商品取引法によって上場企業に作成が義務付けられている。',false,
 '誤り。統合報告書は、両者を一つのストーリーとして示そうとする企業の自発的な取組みとして広がったものであり、法律で作成が義務付けられているわけではない。',3180),
('f1-081','2006','応用','IIRCは2021年にまずIFRS財団と統合し、その後SASBと合併して価値報告財団（VRF）となった。',false,
 '誤り。順序が逆である。IIRCは2021年6月にSASBと合併して価値報告財団（VRF）を設立し、そのVRFが2022年8月にIFRS財団と統合した。',3181),
('f1-082','2006','標準','監査人は、監査した財務諸表を含む開示書類について、財務諸表との重要な相違を見つけるため、非財務情報などのその他の記載内容を通読しなければならない。',true,
 '正しい。監査基準委員会報告書第720号に基づき、監査人は監査対象外のその他の記載内容についても、監査済みの財務諸表との重要な食い違いを見つける目的で通読することが求められる。',3182),
('f1-083','2007','基礎','IFRSはIASBが公表する一連の会計基準であり、IASBが前身のIASCから引き継いだIASも含めてIFRSと呼ぶことがある。',true,
 '正しい。狭義のIFRSは2000年以降にIASB自身が開発した基準を指すが、IASBが現在オーソライズしている基準という意味では、継承したIASも含めてIFRSと称することもある。',3183),
('f1-084','2007','基礎','IASBのボードメンバーは、IASBに資金を提供する各国政府が直接任命している。',false,
 '誤り。IASBのボードメンバーを指名するのはIFRS財団の評議員である。IFRS財団が資金を調達し、IASBは資金提供者の利害に左右されずに基準開発に専念できるとされる。',3184),
('f1-085','2007','標準','IASBの活動が公益に適っているかを確認するモニタリング・ボードは、各法域の証券市場規制当局の代表者によって担われている。',true,
 '正しい。モニタリング・ボードは各法域の証券市場規制当局の代表者が持ち回りで担い、IASBの活動の公益性をチェックする役割を負う。',3185),
('f1-086','2007','基礎','米国の資本市場では、外国企業であってもIFRSに基づいて作成した連結財務諸表を提出することは認められていない。',false,
 '誤り。米国は自国企業にには原則として自国の基準を適用させているが、外国企業についてはIFRSに準拠した連結財務諸表の提出を認めている。',3186),
('f1-087','2007','基礎','EU加盟国内の上場企業は、連結財務諸表をIFRSに準拠して作成することを強制されている。',true,
 '正しい。EU域内上場企業の連結財務諸表へのIFRS強制適用は特筆すべき点であり、これを機にIASBの活動が注目されるようになったといってよい。',3187),
('f1-088','2007','標準','ASBJの修正会計基準第1号「のれんの会計処理」は、のれんを償却せず、減損テストのみを行うことを求めている。',false,
 '誤り。純粋なIFRSは減損に抵触しない限りのれんを簿価で据え置くが、修正会計基準第1号は日本基準と同様に20年以内での規則的な償却と減損処理を求める。',3188),
('f1-089','2007','標準','原則主義的なIFRSでは、抽象的なルールをどう解釈したかの追加説明が必要となるため、日本基準より詳細な注記の開示が求められる傾向がある。',true,
 '正しい。原則主義の下では基本理念の解釈が職業的専門家の判断に任されるため、IFRSでは注記事項や増減表など、日本基準より詳細な開示が求められるとされる。',3189),
('f1-090','2007','標準','IFRSはすべての基準が原則主義的であり、金融商品を扱うIFRS第9号も基本理念だけを示した簡潔な基準となっている。',false,
 '誤り。IFRS第9号は非常に詳細な規定を多く含んでおり、IFRSのすべてが原則主義的だとはいえない。原則主義と細則主義の対比は相対的なものにすぎない。',3190),
('f1-091','2007','応用','取引所の相場がない一部の金融商品にも公正価値の見積りを求めるなど、IFRSは日本基準に比べてストックの適正評価を相対的に重視しているといわれる。',true,
 '正しい。日本基準が主に損益の適正把握に主眼を置くのに対し、IFRSはそれと同程度にストックの適正評価という補完的な要請を重視するといわれ、公正価値を求める範囲の違いに表れる。',3191),
('f1-092','2007','標準','2007年8月の「東京合意」は、ASBJと米国FASBの間で、日本基準と米国基準の差異を解消する目標時期を定めたものである。',false,
 '誤り。東京合意はASBJとIASBの間の合意であり、日本基準とIFRSの重要な差異を2008年までに、残りの差異を2011年6月30日までに解消することを目指した。',3192),
('f1-093','2007','基礎','現行制度で日本企業がIFRSを任意適用するには、上場していることや国際的な財務・事業活動を行っていることを含む3つの要件をすべて満たす必要がある。',false,
 '誤り。任意適用の要件は緩和され、現在はIFRSによる連結財務諸表の適正性確保への取組み・体制整備をしていれば適用できる。上場や国際的な活動は要件ではなくなった。',3193),
('f1-094','2007','応用','東証上場企業に占めるIFRS適用企業の割合は、社数では1割に満たないが、比較的大規模な企業が多いため時価総額で測ると4割を超えている。',true,
 '正しい。IFRS適用企業は社数では10％未満にとどまるが、大企業による任意適用が多く、時価総額ベースの比率は40％を超えている。適用企業数は一貫して増加している。',3194),
('f1-095','2008','基礎','財務諸表の作成責任は経営者にあり、監査人が負うのは財務諸表の適正性について意見を表明する責任であるという役割の区別を、二重責任という。',true,
 '正しい。監査人は適正な財務諸表を作る責任までは負わない。企業の実態を適切に表す財務諸表を作成する責任は経営者にあり、両者の役割の違いを二重責任と呼ぶ。',3195),
('f1-096','2008','標準','経営者には利益を小さく見せる誘因はないため、財務諸表監査はもっぱら利益の水増しを防ぐ目的で必要とされる。',false,
 '誤り。利益連動型報酬やストックオプションは水増しの誘因となる一方、節税の観点からは利益を圧縮する誘因も働く。いずれの方向の恣意的な調整も防ぐため、独立した専門家の監査が必要となる。',3196),
('f1-097','2008','基礎','公認会計士が財務諸表監査で行うべき標準的な手続きは、ASBJが公表する「監査基準」に定められている。',false,
 '誤り。監査の標準的な手続きを定めた「監査基準」は、企業会計審議会が公表したものである。公認会計士は常にこの監査基準への準拠を求められる。',3197),
('f1-098','2008','標準','無限定適正意見の監査報告書には、監査人の意見、意見の根拠、経営者及び監査役等の責任、監査人の責任の各区分の記載が求められる。',true,
 '正しい。無限定適正意見では、この4つの区分を設けて記載する。たとえば経営者の責任の区分には、財務諸表の作成責任や内部統制を整備・運用する責任などが記される。',3198),
('f1-099','2008','標準','財務諸表監査の目的には、企業の内部統制の有効性について意見を表明することも含まれる。',false,
 '誤り。監査人の責任の記載事項として、財務諸表監査の目的は内部統制の有効性について意見を表明するものではないことが明記される。',3199),
('f1-100','2008','応用','重要な監査手続の一部が実施できなかったものの、その影響が財務諸表全体への意見表明を妨げるほどではない場合、監査人は除外事項付きの限定付適正意見を表明する。',true,
 '正しい。この場合、意見の根拠の区分に、実施できなかった監査手続と、その事実が影響する事項を記載する。',3200),
('f1-101','2008','標準','重要な監査手続を実施できず、財務諸表全体について意見を表明する基礎が得られなかった場合、監査人は不適正意見を表明する。',false,
 '誤り。この場合、監査人は意見を表明してはならず、意見不表明となる。意見の根拠の区分には、意見を表明しない旨とその理由が記載される。',3201),
('f1-102','2008','標準','継続企業の前提に関する重要な不確実性があっても、その事項が財務諸表に適切に注記されていれば、監査意見は無限定適正意見となる。',true,
 '正しい。この場合は無限定適正意見だが、監査報告書に継続企業の前提に関する事項の記載が求められる。記載が不適切なら、限定付適正意見または不適正意見となる。',3202),
('f1-103','2008','応用','継続企業を前提に財務諸表を作成することは適切でないと監査人が判断した場合、監査人は意見を表明しないこととされている。',false,
 '誤り。この場合、監査人は継続企業を前提に作成された財務諸表について不適正意見を表明し、そう判断した理由も記載する。',3203),
('f1-104','2008','標準','KAMとは、当年度の監査において監査人が監査役等と協議した事柄のうち、監査人が職業的専門家として特に重要と判断した事項をいう。',true,
 '正しい。KAM（監査上の主要な検討事項）の記載により、監査プロセスの情報が利用者に提供され、監査の透明性や信頼性の向上、経営者との対話の促進、監査の効率化が期待されている。',3204),
('f1-105','2008','基礎','監査報告書にKAMを記載する場合は、監査意見の一部として意見と一体で記載することが求められる。',false,
 '誤り。継続企業の前提に関する事項、KAM、強調事項・説明事項を監査報告書に記載する場合は、それらを監査意見と明確に区分して記載することが求められる。',3205),
('f1-106','2009','基礎','財務報告の質は、利益そのものの質と、利益やそれに関わる情報をどのように提供するかに関わる開示の質とに分けて考えることができる。',true,
 '正しい。財務報告の質は利益の質と開示の質に大別され、両方が高品質であることが望まれる。',3206),
('f1-107','2009','標準','期間配分を行わない生のキャッシュフローは、多額の設備投資をした年度でも投資の成果を的確に表すため、利益より優れた業績指標である。',false,
 '誤り。期間配分をしない生のキャッシュフローは、巨額投資の年度などには成果を的確に反映しない。収支がどの投資の成果や犠牲かを考えて期間配分を行うと、利益はキャッシュフローより優れた業績指標になる。',3207),
('f1-108','2009','標準','投資家との情報格差や利害の不一致を背景に、経営者が利己的な動機から期間配分の手法を使って会計上の利益を歪めることがある。',true,
 '正しい。様々な規律付けがあっても利害を完全には一致させられないため、公表利益が歪められている可能性があり、アナリストは利益調整の誘因を考慮して推測する必要がある。',3208),
('f1-109','2009','標準','ペンマンの整理によれば、売上債権に対する貸倒引当金を増額する操作は、利益を増加させる手段となる。',false,
 '誤り。利益を増やす操作として挙げられているのは、貸倒引当金などの減額であり、これにより収益の増大または販管費の減少がもたらされる。増額は利益を減らす方向に働く。',3209),
('f1-110','2009','応用','期間配分の手法による会計的利益調整が封じられても、企業は取引のタイミング自体を変える実体的利益調整により、利益が帰属する年度を歪めることがある。',true,
 '正しい。会計的利益調整行動を排除するだけでは利益の質は保証されない。取引時期の変更などの実体的利益調整を安価に行えるかどうかも、利益の質に影響する。',3210),
('f1-111','2009','応用','利益の質は、アナリストがpermanent incomeを予測する際に用いるモデルの違いにかかわらず、共通の尺度で一義的に評価すべきものとされる。',false,
 '誤り。持続可能な要素を抽出する手法は投資家によって異なり、利益が備えるべき特性も変わるため、利益の質の評価は一つに定まらない。アナリストは自らのモデルに最も適した尺度で測ることが求められる。',3211),
('f1-112','2009','標準','2018年3月公表の収益認識に関する会計基準により、返品調整引当金の計上が新たに義務付けられた。',false,
 '誤り。企業会計基準第29号「収益認識に関する会計基準」により、返品調整引当金は計上できなくなった。',3212),
('f1-113','2009','標準','ペンマンは会計の質に影響する項目として、会計基準の質や監査の質のほか、取引の質や開示の質を挙げている。',true,
 '正しい。挙げられているのは、基準の質、監査の質、基準の適用の質、取引の質、開示の質の5つであり、基準の開発やエンフォースメントを支える周辺制度の整備も会計の質に影響する。',3213),
('f1-114','2024','基礎','企業会計の利益は、1期間に企業の手元の現金がどれだけ増えたかという金額として計算される。',false,
 '誤り。会計上の利益は、現金の増減ではなく、1期間における資本の増減（資本取引によるものを除く）として計算される。現金収支の差額とは一般に一致しない。',3214),
('f1-115','2024','基礎','利益は一定期間の増減を表すフローの数値であり、資本は特定の時点の大きさを表すストックの数値である。',true,
 '正しい。利益は1期間の資本の増減として求められるフローの数値であり、資本は期首や期末といった一時点の大きさを示すストックの数値である。',3215),
('f1-116','2024','基礎','期首の資産8,000万円・負債5,500万円、期末の資産11,000万円・負債7,200万円の企業で、期中に資本取引がなければ、当期の利益は1,300万円である。',true,
 '正しい。資本＝資産－負債より、期首資本は8,000－5,500＝2,500万円、期末資本は11,000－7,200＝3,800万円。資本取引がないので利益は3,800－2,500＝1,300万円となる。',3216),
('f1-117','2024','標準','企業会計上の資本とは、企業が持つ豊富な資金や高い技術力、優秀な人材といった具体的な経営資源そのものを指す。',false,
 '誤り。そうした日常用語の資本はむしろ会計上の資産に近い。企業会計の資本は資産と負債の差額として算定される抽象的な概念であり、具体的なモノを表すわけではない。',3217),
('f1-118','2024','基礎','勘定記入のルールでは、資産が増加したときは借方（左側）に、負債が増加したときは貸方（右側）に記入する。',true,
 '正しい。資産勘定は増加を借方、減少を貸方に記入し、負債勘定は増加を貸方、減少を借方に記入する。資産と負債では左右の意味が反対になる。',3218),
('f1-119','2024','標準','給料を現金で支払ったときは、現金勘定の貸方に記入するとともに、貸借を一致させるため負債勘定の借方に同額を記入する。',false,
 '誤り。給料の支払いでは現金以外の資産や負債は変化しないため、費用勘定である給料勘定を設けて借方に記入し、貸借を一致させる。',3219),
('f1-120','2024','標準','収益や費用の勘定は、貸借一致のルールの下で取引を記録する際に生じる借方不足や貸方不足を解消するために設けられる名目勘定である。',true,
 '正しい。資産・負債のように実在する対象に対応する実在勘定に対し、収益・費用は不足を埋めるために意図的に設けた名目勘定であり、収益は貸方、費用は借方に増加を記入する。',3220),
('f1-121','2024','基礎','1株150円で取得した自社株100株を1株250円で売却した場合、差額の1万円は有価証券売却益として当期の利益に計上される。',false,
 '誤り。自社株の売買は株主との取引なので資本取引であり、利益には影響しない。売却差額は利益に入れず、その他資本剰余金として処理される。',3221),
('f1-122','2024','標準','配当も借入金の利息も会社から見れば資金調達のコストだが、会計上は、配当は利益を通さず資本から控除し、利息は利益から控除する。',true,
 '正しい。所有者の観点から利益を計算するため、配当は株主の富全体を変えない資本取引として留保利益から控除し、外部者への支払いである利息は費用として利益を減らす。',3222),
('f1-123','2024','応用','300万円の拠出資本のうち半分を減資するために現金200万円を支払った場合、拠出資本の減少額との差額50万円は当期の損失として計上される。',false,
 '誤り。減資は資本取引であり、現金支払額200万円と拠出資本の減少額150万円の差額50万円は利益に反映させず、資本を調整する勘定で処理する。',3223),
('f1-124','2025','基礎','資産や負債の変動だけで取引が完結しない場合には、その差額と同額の影響が収益または費用に生じる。',true,
 '正しい。資産が増えて貸方不足が生じれば収益が、資産が減って借方不足が生じれば費用が同額生じる。資産・負債の動きと収益・費用への影響は原則として切り離せない。',3224),
('f1-125','2025','標準','企業会計では、保有する資産の時価が変動した場合、その価値を直ちに貸借対照表に反映させることが原則とされている。',false,
 '誤り。資産を変動させると貸借対照表の中で完結しない限り収益や費用に影響するため、評価替えで生じる評価損益を他の収益・費用と同様に損益計算書に含めてよいかを検討する必要がある。',3225),
('f1-126','2025','標準','ストック・オプションを付与した場合は、費用の増加と同時に資本が増加するため、資産や負債が増減しない例外的な処理となる。',true,
 '正しい。収益や費用の増減は原則として資産・負債の増減をもたらすが、ストック・オプションの付与時は費用と資本が同時に増加し、資産・負債の増減を伴わない例外となる。',3226),
('f1-127','2025','応用','1台4万円で100台、続いて4.5万円で60台仕入れた商品のうち120台を販売した場合、売上原価は先入先出法で490万円、総平均法で502.5万円となる。',true,
 '正しい。先入先出法では4万円×100台＋4.5万円×20台＝490万円。総平均法の単価は（400万円＋270万円）÷160台＝4.1875万円で、売上原価は×120台＝502.5万円となる。',3227),
('f1-128','2025','応用','帳簿価額100万円の商品の期末時価が120万円になった場合、商品を20万円増額して商品評価益を計上する記録は仕組み上は可能だが、それを収益と認めるかは別の問題である。',true,
 '正しい。取引を擬制してストックの評価額を切り上げることは会計計算の枠組み上可能であるが、生じた評価益を収益として認めるかどうかは実現の考え方に照らして判断される。',3228),
('f1-129','2025','標準','事業活動から収益を記録するための実現の2要件のうち、対価の要件は現金の受取りに限られ、売掛金や受取手形を受け取っただけでは満たされない。',false,
 '誤り。実現の2要件は、製品やサービスの提供と、その対価としての現金または現金等価物の受取りである。売掛金や受取手形は一般に現金等価物とみなされ、販売時点で要件を満たす。',3229),
('f1-130','2025','標準','売上債権が貸倒れになる可能性があっても販売時点で収益を認識し、貸倒れのリスクは事業活動から生じる収益とは切り離して扱うのが一般的である。',true,
 '正しい。企業にとって決定的な事象は製品やサービスの販売であり、代金の回収ではない。このため、現金回収が終わるまで成果を一切認識しないわけではない。',3230),
('f1-131','2025','基礎','自社工場の敷地として使用中の土地に客観的な市場価格があり、それが高騰した場合には、実現の2要件を満たすため評価益を計上できる。',false,
 '誤り。売却するつもりのない事業用の土地の値上がりは、製品の生産・販売でキャッシュを得る事業の目的と無関係であり、客観的な時価があっても実現の2要件から評価益の計上は許されない。',3231),
('f1-132','2025','標準','子会社株式や関連会社株式は時価の値上がりを期待して保有する投資であるため、決算日の時価で評価し、その差額を利益に含める。',false,
 '誤り。子会社・関連会社株式は、親会社に代わって事業を営むための投資であり、時価の上昇を期待した投資ではない。時価評価せず、連結や持分法で処理される。',3232),
('f1-133','2025','応用','従来の日本基準では、未上場株式は換金に制約があり時価も明確でないことから、取得原価で評価されてきた。',true,
 '正しい。換金前に投資が完了したとみなすのは無理があると考えられてきたためである。一方、国際会計基準などでは未上場株式についても何らかの方法で時価を見積もり、時価評価している。',3233),
('f1-134','2026','標準','取得原価900万円、耐用年数3年、残存価額ゼロの設備を定額法で償却すると、1年目末の帳簿価額は300万円となる。',false,
 '誤り。定額法の減価償却費は毎期900万円÷3年＝300万円であり、1年目末の帳簿価額は900－300＝600万円となる。300万円は1年分の償却費であり、配分した残りがストックとして次期に引き継がれる。',3234),
('f1-135','2026','応用','取得原価800万円、総走行可能距離8万kmの車両を生産高比例法で償却する場合、1年目に5万km走行したときの1年目の減価償却費は400万円である。',false,
 '誤り。生産高比例法では走行距離の割合で配分するので、800万円×5万km÷8万km＝500万円となる。400万円は2年で均等に割った定額法の金額である。',3235),
('f1-136','2026','標準','定額法を採用すると、投資初期に償却負担の大きい方法と比べて初期の利益は大きくなるが、後の期には逆に利益が小さくなる。',true,
 '正しい。定額法は初期の費用負担が小さい分、後の期の負担が大きくなり、両方法の関係は逆転する。ただし通算した利益はどの方法でも収支差額の合計と一致する。',3236),
('f1-137','2026','基礎','現行の制度では採用した減価償却方法が注記で開示されるため、投資家はどの方法が採られているかを確認する必要がある。',true,
 '正しい。資産や利益を大きく見せる動機で償却方法が選ばれることもあるため、投資家は注記で採用方法を確かめる必要がある。',3237),
('f1-138','2026','応用','利息のない割引国債を98万円で取得し、1年目末の時価が99.5万円、2年目末に額面100万円で償還された場合、期末に時価評価する方法では1年目の利益は1.5万円となる。',true,
 '正しい。時価評価では1年目に99.5－98＝1.5万円、2年目に100－99.5＝0.5万円の利益となる。通算した2万円は収支差額の合計と一致する。',3238),
('f1-139','2026','応用','利息のない割引国債を97万円で取得し2年後に額面100万円で償還される場合、償還差額を毎年均等に配分する方法では、1年目末の評価額は98.5万円となる。',true,
 '正しい。償還差額3万円を2年間に1.5万円ずつ配分するため、1年目末の評価額は97＋1.5＝98.5万円となる。満期まで保有する意図の債券に用いられる考え方である。',3239),
('f1-140','2026','標準','鉄道会社が決算月の初めに3ヵ月定期券を300万円で販売した場合、当期の売上高は100万円となり、残りの200万円は前受金として翌期に引き継がれる。',true,
 '正しい。現金を受け取ってもサービスを提供するまでは収益を認識できない。サービスが月ごとに均等に提供されるなら当期分は1ヵ月分の100万円で、残りは負債（前受金）となる。',3240),
('f1-141','2026','応用','3年間のアップグレード対価240万円を含むソフトウェアを期首に600万円で販売し、アップグレードは均等に提供される場合、初年度の収益は360万円である。',false,
 '誤り。本体部分360万円は販売時に収益となり、アップグレード対価240万円は3年間に80万円ずつ配分される。初年度の収益は360＋80＝440万円で、残り160万円は負債として繰り延べられる。',3241),
('f1-142','2026','標準','研究開発投資は、成果が表れるか不確実であり、どの収益に対応するかも明確でないため、支出時の年度に費用処理される。',true,
 '正しい。対応の考え方からは製品販売まで繰り延べることも考えられるが、投資の成否に高い不確実性がある支出は、収益が実現する前に費用処理される。',3242),
('f1-143','2026','基礎','会計利益では、売掛金で販売した場合でも代金を回収した時点で収益を計上するため、売上収益と現金収入の間にタイミングのずれは生じない。',false,
 '誤り。収益は製品・サービスの提供と現金等価物（売掛金や受取手形を含む）の受取りで認識されるため、通常は現金の受取りより前の販売時に計上され、売上収益と現金収入にタイミングの差が生じる。',3243),
('f1-144','2026','標準','会計利益には経営者の予測や見積りによる裁量が含まれるが、キャッシュフローは期ごとの変動が大きいため、将来を予測する際には会計利益がよく用いられる。',true,
 '正しい。売上原価と仕入支出、減価償却費と投資支出などの時期のずれが会計利益とキャッシュフローの差を生む。変動の大きいキャッシュフローより会計利益が予測に使われやすい。',3244),
('f1-145','2027','基礎','引当金を設定すると負債の増加に伴い費用を通じて利益が減少し、取り崩すと負債の減少に伴い収益を通じて利益に影響する。',true,
 '正しい。負債の増減も、貸借対照表の中で完結しなければ費用や収益を通じて利益に影響する。負債の会計は資産の会計を裏返して考えればよい。',3245),
('f1-146','2027','標準','社債の発行者が、償還まで毎期時価評価する方法と、発行時の受入額のまま記録する方法のどちらをとるかによって、償還までを通算した利益も異なる。',false,
 '誤り。どちらの方法でも各期の利益は異なるが、償還までの合計の利益は変わらない。負債の処理もキャッシュフローの期間配分として説明できる。',3246),
('f1-147','2027','基礎','前受金や資産除去債務は、銀行からの借入金や社債と同様に、金融負債に分類される負債である。',false,
 '誤り。企業会計の負債は金融負債と非金融負債に大別される。借入金や社債は金融負債だが、前受金、退職給付に係る負債、資産除去債務は一般的な引当金とともに非金融負債に含まれる。',3247),
('f1-148','2027','標準','金融負債のうち時価評価されるのは、随時決済できる市場があり決済に事業上の制約がないものであり、実際にはデリバティブなどごく一部に限られる。',true,
 '正しい。時価変動を狙った金融投資とみられる金融負債は時価評価される。ただしそのような負債は、実際にはデリバティブなどに限られる。',3248),
('f1-149','2027','基礎','償却原価法では、金融負債を償還金額で当初記録し、満期日に当初受け入れた現金の額となるよう毎期調整していく。',false,
 '誤り。償却原価法では、当初に受け入れた現金の額で負債を記録し、満期日に償還金額へ達するよう毎期調整する。時価の変動は業績と関係ないと考えられている。',3249),
('f1-150','2027','標準','負債の会計処理は資産とまったく異なる考え方で行われ、キャッシュフローを期間ごとに配分するという説明は負債には当てはまらない。',false,
 '誤り。負債の会計は資産の会計を裏返して考えればよく、収益・費用・利益との関係も同様に説明できる。利益計算がキャッシュフローを年度間に割り振る作業である点も負債に当てはまる。',3250),
('f1-151','2028','基礎','引当金を計上する根拠は費用収益対応にあり、当期の収益に関係する将来の支出を、見積もったうえで当期の費用として計上する。',true,
 '正しい。たとえば船舶の定期点検の支出は、当期までに提供したサービスと関連するため、支出前でも見積額を当期の費用として記録し、相手勘定として引当金という負債を計上する。',3251),
('f1-152','2028','基礎','5年ごとの定期点検に備えて毎年3億円ずつ特別修繕引当金を繰り入れ、5年目の点検で18億円を支出した場合、引当金15億円を取り崩し、差額3億円を修繕費とする。',true,
 '正しい。5年間の繰入額は3億円×5＝15億円である。実際の支出18億円との差額3億円は見積りを超えた部分として修繕費で処理する。見積りどおりに支出されるとは限らない。',3252),
('f1-153','2028','基礎','引当金を計上している企業には、その金額に見合う現金が将来の支出に備えて社内に積み立てられている。',false,
 '誤り。引当金は将来の支出を現在の費用とするための勘定であり、その金額に相当する現金が存在するわけではない。修繕積立金を預金で積み立てるマンション管理組合の例と混同しないよう注意する。',3253),
('f1-154','2028','標準','当期に過大な引当金を設定し、翌期以降に取り崩して利益を計上する実務もあり得るため、分析では引当ての過少だけでなく過大にも注意が必要である。',true,
 '正しい。決算書の分析では、当期に引き当てるべき費用の見積りが少なすぎないかに加え、将来の戻入益を意図した過大な引当てがないかも確認する必要がある。',3254),
('f1-155','2028','標準','修繕引当金は、5年に1度など数年おきに実施される大規模な修繕に備えて計上される引当金である。',false,
 '誤り。数年おきの大規模修繕に備えるのは特別修繕引当金である。修繕引当金は、毎年実施する修繕を年度内に行えなかったときに計上される。',3255),
('f1-156','2028','基礎','連結貸借対照表に表示される退職給付に係る負債は、かつて退職給付引当金という名称で計上されていた。',true,
 '正しい。退職給付引当金は現在の連結決算書上では退職給付に係る負債として表示される。賞与引当金や工事補償引当金などとともに、よく用いられてきた引当金の一つである。',3256),
('f1-157','2028','標準','引当金の繰入れは、財貨や役務の消費が先に起こり、その後に費用が計上される典型例である。',false,
 '誤り。引当金の繰入れは、財貨や役務の消費に先行して費用や損失を計上する例である。将来の支出を前もって当期の費用とするところに特徴がある。',3257),
('f1-158','2029','標準','資本取引か損益取引かの区別は、キャッシュフローの配り方の違いとは異なり、投資期間を通じた利益の合計額にも影響するため重要である。',true,
 '正しい。配分方法の違いは通算の利益を変えないが、資本取引として資本を直接増減させたものは以後の利益に影響しない。このため資本と利益の区別は極めて重要とされる。',3258),
('f1-159','2029','基礎','現在の企業会計では、純資産と株主資本は同じ意味で用いられ、いずれも資産から負債を差し引いた額として定められている。',false,
 '誤り。純資産は資産から負債を差し引いた額だが、株主資本は純資産のうち株主（報告主体の所有者）に帰属する部分であり、両者の意味は異なる。',3259),
('f1-160','2029','標準','連結貸借対照表の純資産の部は、株主資本、その他の包括利益累計額、株式引受権、新株予約権および非支配株主持分に区分して表示される。',true,
 '正しい。個別貸借対照表では、株主資本、評価・換算差額等、株式引受権、新株予約権が表示され、非支配株主持分は現れない。',3260),
('f1-161','2029','標準','日本基準の株主資本等変動計算書では、株主資本以外の項目も、株主資本と同様に変動要因ごとに区分して表示される。',false,
 '誤り。株主資本は当期首残高から変動要因ごとに加減して当期末残高を示すが、それ以外の項目は変動額を純額で表示しており、株主資本に比重が置かれている。',3261),
('f1-162','2029','標準','株式引受権は、取締役などに自社株式を無償で交付する取引から生じ、交付の有無が確定するまで株主資本とは区別して純資産の部に表示される。',true,
 '正しい。株式引受権は、交付するかどうかが決まるまで、株主資本と区別して純資産の部に計上される項目である。',3262),
('f1-163','2029','標準','個別貸借対照表の評価・換算差額等には、為替換算調整勘定や退職給付に係る調整累計額も含まれる。',false,
 '誤り。個別の評価・換算差額等は、連結のその他の包括利益累計額のうち、為替換算調整勘定と退職給付に係る調整累計額を含まないものに当たる。両者は連結特有の項目である。',3263),
('f1-164','2029','基礎','自社株の取得は株主への払戻しと考えられ、保有する自己株式は株主資本から差し引く形で表示される。',true,
 '正しい。自己株式は連結・個別のいずれでも株主資本から差し引く形で表示される。自社株の売却差額は利益に入れず、その他資本剰余金とする。',3264),
('f1-165','2029','標準','会社法上、新株発行時に株主から払い込まれた金額は全額を資本金としなければならず、一部を資本準備金とすることは認められない。',false,
 '誤り。払込額は原則として全額を資本金とするが、払い込まれた金額の2分の1までは資本準備金とすることができる。',3265),
('f1-166','2029','応用','資本金の減少には原則、株主総会の特別決議と債権者保護手続きが必要だが、資本準備金の減少は普通決議で足りるなど、条件が緩和されている。',true,
 '正しい。資本金は会社法上最も強い拘束を受ける。資本準備金の減少は株主総会の普通決議によるが、債権者保護手続きを要する場合もある。',3266),
('f1-167','2029','標準','繰越利益剰余金から工場新築積立金を積み立てると、その金額に相当する現金預金が会社内に確保されることになる。',false,
 '誤り。任意積立金は分配可能な剰余金の一部を社外に流出させないという意味にすぎず、その分の現金が保管されているわけではない。取り崩しても現金や純資産が増えるわけでもない。',3267),
('f1-168','2029','応用','期首株主資本200、新株発行40、親会社株主に帰属する当期純利益30、剰余金の配当15、利益準備金への繰入3、その他有価証券評価差額金の増加8の場合、期末の株主資本は263である。',false,
 '誤り。期末株主資本は200＋40＋30－15＝255である。利益準備金への繰入は株主資本内部の振替であり、その他有価証券評価差額金はその他の包括利益累計額に属し、株主資本には含まれない。',3268),
('f1-169','2029','応用','期首の利益剰余金120、当期純利益50、利益剰余金からの配当20、任意積立金の積立て15、自己株式の取得10の場合、期末の利益剰余金は150となる。',true,
 '正しい。120＋50－20＝150。任意積立金の積立ては利益剰余金の内部の振替であり、自己株式の取得は株主資本からの控除項目として扱われるため、利益剰余金の残高には影響しない。',3269),
('f1-170','2030','基礎','新株予約権とは、将来、あらかじめ定められた金額で発行会社の新株を取得できる権利をいう。',true,
 '正しい。新株予約権の保有者は、行使期間までに株価が上昇するほど利得が大きくなり、株価が行使価格を下回れば権利は無価値となる。',3270),
('f1-171','2030','基礎','行使価格800円の新株予約権について、行使日の株価が2,000円であれば、行使して直ちに市場で売却することで1株当たり1,200円の利得を得られる。',true,
 '正しい。800円で取得した株式を2,000円で売却すれば、2,000－800＝1,200円の利得となる。株価が行使価格を上回る分だけ保有者は得をする。',3271),
('f1-172','2030','標準','株価が行使価格を下回ったまま行使期日を迎えた場合、新株予約権の価値は株価と行使価格の差額分だけマイナスになる。',false,
 '誤り。株価が行使価格を下回れば市場で買う方が安いので権利は行使されず、新株予約権は無価値となる。マイナスの価値になるわけではない。',3272),
('f1-173','2030','基礎','日本基準では、新株予約権を発行して受け取った払込額は、発行した時点で負債として計上される。',false,
 '誤り。日本基準では、新株予約権は発行時点で株主資本でも負債でもない暫定的な項目として、純資産の部に株主資本とは区別して表示される。',3273),
('f1-174','2030','応用','日本基準で200円で発行した新株予約権が行使され、行使価格900円の払込みを受けて新株を発行した場合、株主資本（拠出資本）は1,100円増加する。',true,
 '正しい。行使時には払込額900円とともに、純資産の部に計上されていた新株予約権200円が拠出資本に振り替えられるため、株主資本は900＋200＝1,100円増加する。',3274),
('f1-175','2030','標準','IFRSや米国基準では、新株予約権が行使されずに失効した場合、払込額は利益に振り替えられる。',false,
 '誤り。米国基準やIFRSでは発行時に新株予約権を拠出資本として記録するため、失効しても拠出資本のままで利益は記録されない。失効時に利益とするのは日本基準の処理である。',3275),
('f1-176','2030','基礎','現行制度では、新株予約権を行使時点の時価で評価し直したうえで、その時価を株主資本に振り替える処理が求められている。',false,
 '誤り。行使時の新株予約権には時価が存在するが、それで評価し直して拠出資本に振り替える処理は現行制度では認められていない。発行時の払込額を振り替える。',3276),
('f1-177','2031','基礎','固定資産の耐用年数をこれまでより長く見積もり直すと、毎期の償却負担が小さくなり、会計利益は大きくなる。',true,
 '正しい。会計処理の方法や見積りを変えると各年度の利益は変わる。アナリストは業績の変化が会計上の変更によるのか、キャッシュフローの変化によるのかを見極める必要がある。',3277),
('f1-178','2031','標準','企業会計基準第24号でいう「会計上の変更」には、会計方針や会計上の見積りの変更は含まれるが、表示方法の変更は含まれない。',false,
 '誤り。会計上の変更は、会計方針の変更、表示方法の変更、会計上の見積りの変更を合わせたものである。過去の誤謬の訂正はこれとは別に扱われる。',3278),
('f1-179','2031','標準','過去に入手可能だった情報を使わなかったり誤用したりしたために生じた財務諸表の誤りを誤謬といい、発見された場合は過去の財務諸表を修正再表示する。',true,
 '正しい。誤謬は会計上の変更とは区別され、過去の財務諸表に訂正を反映させる遡及処理（修正再表示）が行われる。',3279),
('f1-180','2031','標準','表示方法を変更した場合、過去の財務諸表は組み替えず、変更した期以降の財務諸表から新しい表示方法を適用する。',false,
 '誤り。表示方法を変更した場合は、原則として表示する過去の財務諸表を新たな表示方法に従って組み替える。これにより財務諸表全般の比較可能性が向上すると考えられる。',3280),
('f1-181','2031','応用','減価償却方法の変更は会計方針の変更に当たるため、過去の財務諸表に遡って新しい方法を適用することが求められる。',false,
 '誤り。減価償却方法の変更は本来は会計方針の変更だが、見積りの変更と見分けにくいため見積りの変更と同じ扱いとなり、遡及処理は求められない。',3281),
('f1-182','2031','応用','取得原価800万円・残存価額ゼロ・定額法で当初の耐用年数を10年としていた資産について、3年目期首に総耐用年数を8年に見直した場合、プロスペクティブ方式では3年目以降の減価償却費は毎期100万円である。',false,
 '誤り。プロスペクティブ方式では2年目末の簿価640万円（800－160）を残り6年で償却するため、毎期約106.7万円となる。100万円は総耐用年数8年で計算し直したレトロスペクティブ方式の金額である。',3282),
('f1-183','2031','応用','取得原価800万円・残存価額ゼロ・定額法の資産で、3年目期首に総耐用年数を10年から8年に見直す場合、キャッチ・アップ方式では3年目に40万円の特別損失が計上される。',true,
 '正しい。旧来の2年目末簿価は800－160＝640万円、8年で計算し直した簿価は800－200＝600万円で、差額40万円を特別損失とし、以後は毎期100万円を償却する。',3283),
('f1-184','2031','標準','貸倒引当金の見積額を変更した場合、会計上の見積りの変更として、その影響は過去の期間に遡って修正される。',false,
 '誤り。見積りの変更は新しい情報によるものと考えられるため遡及処理せず、影響は当期以降に認識する。貸倒引当金の見積変更は当期だけに、耐用年数の変更は当期と将来に影響する。',3284),
('f1-185','2032','基礎','企業会計基準委員会の概念フレームワークは、2004年の公表時も、2006年に表現を見直した際も、正式な会計基準ではなく討議資料という位置づけであった。',true,
 '正しい。いずれも討議資料であり最終的な公表物ではないが、基準設定の際に参照され、会計基準の議論に一定の役割を果たしている。',3285),
('f1-186','2032','標準','「概念フレームワーク」は、資産の測定値について、市場価格で測るのが難しい場合に限り取得原価を用いるという優先順位を定めている。',false,
 '誤り。資産の測定値として取得原価、市場価格、割引価値、入金予定額などが列挙されているが、どれを優先すべきかは示されておらず、取得原価なども積極的に並列させている。',3286),
('f1-187','2032','標準','「概念フレームワーク」は財務報告の目的を、投資家の意思決定に役立てるため、投資のポジションと成果を測定し開示することに置いている。',true,
 '正しい。投資のポジションとその成果は、貸借対照表の財政状態と損益計算書の経営成績にほぼ相当する。投資家の意思決定に資することを第一に掲げている点が注目される。',3287),
('f1-188','2032','基礎','「概念フレームワーク」によれば、財務報告の役割は、企業価値そのものを算定して投資家に開示することにある。',false,
 '誤り。会計情報には企業価値の推定に役立つことが期待されるが、企業価値の見積り自体は投資家が行うものであり、会計情報はその基礎を提供するにすぎない。財務報告の目的は原則として事実の開示にある。',3288),
('f1-189','2032','標準','「概念フレームワーク」では、配当規制や課税所得の算定といった利害調整への利用が、財務報告の主目的とされている。',false,
 '誤り。利害調整は会計情報の副次的な用途と位置付けられ、基準の設定・改廃の際にその影響も考慮すべきとされるにとどまる。主目的は投資家の意思決定に資する情報の提供である。',3289),
('f1-190','2032','基礎','意思決定有用性を下位から直接支える2つの特性は、内的整合性と比較可能性であるとされている。',false,
 '誤り。意思決定有用性を下位から支えるのは意思決定との関連性と信頼性である。内的整合性と比較可能性は階層全体にかかる一般的制約の特性で、有用性を間接的に推定する際に用いられる。',3290),
('f1-191','2032','標準','「概念フレームワーク」では、信頼性を支える特性として、検証可能性、中立性、表現の忠実性が挙げられている。',true,
 '正しい。一部の関係者の利害を偏重しないこと（中立性）、測定者の主観に左右されないこと（検証可能性）、事実と会計上の分類の対応が明確なこと（表現の忠実性）が信頼性を支える。',3291),
('f1-192','2032','応用','新しい取引に関する個別基準を作る際に、関連性や信頼性を事前に判断しにくい場合は、既存の基準体系との内的整合性を確かめることで間接的に推定できるとされる。',true,
 '正しい。内的整合性とは個別の会計基準が基準体系の根本的な考え方と食い違わないことであり、その判断を通じて関連性や信頼性を間接的・補完的に推定できる。',3292),
('f1-193','2032','応用','「概念フレームワーク」は、IFRSなど海外の概念フレームワークと同様に、純利益を独自に定義せず、包括利益だけを定義している。',false,
 '誤り。投資家の利用目的に合うよう、包括利益とは別に純利益も定義し、これに関連付けて収益と費用を定義している。この点は海外の概念フレームワークとの大きな違いである。',3293),
('f1-194','2032','標準','「概念フレームワーク」が自己創設のれんの計上を認めないのは、それが経営者自身による企業価値の評価・申告にあたり、財務報告の目的に反するためである。',true,
 '正しい。自己創設のれんは資産の定義を満たし得るものの、定義への当てはめより先に財務報告の目的や財務諸表の役割に合うかが問われ、目的に反するとして資産に含めない。',3294),
('f1-195','2033','標準','包括利益では資産と負債の評価額を先に決め、その差額の変動から資本取引による分を除いたものを利益とするため、実現や対応の概念を必ずしも用いない。',true,
 '正しい。純利益は実現や対応に基づいて収益・費用を決めるのに対し、包括利益は資産・負債の評価から導かれる。このため、その他有価証券の評価差額などで両者の扱いが分かれる。',3295),
('f1-196','2033','基礎','包括利益の表示に関する会計基準は、連結財務諸表に加えて個別財務諸表でも包括利益を開示することを求めている。',false,
 '誤り。この基準は2010年6月に定められ、連結財務諸表では2011年3月決算期から適用されたが、個別財務諸表での包括利益の開示は当面見送られたままである。',3296),
('f1-197','2033','応用','IFRSは、未実現利得を認識時と実現時の2回にわたり包括利益に含めないよう、実現した金額をその他の包括利益から控除するとしており、これは包括利益を重視する意味でのリサイクリングといえる。',true,
 '正しい。リサイクリングには、OCIを実現時に純利益へ振り替える意味（純利益重視）と、OCIを減少させる意味（包括利益重視）がある。IFRS第18号の記述は後者の意味でも用いている。',3297),
('f1-198','2033','標準','IFRSでは、その他の包括利益累計額は利益剰余金と区別され、資本の外に表示される。',false,
 '誤り。IFRSでは、その他の包括利益累計額も「その他の資本の構成要素」という形で資本の中に含められ、利益剰余金と並んで表示される。純利益を業績指標と位置付ける立場をとっていないためである。',3298),
('f1-199','2033','標準','IFRSでは、支払い義務のない項目は負債ではなく資本と考えるため、非支配株主持分や新株予約権も資本に含められる。',true,
 '正しい。IFRSは資産と負債の差額から資本を導くアプローチをとるため、本来の意味での所有者の請求権とはいえない部分も資本に入る。日本基準ではこれらを株主資本と区別する。',3299),
('f1-200','2033','応用','日本基準がのれんを規則的に償却する主な理由は、のれんの耐用年数や減価のパターンを正確に予測できるからである。',false,
 '誤り。日本基準の主な論拠は、のれんも投資原価に含まれ、企業結合後の利益はその投資原価を上回って回収された余剰だという考え方にある。見積りの難しさは有形固定資産の償却にも共通する。',3300),
('f2-021','2010','基礎','有価証券報告書の提出義務を負うのは株式を上場している会社に限られ、社債券の募集だけを行う会社が対象となることはない。',false,
 '誤り。1億円以上の有価証券（株券だけでなく社債券なども含む）の募集・売出しで有価証券届出書の提出を求められた会社も、有価証券報告書の提出義務を負う。',4121),
('f2-022','2010','標準','過去5年間のいずれかの事業年度末に株券の保有者が1,000人以上となった会社は、資本金5億円未満の会社を除き、有価証券報告書を提出しなければならない。',true,
 '正しい。上場会社・店頭登録会社・一定の募集等を行った会社に加え、株券等の保有者が1,000人以上に達した経験のある会社（資本金5億円未満は除く）も提出義務の対象となる。',4122),
('f2-023','2010','基礎','有価証券報告書の「主要な経営指標等の推移」には連結ベースの指標だけが記載され、個別ベースの指標は記載されない。',false,
 '誤り。連結・個別の両ベースで指標が示される。個別ベースでは株価収益率や配当性向、期中の最高・最低株価なども示される。',4123),
('f2-024','2010','基礎','有価証券報告書は統一された書式で作成されるため、他の手段で発信される企業情報に比べて企業間比較や時系列比較を行いやすい。',true,
 '正しい。企業が発信する情報は形式が多様だが、有価証券報告書は書式が統一されているので、他社との比較や過去との比較がしやすい。',4124),
('f2-025','2010','標準','会計方針を変更して遡及適用した場合には、「主要な経営指標等の推移」に載せる過去の年度の数値も、新しい会計方針で計算し直したものになる。',true,
 '正しい。遡及適用を伴う方針変更があれば、推移表に並ぶ過去の数値もすべて新しい方針によって計算し直され、比較可能性が保たれる。',4125),
('f2-026','2010','標準','MD&Aの名称に「経営者による」の語が付け加えられたのは、MD&Aでは客観的な事実の提示に徹し、経営者自身の解釈を交えないことを明確にするためである。',false,
 '誤り。2018年の内閣府令改正で「経営者による」が加えられたのは、事実を並べるだけでなく、経営者自身が説明し解釈を加えるべきだという趣旨である。',4126),
('f2-027','2010','標準','有価証券報告書のリスク情報には当該企業に固有のリスクだけが記載されているので、アナリストは記載された内容を取捨選択せずにそのまま評価に使えばよい。',false,
 '誤り。近年はリスク情報を網羅的に示そうとするため、一般的に存在するリスクまで記載されている場合がある。分析にあたっては重要なリスクを見極めて選び取る必要がある。',4127),
('f2-028','2010','標準','「サステナビリティに関する考え方及び取組」では、多様な人材の確保を含めた人材育成方針などについて、その指標の内容と指標を用いた目標・実績の記載が必須とされている。',true,
 '正しい。戦略と指標・目標は重要なものを記載するのが基本だが、人材育成方針や社内環境整備方針と、それに関する指標・目標・実績は必ず記載しなければならない。',4128),
('f2-029','2010','標準','配当性向を毎期一定に保つ配当政策を採る企業では、将来の配当によるキャッシュ・アウトフローは業績にかかわらずほぼ一定になると予想される。',false,
 '誤り。配当性向を一定とする政策では、将来の業績に比例して配当のキャッシュ・アウトフローが増減すると考えられる。一定の流出が予定されるのは安定配当政策の場合である。',4129),
('f2-030','2010','基礎','有価証券報告書の「第5 経理の状況」には、連結財務諸表と個別財務諸表のほか、それらの注記や附属明細表が収められている。',true,
 '正しい。経理の状況には連結・個別の財務諸表とその注記・附属明細表が掲載され、中心となる財務諸表は連結財務諸表とされている。',4130),
('f2-031','2010','標準','分析対象の上場企業に親会社が存在する場合には、当該企業の方針に親会社の意向が強く作用し得るため、「提出会社の参考情報」に示される親会社についても分析することが求められる。',true,
 '正しい。日本では子会社が上場している例が少なくない。親会社があればその意向が将来の方針に影響するので、親会社の分析も必要となる。',4131),
('f2-032','2010','応用','2023年11月の金融商品取引法改正により第1・第3四半期の四半期報告書が廃止されたため、上場企業の四半期ごとの開示は行われなくなった。',false,
 '誤り。四半期の開示は取引所規則による四半期決算短信へまとめられたのであり、四半期開示自体がなくなったわけではない。第2四半期分は半期報告書として提出が続く。',4132),
('f2-033','2011','基礎','期中に資本取引が行われていなければ、期末純資産は期首純資産に当期の収益と費用の差額を加えた金額となる。',true,
 '正しい。資本取引がない場合、純資産の増加は収益、減少は費用として記録されるので、期末純資産＝期首純資産＋（収益－費用）が成り立つ。',4133),
('f2-034','2011','基礎','残高試算表では、「期末資産＋収益＝期末負債＋期首純資産＋費用」という関係が成り立つことが帳簿残高で確かめられる。',false,
 '誤り。成り立つ関係は「期末資産＋費用＝期末負債＋期首純資産＋収益」である。費用は借方、収益は貸方に集計される。',4134),
('f2-035','2011','標準','資本取引がない場合、期首と期末の純資産の差額として求める財産法の当期純利益と、収益と費用の差額として求める損益法の当期純利益は、複式簿記では一致する。',true,
 '正しい。残高試算表をストック（貸借対照表）とフロー（損益計算書）に分けると、それぞれの差額である当期純利益は一致する。',4135),
('f2-036','2011','基礎','当期純利益を介して貸借対照表と損益計算書がつながっている関係は、「連結（consolidation）」と呼ばれる。',false,
 '誤り。この関係は貸借対照表と損益計算書の「連携（articulation）」と呼ばれる。連結は企業集団の財務諸表を作成する手続きを指す用語である。',4136),
('f2-037','2011','標準','純資産直入の処理があると、資本取引のない期であっても、純資産の期首から期末への増減額と、収益から費用を引いた額とが食い違う。',true,
 '正しい。損益を通さずに純資産が増減するためである。連結財務諸表では、このずれを説明するために包括利益計算書が作成される。',4137),
('f2-038','2011','標準','損益計算書は、包括利益計算書を媒介として、貸借対照表の純資産の部の利益剰余金と結び付いている。',false,
 '誤り。当期純利益が利益剰余金に加減算される計算は株主資本等変動計算書の中で示されるので、損益計算書は株主資本等変動計算書を媒介として貸借対照表と結び付く。',4138),
('f2-039','2011','標準','株主資本等変動計算書には当期純利益とその他の包括利益の両方が純資産の増減として現れるので、包括利益計算書の内容はすべて株主資本等変動計算書に含まれていると考えることができる。',true,
 '正しい。包括利益の計算要素はともに株主資本等変動計算書に現れるので、包括利益計算書はその部分集合といえ、同計算書を通じて貸借対照表ともつながる。',4139),
('f2-040','2011','基礎','キャッシュ・フロー計算書は、前期末と当期末の貸借対照表を、現金及び現金同等物の残高を通じてつないでいる。',true,
 '正しい。キャッシュ・フロー計算書は現金及び現金同等物の期中変動の原因を説明するので、前期末と当期末の残高をつなぐ役割を持つ。',4140),
('f2-041','2011','標準','現金及び現金同等物の変動は純資産の変動とは無関係であるため、キャッシュ・フロー計算書と損益計算書との間に相互関係は成り立たない。',false,
 '誤り。両者に直接の関連はないが、貸借対照表等式を通じて現金及び現金同等物の変動は純資産の変化と結び付き、損益計算書とも関連する。すべての財務諸表は相互に関連している。',4141),
('f2-042','2011','応用','期首純資産が800、期中に増資150と配当60が行われ、当期純利益が200でその他の包括利益がゼロであれば、期末純資産は1,090となる。',true,
 '正しい。期末純資産＝期首800＋増資150－配当60＋当期純利益200＝1,090。資本取引による増減と当期純利益の両方を加減する。',4142),
('f2-043','2011','応用','前期末の資産3,000・負債1,800、当期末の資産3,900・負債2,200で、期中の資本取引は配当100の支払いのみ、その他の包括利益はゼロの場合、当期純利益は500である。',false,
 '誤り。期首純資産1,200、期末純資産1,700で差額は500だが、配当100で純資産が減っているので、当期純利益＝1,700－1,200＋100＝600となる。',4143),
('f2-044','2011','標準','発生主義のもとでは当期純利益が期中の現金残高の増減と一致するため、利益を計上している企業が支払不能に陥ることはない。',false,
 '誤り。発生主義では収益・費用の認識が現金の出入りと別に行われるため、当期純利益と現金残高の増減は一致しない。利益を計上しながら倒産する黒字倒産も起こり得る。',4144),
('f2-045','2012','基礎','連結財務諸表は企業集団を構成する企業の財務諸表を合算して作成されるので、子会社ごとの業績の違いも連結財務諸表からそのまま読み取ることができる。',false,
 '誤り。合算によって企業集団内の企業間の差異が相殺されてしまう可能性がある。このため、事業内容ごとに区分したセグメント情報が必要になる。',4145),
('f2-046','2012','基礎','個別財務諸表で製造原価明細書を開示する必要がなくなるのは、その企業が連結財務諸表でセグメント情報を開示している場合である。',true,
 '正しい。セグメント情報を開示している企業には製造原価明細書を開示しなくてよい。その分、製造活動について入手できる情報は限られる。',4146),
('f2-047','2012','基礎','2010年4月以降に開始する事業年度においても、セグメント情報の開示が求められるのは連結財務諸表を作成している企業に限られる。',false,
 '誤り。2010年4月以降開始の事業年度では、連結財務諸表を作らない会社でも、個別財務諸表の注記でセグメント情報を示すことが求められる。',4147),
('f2-048','2012','基礎','事業セグメントとして識別されるための要件の一つに、その構成単位についてその単位について区分された財務情報が得られることがある。',true,
 '正しい。事業セグメントは、収益を獲得し費用が発生する事業活動に関わること、最高経営意思決定機関が経営成績を定期的に検討すること、区分された財務情報が得られることのすべてを満たす構成単位である。',4148),
('f2-049','2012','基礎','セグメント情報における最高経営意思決定機関には、取締役会のような会議体が該当する場合のほか、CEOやCOOといった個人が該当する場合もある。',true,
 '正しい。最高経営意思決定機関は、取締役会・執行役員会議といった合議体のことも、CEO・COOといった個人のこともある。',4149),
('f2-050','2012','標準','事業セグメントとして識別されるためには、会計基準に列挙された要件のうち、いずれか1つを満たしていれば足りる。',false,
 '誤り。収益獲得・費用発生に関わる事業活動であること、最高経営意思決定機関が業績を定期的に検討していること、分離された財務情報が入手できることの要件すべてに該当する必要がある。',4150),
('f2-051','2012','標準','経営者が社内で実際に使っている区分に沿って作るマネジメント・アプローチのセグメント情報は、作成のための追加負担が軽く、区分の決め方に恣意性が入り込みにくいという利点がある。',true,
 '正しい。経営者用に作成済みの情報を使うので新たな負担が小さく、最高経営意思決定機関で実際に用いられている区分であることから恣意性も入りにくい。',4151),
('f2-052','2012','標準','売上高（セグメント間の内部売上高を含む）がすべての事業セグメントの売上高合計の5％以上である事業セグメントは、報告セグメントとしなければならない。',false,
 '誤り。量的基準は10％である。売上高、利益または損失の絶対値、資産のいずれかが所定の合計額の10％以上であれば報告セグメントとする。',4152),
('f2-053','2012','応用','利益が生じている事業セグメントの利益合計が800、損失が生じている事業セグメントの損失合計の絶対値が1,000の企業において、損失120を計上している事業セグメントは、利益・損失の基準により報告セグメントとなる。',true,
 '正しい。基準額は800と1,000のいずれか大きい1,000であり、その10％は100となる。損失の絶対値120は100以上なので報告セグメントとなる。',4153),
('f2-054','2012','基礎','報告セグメントの外部顧客への売上高の合計が損益計算書の売上高の90％未満である場合には、90％以上になるまで報告セグメントを追加しなければならない。',false,
 '誤り。追加識別の基準は75％である。報告セグメントの外部顧客への売上高合計が損益計算書の売上高の75％以上になるまで報告セグメントを追加する。',4154),
('f2-055','2012','標準','報告セグメントの区分を変更した企業は、前年度分のセグメント情報も新しい区分に組み替えて開示する必要がある。',true,
 '正しい。区分変更により時系列比較ができなくなるのを防ぐため、前年度のセグメント情報を変更後の区分で組み替えて開示することが求められる。',4155),
('f2-056','2012','標準','各報告セグメントの負債の額は、最高経営意思決定機関に定期的に提供されているか否かにかかわらず、すべての企業が開示しなければならない。',false,
 '誤り。開示が必須なのは各報告セグメントの利益（または損失）と資産の額である。負債の額は、その情報が最高経営意思決定機関に定期的に提供され使用されている場合に開示する。',4156),
('f2-057','2012','標準','損益計算書に固定資産の減損損失を計上している企業は、最高経営意思決定機関に報告しているかどうかを問わず、報告セグメントごとの減損損失を開示しなければならない。',true,
 '正しい。セグメント別の減損損失やのれんの償却額は将来キャッシュフローの予測に有用と考えられるため、最高経営意思決定機関への提供の有無を問わず開示が求められる。',4157),
('f2-058','2012','標準','地域に関する情報では、海外の外部顧客への売上高を、近接するいくつかの国をまとめた地域単位で開示することが求められている。',false,
 '誤り。近隣国をまとめた開示は要求されていない。まとめると、国によって違う経済情勢や政治リスクが一括りにされてしまうからである。',4158),
('f2-059','2013','基礎','継続企業の前提とは、特に問題がない限り企業活動が将来にわたって継続するという前提であり、固定資産の減価償却のような会計処理もこの前提に依拠している。',true,
 '正しい。例えば耐用年数30年で減価償却するのは、企業が少なくとも30年間活動を続けることを前提にしているからである。',4159),
('f2-060','2013','標準','継続企業の前提に重要な疑いを抱かせる事象が存在すれば、経営者の対応策によって重要な不確実性が解消された場合でも、継続企業の前提に関する注記を行わなければならない。',false,
 '誤り。注記が求められるのは、その事象・状況への対応策を講じた後でも、なお継続企業の前提について重要な不確実性が残る場合である。',4160),
('f2-061','2013','基礎','継続企業の前提に関する注記には、重要な疑義がある旨やその中身のほか、疑義を解消・改善するための経営者の対応策も記載される。',true,
 '正しい。注記では、疑義の中身、経営者の対応策、対応後も残る重要な不確実性とその理由、およびその影響が示される。',4161),
('f2-062','2013','標準','会計方針の決定には企業の裁量が認められているので、企業は継続性の原則にとらわれず、毎期自由に会計方針を選び直すことができる。',false,
 '誤り。会計方針は会計監査の対象であり、適正であることと継続性の原則の遵守が求められる。多様性が認められていても恣意的に変更できるわけではない。',4162),
('f2-063','2013','標準','重要な会計方針の注記では、有価証券や棚卸資産の評価基準・評価方法のほか、引当金の計上基準や収益及び費用の計上基準なども説明される。',true,
 '正しい。注記対象には固定資産の減価償却方法や外貨建資産・負債の換算基準なども含まれる。なお重要性の乏しいものは注記を省略できる。',4163),
('f2-064','2013','応用','固定資産の取得初期には、定率法を採用している企業の方が定額法を採用している企業よりも減価償却費が小さくなるため、期間利益は大きくなる。',false,
 '誤り。定率法は初期の費用額を大きくし、その後次第に減らしていく方法である。取得初期には定率法の方が減価償却費が大きく、期間利益は小さくなる。',4164),
('f2-065','2013','標準','定率法を採用している企業では、減価償却費が年々減少していくため、同じ資産を定額法で償却している場合と比べて、後年度の利益が大きくなる傾向がある。',true,
 '正しい。減価償却方法の違いは当年度だけでなく将来の利益にも影響する。将来予測を行う際には、会計方針の注記でこの点を確認する必要がある。',4165),
('f2-066','2013','基礎','連結財務諸表の注記では、連結の範囲や持分法の適用に関する事項は示されるが、連結子会社の事業年度に関する事項は示されない。',false,
 '誤り。連結の基礎となる重要事項として、連結範囲、持分法の適用状況、連結子会社の決算期などに関する事項が注記される。',4166),
('f2-067','2013','標準','財務諸表本表では相殺後の金額しか分からない繰延税金資産・負債について、税効果会計に関する注記ではその内訳が発生原因別に示される。',true,
 '正しい。繰延税金資産・負債が将来キャッシュフローに与える影響は構成要素ごとに異なるため、発生原因別の内訳が注記される。',4167),
('f2-068','2013','標準','同一納税主体の繰延税金資産と繰延税金負債は、財務諸表本表において相殺せずにそれぞれ総額で表示される。',false,
 '誤り。財務諸表本表では、同一納税主体の税支出の減少となる繰延税金資産と増加となる繰延税金負債は相殺して表示される。内訳は税効果会計の注記で確認する。',4168),
('f2-069','2013','標準','企業結合の注記からは、当期のM&Aで受け入れた資産・負債の内訳や、そのM&Aで生じたのれんの額を知ることができる。',true,
 '正しい。貸借対照表本表では自社の活動による増減とM&Aによる増加が合算されているため、注記によってM&Aの影響を切り分けて評価できる。',4169),
('f2-070','2013','応用','後発事象のうち、その実質的な原因が決算日より後に発生したものは、決算上の見積りを修正するため財務諸表本表の数値を修正して反映する。',false,
 '誤り。原因が決算日より後に発生した後発事象の影響は財務諸表には反映されず、その情報は注記から得るしかない。財務諸表を修正するのは、原因が決算日時点で既に存在していた場合である。',4170),
('f2-071','2013','標準','決算日後に発生した事象であっても、その実質的な原因が決算日現在で既に存在しており、決算での判断や見積りの見直しが必要になるときは、財務諸表の数値そのものを修正する。',true,
 '正しい。原因が決算日時点で存在していた後発事象は財務諸表の修正を要する。原因そのものが決算日より後に生じたときは、重要なものを注記で開示する。',4171),
('f2-072','2013','基礎','上場企業は、個別財務諸表の附属明細表として有価証券明細表を作成しなければならない。',false,
 '誤り。個別財務諸表には有価証券明細表、有形固定資産等明細表、社債明細表、借入金等明細表、引当金明細表、資産除去債務明細表が添付されるが、上場企業は有価証券明細表の作成を免除されている。',4172),
('f2-073','2014','基礎','損益計算書では純額主義が原則とされ、同じ取引に関わる収益と費用は相殺して差額だけを表示する。',false,
 '誤り。損益計算書には原則として総額主義が適用され、収益と費用はそれぞれ総額で表示する。ただし有価証券売却損益や固定資産売却損益など純額で表示される項目もある。',4173),
('f2-074','2014','標準','売上高と広告宣伝費の対応のように、特定の資産ではなく一定期間の企業活動を仲立ちにして収益と費用を結び付ける方式は、間接的対応（期間的対応）と呼ばれる。',true,
 '正しい。売上高と売上原価のように特定の資産を媒介とするのが直接的対応（個別的対応）、期間の活動を媒介とするのが間接的対応（期間的対応）である。',4174),
('f2-075','2014','基礎','売上高は、総売上高から売上値引・戻り高を差し引いて表示され、大量取引を理由に代金を減額する売上割戻も売上高から控除される。',true,
 '正しい。売上値引・戻り高は収益の取消とみなされるため控除され、売上割戻も売上高から差し引かれる。',4175),
('f2-076','2014','標準','販売費と一般管理費は性格が異なる費用であるため、損益計算書上は両者をはっきり分けて示さなければならない。',false,
 '誤り。販売活動と管理活動は現実には一体として行われることが多いため、両者をはっきり分けることは要求されておらず、「販売費及び一般管理費」として一括して示される。',4176),
('f2-077','2014','標準','販売費及び一般管理費に含まれる修繕費は、当期に支出を抑制すれば、将来の費用も減少する傾向がある項目である。',false,
 '誤り。修繕費は当期に抑制した結果、後の期の費用が膨らむおそれのある項目である。そのため経営成績の評価では販売費及び一般管理費の内訳にも注意が必要である。',4177),
('f2-078','2014','基礎','仕入代金を早期に支払ったことで代金の一部の減額を受ける仕入割引は、売上原価から控除して表示する。',false,
 '誤り。仕入割引は資金の運用に伴う収益とみなされ、営業外収益に計上される。同様に、売上債権の早期回収に伴う売上割引は営業外費用となる。',4178),
('f2-079','2014','基礎','資金調達に関連する支出であっても、自社の株主に支払う配当は営業外費用には含まれない。',true,
 '正しい。営業外費用の中心は支払利息だが、株主への配当は剰余金の分配であり、損益計算書には計上されない。',4179),
('f2-080','2014','応用','株式の25％を保有する関連会社が当期純利益400億円を計上した場合、投資会社の連結損益計算書には持分法投資利益100億円が営業外収益として計上される。',true,
 '正しい。持分法投資損益は被投資会社の当期純利益に所有割合を乗じた額であり、400億円×25％＝100億円が営業外収益に計上され、投資勘定にも加算される。',4180),
('f2-081','2014','標準','経常損益は臨時的な項目を含む企業活動全体の成果を示すため、将来の業績を予測するうえでは当期純利益よりも重要性が低いと考えられている。',false,
 '誤り。経常損益は反復的に実施される活動の成果であり、臨時的な特別損益を含まない。活動が将来も続くなら、将来業績の予測に最も重要な利益数値と考えられている。',4181),
('f2-082','2014','標準','売却目的で保有していない有形固定資産の売却損益でも、その売却が毎期くり返し行われているなら、特別損益とせずに営業外収益・営業外費用に含めることができる。',true,
 '正しい。特別損益は臨時的な項目を経常損益から除くための区分なので、継続的に発生する売却損益や金額が僅少なものは営業外項目に含められる。',4182),
('f2-083','2014','標準','2011年4月以降に開始する事業年度では、過去の収益・費用の修正が必要であると当期に判明した場合、「前期損益修正」として当期の特別損益に計上する。',false,
 '誤り。2011年4月以降に開始する事業年度からは、過去の財務諸表そのものを修正する。重要性が乏しく修正しない場合は、性質に応じて営業損益または経常損益の区分に含める。',4183),
('f2-084','2014','標準','2015年3月決算以前の連結損益計算書で「当期純利益」として表示されていた金額は、現在の連結損益計算書の「親会社株主に帰属する当期純利益」に相当する。',true,
 '正しい。かつては少数株主損益調整前当期純利益から少数株主利益を差し引いた額が当期純利益とされていた。時系列比較の際は、表示内容の違いに注意が必要である。',4184),
('f2-085','2014','標準','EBITは性格が営業利益に似た指標であり、有価証券の売却損益や特別利益・特別損失は算入されない。',false,
 '誤り。EBITは利息と税金を差し引く前の当期純利益であり、有価証券売却損益などの投資活動の成果や特別利益・特別損失も含まれている点が営業利益と異なる。',4185),
('f2-086','2014','標準','非GAAP指標は計算方法が統一的に定められておらず、同じ名称でも企業によって計算が異なり得るため、企業間のクロス・セクション分析には使いにくい。',true,
 '正しい。EBITDAやコア利益などの非GAAP指標は経営者の裁量が作用しやすい。開示している意図を読み取ったうえで評価に使うかを判断する必要がある。',4186),
('f2-087','2015','基礎','日本基準では、包括利益の計算・表示は、連結財務諸表だけでなく個別財務諸表においても求められている。',false,
 '誤り。企業会計基準第25号により包括利益の表示が求められるのは連結財務諸表であり、個別財務諸表では当面の間、包括利益の表示は求めないとされている。',4187),
('f2-088','2015','標準','包括利益の概念は、1980年に米国の財務会計基準審議会（FASB）が公表した財務会計概念書第3号で示されたものである。',true,
 '正しい。同概念書では当期純利益は定義されず、非所有者との取引等から生じた1期間の持分（純資産）の変動として包括利益が定義された。',4188),
('f2-089','2015','標準','収益費用中心観では、資産としての実在が確認できないことを理由に繰延資産の計上は認められない。',false,
 '誤り。繰延資産の計上を認めないのは資産負債中心観である。収益費用中心観では、適正な期間損益計算を重視して繰延資産の計上を認める。',4189),
('f2-090','2015','標準','クリーンサープラス関係とは、資本取引による増減を除いた一期間の資本の増減額と、同じ期間の利益とが一致する関係をいう。',true,
 '正しい。日本基準では純資産との間でこの関係が成り立つ利益が包括利益とされ、その表示によってストックとフローの情報がつながる。',4190),
('f2-091','2015','標準','「財務会計の概念フレームワーク」では、当期純利益は、リスクから解放されたか否かにかかわらず、所有者との直接的な取引を除く純資産の変動額全体と定義されている。',false,
 '誤り。当期純利益は、純資産の変動額のうち、当期に投資のリスクから解放された成果のうち報告主体の所有者に帰属するものと定義される。リスクから解放されていない部分はその他の包括利益となる。',4191),
('f2-092','2015','基礎','退職給付に係る調整額と繰延ヘッジ損益は、いずれもその他の包括利益に含まれる項目である。',true,
 '正しい。その他の包括利益には、為替換算調整勘定、その他有価証券評価差額金、退職給付に係る調整額、繰延ヘッジ損益が含まれる。',4192),
('f2-093','2015','基礎','包括利益の表示において、1計算書方式を採用した場合と2計算書方式を採用した場合とでは、表示される内容が異なる。',false,
 '誤り。連結損益計算書と連結包括利益計算書を別に作る2計算書方式と、1つの計算書で示す1計算書方式のどちらを選んでも示される中身は同じである。',4193),
('f2-094','2015','応用','親会社が$1＝¥120のときに$2,000を全額出資して在外子会社を設立し、決算日の為替レートが$1＝¥115で子会社の純資産が$2,000のままであれば、為替換算調整勘定は¥10,000のマイナス（借方）となる。',true,
 '正しい。子会社の純資産を決算日レートで換算すると¥230,000、子会社株式の帳簿価額は¥240,000であり、差額¥10,000（＝$2,000×（¥115－¥120））がマイナスの為替換算調整勘定となる。',4194),
('f2-095','2015','標準','その他有価証券について、時価が取得原価を上回る銘柄の評価差額は純資産の部に計上し、下回る銘柄の評価差額は当期の損失とする方法を、全部純資産直入法という。',false,
 '誤り。この方法は部分純資産直入法である。全部純資産直入法は、評価差額を合計額のまま純資産の部に計上する方法である。',4195),
('f2-096','2015','応用','取得原価10,000円のその他有価証券（全部純資産直入法）の期末時価が11,200円となり、翌期首に洗い替えた後、翌期中に11,200円で全部売却した場合、翌期の損益計算書には投資有価証券売却益1,200円が計上される。',true,
 '正しい。洗い替えにより帳簿価額は取得原価10,000円に戻るため、売却時に1,200円の売却益が当期純利益に計上され、前期のその他有価証券評価差額金は取り消される（リサイクリング）。',4196),
('f2-097','2015','応用','年金資産の時価が期待より300,000円下回って数理計算上の差異が生じ、これを平均残存勤務期間12年で按分して費用処理する場合、当期の費用処理額は30,000円である。',false,
 '誤り。費用処理額は300,000円÷12年＝25,000円である。費用処理されない部分は退職給付に係る調整額としてその他の包括利益を通じ純資産に計上される。',4197),
('f2-098','2015','標準','個別財務諸表では、未認識数理計算上の差異や未認識過去勤務費用を負債（または資産）に計上する必要はない。',true,
 '正しい。企業会計基準第26号により、これらを負債（資産）として即時に認識し、退職給付に係る調整額として表示するのは連結財務諸表である。',4198),
('f2-099','2015','標準','ヘッジ会計の要件を満たす場合、時価評価されるヘッジ手段の評価差額は、ヘッジ対象の損益が計上されるまでの各期において、その期の損益に算入される。',false,
 '誤り。ヘッジ手段の評価差額は、ヘッジ対象の損益が認識されるまで純資産の部に繰り延べられ、繰延ヘッジ損益としてその他の包括利益に計上される。',4199),
('f2-100','2015','応用','親会社株主に帰属する当期純利益3,000、非支配株主に帰属する当期純利益400、その他有価証券評価差額金の増加250、為替換算調整勘定の減少600、損益計算書に計上済みの投資有価証券売却益200のとき、包括利益は3,050である。',true,
 '正しい。包括利益＝当期純利益（3,000＋400）＋その他の包括利益（250－600）＝3,050。投資有価証券売却益は既に当期純利益に含まれているので加えない。',4200),
('f2-101','2016','基礎','株価水準を評価する手がかりとなる株価収益率（PER）は、1株当たり当期純利益を株価で除して求める指標である。',false,
 '誤り。PERは株価を1株当たり当期純利益（EPS）で除して求める。株価が高くてもEPSも大きくPERが低いなら、割安と判断できる余地がある。',4201),
('f2-102','2016','基礎','連結財務諸表に基づくEPSの分子には、非支配株主に帰属する当期純利益を含めた連結損益計算書上の当期純利益を用いる。',false,
 '誤り。投資対象は親会社の普通株式なので、親会社株主に帰属する当期純利益を用いる。非支配株主に帰属する当期純利益は親会社の普通株式とは関係がない。',4202),
('f2-103','2016','基礎','普通株式に係る当期純利益の算定では、配当優先株式に対する優先配当額は差し引くが、普通株式に対する配当額は差し引かない。',true,
 '正しい。普通株主に帰属しない金額（優先配当など）を控除する。普通株式への配当はEPSの計算には関係しない。',4203),
('f2-104','2016','標準','累積型配当優先株式は、EPSを計算する期間に基準日がある配当額を差し引けば足り、当期に係る要支払額を差し引く必要はない。',false,
 '誤り。基準日が属する配当額を差し引けばよいのは非累積型配当優先株式である。累積型配当優先株式は、算定対象期間に係る要支払額を差し引く。',4204),
('f2-105','2016','基礎','EPSの分母に用いる普通株式の期中平均株式数は、期中平均発行済株式数から期中平均自己株式数を差し引いて求める。',true,
 '正しい。自己株式は普通株主が実際に持っている株式ではないので、EPSの趣旨から除く。',4205),
('f2-106','2016','応用','発行済株式の60％を所有している子会社が親会社株式2,000株を持っている場合、連結財務諸表のEPSの算定上、1,200株が自己株式数に含められる。',true,
 '正しい。子会社・関連会社が保有する親会社株式のうち、親会社の持分に相当する株式数（2,000株×60％＝1,200株）を自己株式数に含める。',4206),
('f2-107','2016','標準','期中に株式分割が行われた場合、期中平均株式数は分割前の期間の株式数を修正せず、分割日以降の株式数のみを増やして計算する。',false,
 '誤り。株式分割・株式併合があった場合は、表示される財務諸表の中で最も古い期の期首に実施されたものとみなして期中平均株式数を計算し、過去のEPSも遡って再計算する。',4207),
('f2-108','2016','標準','決算日の後に株式分割を実施した場合も、EPSは、表示される財務諸表の中で最も古い期の期首に分割したものとみなして計算・表示する。',true,
 '正しい。EPSは開示する時点の普通株主に役立つ情報でなければならないので、決算日後の株式分割・併合についても同じ仮定で計算する。',4208),
('f2-109','2016','応用','親会社株主に帰属する当期純利益3,600千円、優先株式への配当600千円、普通株式の期中平均発行済株式数1,100千株、期中平均自己株式数100千株の場合、EPSは3.6円である。',false,
 '誤り。分子は優先配当を控除した3,000千円、分母は自己株式を控除した1,000千株なので、EPS＝3,000千円÷1,000千株＝3円となる。',4209),
('f2-110','2016','基礎','潜在株式には、新株予約権のようなワラントや、新株予約権付社債のような転換証券が含まれる。',true,
 '正しい。潜在株式は普通株式を取得できる権利や普通株式への転換請求権などが付された証券・契約で、ワラントと転換証券が含まれる。',4210),
('f2-111','2016','応用','損失計上の期でも、潜在株式が存在する企業は、希薄化効果を有するものとして潜在株式調整後の1株当たり金額を開示しなければならない。',false,
 '誤り。希薄化効果を問題にするのは1株当たり利益が減る場合である。当期純損失の企業では、権利行使を仮定した額が潜在株式を考えない1株当たり当期純損失を上回っても、希薄化効果はないものとして扱う。',4211),
('f2-112','2016','応用','普通株式に係る当期純利益900百万円、転換証券に係る当期純利益調整額60百万円、普通株式の期中平均株式数300百万株、転換による普通株式増加数100百万株の場合、潜在株式調整後EPSは2.4円である。',true,
 '正しい。潜在株式調整後EPS＝（900＋60）百万円÷（300＋100）百万株＝2.4円。希薄化前EPSは3円なので希薄化効果がある。',4212),
('f2-113','2017','基礎','「財務会計の概念フレームワーク」では、資産は、報告主体が過去の取引や事象の結果として支配している経済的資源と定義されている。',true,
 '正しい。負債は経済的資源を放棄もしくは引き渡す義務などと定義され、資産と負債は経済的資源のプラスとマイナスとして捉えられる。',4213),
('f2-114','2017','標準','正常営業循環基準のもとでは、熟成に数年を要する酒類の仕掛品は、販売までに1年を超える期間を要するため固定資産に分類される。',false,
 '誤り。通常の1サイクルの営業循環の中で販売されるものであれば、販売までに数年を要する仕掛品でも流動資産となる。正常営業循環基準は保有期間よりも性質を重視する。',4214),
('f2-115','2017','標準','貸付金や借入金のように財務活動から生じる金融資産・金融負債は、1年基準で流動・固定に分けられる。',true,
 '正しい。営業循環とは別の活動で生じる資産・負債には1年基準が適用される。ただし主となるのは正常営業循環基準である。',4215),
('f2-116','2017','基礎','長期的に運用する設備の重要性が大きい電力・ガス・通信などの企業では、流動区分を先に記載する流動性配列法が採用されている。',false,
 '誤り。一般には流動性配列法が採用されるが、電力・ガス・通信などの企業では固定区分を先に記載する固定性配列法が採用されている。',4216),
('f2-117','2017','標準','繰延資産として計上できる項目には開発費が含まれるが、画期的な新製品などのために特別に支出した研究開発費は、支出した年度に費用処理しなければならない。',true,
 '正しい。繰延資産にできるのは株式交付費、社債発行費等、創立費、開業費、開発費に限られ、研究開発費は繰延資産とすることができない。',4217),
('f2-118','2017','応用','回収可能見込額で資産を評価する場合、将来キャッシュフローを適切な割引率で割り引いた金額で資産を評価する。',false,
 '誤り。回収可能見込額は将来得られると期待されるキャッシュフローの金額であり、割引現在価値と区別するため割引計算は行わない。主に債権の評価に用いられる。',4218),
('f2-119','2017','標準','時価の算定に用いるインプットのうちレベル3は観察できないインプットであり、レベル1・レベル2のインプットが得られないときに使われる。',true,
 '正しい。レベル1は活発な市場における同一資産の市場価格、レベル2はそれ以外の観察可能なインプットであり、いずれも使えない場合に金融工学の手法などによるレベル3を用いる。',4219),
('f2-120','2017','応用','企業会計における時価は、保有資産を測定時にあらためて買い入れるのに要する額である再調達原価、すなわち入口価格を意味する。',false,
 '誤り。企業会計の時価は資産を売却したときに受け取る価格であり、出口価格である。再調達原価は入口価格で、原材料などで例外的に継続適用を条件に用いることが認められるにとどまる。',4220),
('f2-121','2017','応用','割引率が年5％のとき、2年後に受け取る110.25万円の割引現在価値は100万円である。',true,
 '正しい。110.25万円÷（1.05）²＝100万円。割引現在価値は資産の継続利用を前提とした評価額で、使用価値とも呼ばれる。',4221),
('f2-122','2017','基礎','当座資産には現金・預金や受取手形・売掛金などの売上債権が含まれ、棚卸資産は含まれない。',true,
 '正しい。当座資産はすぐに現金化できる、流動性が最も高い資産である。棚卸資産は販売できる保証がないため流動性で当座資産に劣り、別に区分される。',4222),
('f2-123','2017','標準','建設仮勘定は有形固定資産に含まれるため、資産が完成する前の段階から減価償却の対象となる。',false,
 '誤り。建設仮勘定は完成前の支出を一時的に集計する科目で、生産・販売活動に実際に使われていないため減価償却は行われない。完成時に適切な科目へ振り替える。',4223),
('f2-124','2017','基礎','買掛金や支払手形は、通常の営業活動で生じた債務であるため、支払期限まで1年を超えるものであっても流動負債に分類される。',true,
 '正しい。負債の流動・固定区分も主として正常営業循環基準による。一方、借入金など財務活動による債務は1年基準で区分される。',4224),
('f2-125','2017','応用','自己創設のれんは企業が築き上げた超過収益力を表すものであり、金額を合理的に見積もることができる場合には無形固定資産として計上できる。',false,
 '誤り。自己創設のれんは原価を信頼できる形で測ることが難しく、識別可能な資源でもないため、資産として認識することは認められていない。',4225),
('f2-126','2017','標準','繰延税金資産は、回収が見込まれる時期に応じて、流動資産と投資その他の資産に分けて表示される。',false,
 '誤り。企業会計基準第28号により、繰延税金資産はすべて投資その他の資産の区分に表示する。繰延税金負債もすべて固定負債に表示する。',4226),
('f2-127','2018','基礎','個別貸借対照表の純資産の部で評価・換算差額等として表示されるのは、その他有価証券評価差額金と繰延ヘッジ損益である。',true,
 '正しい。為替換算調整勘定は連結財務諸表の作成過程で生じ、退職給付に係る調整額も当面は連結にのみ計上されるため、個別ではこの2項目となる。',4227),
('f2-128','2018','基礎','為替換算調整勘定は、連結貸借対照表だけでなく、在外子会社を持つ親会社の個別貸借対照表の評価・換算差額等にも計上される。',false,
 '誤り。為替換算調整勘定は、在外子会社の財務諸表を円換算して連結する過程で生じる項目なので、個別貸借対照表の評価・換算差額等には表示されない。',4228),
('f2-129','2018','標準','評価・換算差額等は将来の返済義務を伴わないため負債ではないが、株主の拠出でも利益の留保でもないため、株主資本とは区分して表示される。',true,
 '正しい。評価・換算差額等は当期純利益の計算から除外された時価変動等の累計額であり、純資産には含めるが株主資本とは別に表示する。',4229),
('f2-130','2018','基礎','新株予約権は、将来株式を交付する義務を表すものであるため、貸借対照表の負債の部に計上される。',false,
 '誤り。新株予約権について企業は経済的資源を放棄・引き渡す義務を負っておらず、行使時には新たな資本の拠出が行われるため、負債ではなく純資産に含められる。',4230),
('f2-131','2018','標準','新株予約権の保有者は権利を行使するまでは株主ではないため、新株予約権は純資産の部の株主資本以外の項目として表示される。',true,
 '正しい。新株予約権の保有者は潜在株主にすぎない。行使された時点で、新株予約権の金額は払込額とともに株主資本へ振り替えられる。',4231),
('f2-132','2018','応用','権利行使期間が満了し失効した新株予約権の金額は、その他資本剰余金に振り替えられる。',false,
 '誤り。失効した新株予約権の金額は特別利益として当期純利益の計算に組み入れられ、利益剰余金として株主資本に入る。株主との直接的な取引による増加ではないためである。',4232),
('f2-133','2018','標準','「少数株主持分」の名称が「非支配株主持分」に改められたのは、連結の範囲が持株基準で決まり、親会社の所有割合が常に50％を超えるからである。',false,
 '誤り。連結の範囲の決定には支配力基準が用いられ、親会社の所有割合が50％以下の子会社もあり得る。そのため2015年4月以降開始の事業年度から非支配株主持分という名称が使われている。',4233),
('f2-134','2018','標準','資本連結では、子会社の純資産のうち親会社持分が子会社株式と相殺され差額はのれんとなるので、親会社の持分が連結純資産を増加させることはない。',true,
 '正しい。連結純資産を増加させるのは消去されない親会社以外の株主の持分であり、それが非支配株主持分として純資産の部に表示される。',4234),
('f2-135','2018','標準','連結貸借対照表のその他の包括利益累計額には退職給付に係る調整累計額が含まれるが、個別貸借対照表ではその計上は求められていない。',true,
 '正しい。退職給付に係る調整累計額は連結貸借対照表にのみ計上され、為替換算調整勘定も連結特有の項目である。',4235),
('f2-136','2018','基礎','連結貸借対照表では、個別貸借対照表の評価・換算差額等に当たる項目がその他の包括利益累計額として表示され、さらに非支配株主持分が表示される。',true,
 '正しい。個別では株主資本・評価・換算差額等・新株予約権に区分されるが、連結では評価・換算差額等がその他の包括利益累計額となり、非支配株主持分が加わる。',4236),
('f2-137','2018','応用','連結貸借対照表の純資産の部が、株主資本3,000、その他の包括利益累計額200、新株予約権50、非支配株主持分400で構成されている場合、株主資本以外の純資産の額は250である。',false,
 '誤り。株主資本以外の純資産は、その他の包括利益累計額200＋新株予約権50＋非支配株主持分400＝650である。純資産合計は3,650となる。',4237),
('f2-138','2018','基礎','個別貸借対照表の純資産の部は、株主資本、評価・換算差額等、新株予約権および非支配株主持分の4つに区分して表示される。',false,
 '誤り。個別貸借対照表の純資産の部は株主資本、評価・換算差額等、新株予約権に区分される。非支配株主持分は連結貸借対照表にのみ表示される。',4238),
('f2-139','2019','基礎','会社法上、株式の発行に際して株主が払い込んだ金額は、その全額を資本金に計上しなければならない。',false,
 '誤り。払込金額の2分の1までは資本準備金に回すことができ、多くの会社がこれを利用している。そのため資本金は株主の拠出額より小さいことが多い。',4239),
('f2-140','2019','標準','資本金は会社法で定める減資の手続きを経なければ減額できず、その金額に見合う資産を企業内にとどめておく拘束性が高い。',true,
 '正しい。資本金を容易に減らせないのは、それに見合う資産を社内に維持させる拘束力が強いことを表している。',4240),
('f2-141','2019','標準','資本金が計上されている企業は、その金額に相当する現金を手許に保有していなければならない。',false,
 '誤り。資本金に見合う資産を保持する必要はあるが、出資された資金は通常さまざまな資産に投下されており、同額の現金を持っているわけではない。',4241),
('f2-142','2019','標準','資本準備金は減額に際して減資の手続きが不要である点で資本金より拘束性が低いが、拠出資本であるという点では資本金と同じである。',true,
 '正しい。資本準備金は払込額のうち資本金としなかった額などからなり、資本金より拘束性は低いが拠出資本に属する。',4242),
('f2-143','2019','標準','その他資本剰余金は拠出資本であるため、会社法上、剰余金の配当として株主に分配することは認められていない。',false,
 '誤り。その他資本剰余金は拠出資本ではあるが、会社法上は剰余金の配当の財源にでき、この点が資本金・資本準備金と大きく異なる。',4243),
('f2-144','2019','標準','手持ちの自己株式を消却したときは、その自己株式の帳簿価額だけその他資本剰余金を減らす。',true,
 '正しい。自己株式の売買差額や消却額はその他資本剰余金に加減算される。残高がマイナスになる場合はゼロとし、不足分を繰越利益剰余金から減額する。',4244),
('f2-145','2019','標準','剰余金を財源に配当を行う場合、準備金（資本準備金＋利益準備金）が資本金の4分の1に届くまでは、配当額の10分の1を準備金として積み立てなければならない。',true,
 '正しい。財源がその他利益剰余金なら利益準備金、その他資本剰余金なら資本準備金を積み立てる。準備金合計が資本金の4分の1を上回っていれば積立ては不要である。',4245),
('f2-146','2019','基礎','企業が自らの判断で利益を留保する任意積立金のうち、使途を特定しないで積み立てたものを別途積立金という。',true,
 '正しい。任意積立金には配当平均積立金や新築積立金のように目的を示す科目もあるが、目的を定めない場合は別途積立金とする。',4246),
('f2-147','2019','基礎','個別貸借対照表の利益剰余金のうち、企業の当期純利益は決算の段階でまず利益準備金に加算される。',false,
 '誤り。当期純利益は決算の段階でまず繰越利益剰余金に加算される。繰越利益剰余金は、社外流出か内部留保かがまだ決められていない利益を表す。',4247),
('f2-148','2019','基礎','自己株式の取得は外見上は有価証券の購入であるため、取得した自己株式は有価証券として資産の部に計上される。',false,
 '誤り。自己株式の取得は実態として株主への資本の払戻しと考えられるため、資産計上せず株主資本のマイナス項目として表示する。',4248),
('f2-149','2019','標準','自己株式を取得価額より低い価額で処分した場合、その差額は営業外費用として当期純利益の計算に含められる。',false,
 '誤り。自己株式の売買は株主との資本取引なので、処分差額はその他資本剰余金に加減算する。差損であればその他資本剰余金を減少させ、損益には影響しない。',4249),
('f2-150','2019','標準','自己株式の処分差損がその他資本剰余金の残高を上回った場合には、その他資本剰余金をゼロとし、上回る部分はその他利益剰余金から減額する。',true,
 '正しい。その他資本剰余金は負の残高にはせず、超過部分はその他利益剰余金（繰越利益剰余金）から減額する。',4250),
('f2-151','2019','応用','諸資産6,000、諸負債3,500、資本金500、資本準備金400、その他資本剰余金100、利益準備金150、繰越利益剰余金1,450、自己株式△100の会社（のれん・繰延資産・評価差額等なし、決算日後の取引なし）の分配可能額は1,450である。',true,
 '正しい。剰余金＝6,000＋100－3,500－500－（400＋150）＝1,550（その他資本剰余金100＋繰越利益剰余金1,450に一致）。ここから自己株式100を控除し、分配可能額は1,450となる。',4251),
('f2-152','2019','応用','期首の利益剰余金300の会社が、当期に当期純利益80を計上し、配当40を支払い、任意積立金20を積み立て、自己株式30を取得した場合、期末の利益剰余金は310である。',false,
 '誤り。任意積立金の積立ては利益剰余金内部の振替であり、自己株式の取得は利益剰余金を変動させない。期末利益剰余金＝300＋80－40＝340となる。',4252),
('f2-153','2020','基礎','キャッシュ・フロー計算書が対象とする資金の範囲は、手許現金や要求払預金などの現金に、現金同等物を加えたものである。',true,
 '正しい。現金には手許現金と要求払預金（および特定の電子決済手段）が含まれ、これに容易に換金可能で価値変動のリスクが僅少な短期投資である現金同等物を加えたものが資金となる。',4253),
('f2-154','2020','基礎','取得日から満期日までの期間が6ヵ月の定期預金は、価値の変動リスクが小さいため現金同等物に含まれる。',false,
 '誤り。現金同等物の例として挙げられているのは、取得から満期・償還までが3ヵ月以内の定期預金、譲渡性預金、コマーシャル・ペーパーなどである。',4254),
('f2-155','2020','標準','2023年の作成基準の一部改正により、法定通貨に価値が連動し、額面での払戻しが約束された電子決済手段など、特定の電子決済手段が現金に含まれることになった。',true,
 '正しい。資金決済法に定める電子決済手段で、いわゆるステーブルコインのうち一定のものが、キャッシュ・フロー計算書上の現金に含まれる。',4255),
('f2-156','2020','基礎','法人税等の支払額は、キャッシュ・フロー計算書の投資活動によるキャッシュ・フローの区分に記載される。',false,
 '誤り。法人税等に係るキャッシュ・フローは営業活動によるキャッシュ・フローの区分に記載される。',4256),
('f2-157','2020','標準','災害による保険金収入や損害賠償金の支払は、投資・財務のどちらの活動にも当たらない取引として、営業活動によるキャッシュ・フローの区分に記載される。',true,
 '正しい。営業活動の区分には、営業損益計算に含まれる取引に加え、投資・財務のいずれにも属さない取引のキャッシュ・フローも含まれる。',4257),
('f2-158','2020','標準','受取利息・支払利息・受取配当金を営業活動の区分に記載する方法を採用した場合には、支払配当金も営業活動によるキャッシュ・フローの区分に記載される。',false,
 '誤り。支払配当金はいずれの方法でも財務活動によるキャッシュ・フローの区分に記載される。営業活動に含められるのは受取利息・支払利息・受取配当金である。',4258),
('f2-159','2020','応用','連結キャッシュ・フロー計算書では、連結範囲の変動を伴う子会社株式の取得または売却によるキャッシュ・フローを、投資活動の区分に独立の項目を設けて記載する。',true,
 '正しい。連結範囲の変動を伴う子会社株式の取得・売却は投資活動の中で独立掲記する。なお連結では配当金の支払を親会社分と非支配株主分に区分する。',4259),
('f2-160','2020','標準','投資活動によるキャッシュ・フローが大幅な黒字となっている場合、企業が積極的に設備投資を行っていることを示していると考えられる。',false,
 '誤り。設備投資を続けて規模拡大を図っている企業では投資活動のキャッシュ・フローは赤字が続く。大きな黒字はリストラなどによる大規模な資産処分の可能性を示す。',4260),
('f2-161','2020','応用','DCF法で企業価値を評価するときのフリー・キャッシュフローには、支払利息を控除した後の金額を用いなければならない。',false,
 '誤り。DCF法で用いるフリー・キャッシュフローは支払利息を差し引く前のものでなければならない。営業活動によるキャッシュ・フローは支払利息控除後であることが多いので注意が必要である。',4261),
('f2-162','2020','基礎','自己株式の取得による支出や配当金の支払は、財務活動によるキャッシュ・フローの区分に記載される。',true,
 '正しい。財務活動の区分には、株式の発行による収入、自己株式の取得による支出、配当金の支払、社債・借入金による調達と返済などが記載される。',4262),
('f2-163','2020','応用','営業活動によるキャッシュ・フローが1,200、投資活動によるキャッシュ・フローが▲900、財務活動によるキャッシュ・フローが▲200の企業では、フリー・キャッシュフローは300である。',true,
 '正しい。フリー・キャッシュフロー＝営業活動1,200＋投資活動▲900＝300。財務活動は含めない。この場合、現金及び現金同等物は100増加する。',4263),
('f2-164','2020','標準','営業活動のキャッシュ・フローが黒字、投資活動が赤字、財務活動が黒字という組み合わせは、外部資金も使って積極的に事業を拡大している企業に典型的に見られる。',true,
 '正しい。営業で得た資金に外部調達資金を加えて設備投資に充てている状況が考えられる。ただし投資の成果が出るとは限らないので投資内容の検討も必要である。',4264),
('f2-165','2020','標準','営業活動と投資活動のキャッシュ・フローがともに赤字で財務活動が黒字という組み合わせは、企業の創業期や発展期には生じにくい。',false,
 '誤り。創業期や発展期には出資などで集めた資金がまず営業活動や設備に投入されるため、この組み合わせになることが多い。',4265),
('f2-166','2020','応用','営業活動のキャッシュ・フローが赤字、投資活動が黒字、財務活動が赤字という組み合わせは、外部から資金を調達して事業規模を拡大している企業に典型的である。',false,
 '誤り。この組み合わせは、営業活動の資金不足を固定資産の売却などで補い、債務返済も行っている状況であり、企業規模が縮小傾向にある場合に典型的とされる。',4266),
('f2-167','2021','基礎','直接法は、主要な取引ごとにキャッシュ・フローを総額で表示する方法であり、営業収入や原材料・商品の仕入支出などに区分して示される。',true,
 '正しい。一方、間接法は、税金等調整前当期純利益から出発し、非資金損益項目や営業上の資産・負債の増減などを調整して示す方法である。',4267),
('f2-168','2021','基礎','間接法では、減価償却費はキャッシュ・フローを伴わない費用であるため、税金等調整前当期純利益から減算される。',false,
 '誤り。減価償却費は利益の計算では差し引かれているが支出を伴わないので、税金等調整前当期純利益に加算（戻し入れ）する。',4268),
('f2-169','2021','標準','間接法による連結キャッシュ・フロー計算書では、持分法による投資利益はキャッシュ・フローを伴わない収益として税金等調整前当期純利益から控除される。',true,
 '正しい。連結の場合、持分法による投資損益も現金の動きを伴わない損益として扱われ、投資利益は減算、投資損失は加算する。',4269),
('f2-170','2021','基礎','間接法で営業活動によるキャッシュ・フローを計算する場合、棚卸資産の減少額は税金等調整前当期純利益から減算される。',false,
 '誤り。棚卸資産の減少額は売上原価として費用に含まれているが当期の支出ではないため、加算する。棚卸資産の増加額は減算する。',4270),
('f2-171','2021','標準','間接法では、有形固定資産売却損は投資活動の区分で売却収入として表示されるため、営業活動によるキャッシュ・フローの計算上は税金等調整前当期純利益に加算して除外する。',true,
 '正しい。投資活動や財務活動の区分に含まれる損益項目は営業活動から除外する。売却損は利益を減らしているので加算し、売却益は減算する。',4271),
('f2-172','2021','応用','税金等調整前当期純利益8,000、減価償却費1,200、売上債権の増加900、棚卸資産の減少400、仕入債務の増加300、投資有価証券売却益500、法人税等の支払額2,000の場合、営業活動によるキャッシュ・フローは6,500である。',true,
 '正しい。8,000＋1,200－900＋400＋300－500－2,000＝6,500。売上債権の増加と売却益は減算、棚卸資産の減少と仕入債務の増加は加算する。',4272),
('f2-173','2021','応用','税金等調整前当期純利益5,000、のれんの償却額600、貸倒引当金の増加200、売上債権の減少700、仕入債務の減少1,100、固定資産売却益300、法人税等の支払額1,500の場合、営業活動によるキャッシュ・フローは4,200である。',false,
 '誤り。5,000＋600＋200＋700－1,100－300－1,500＝3,600となる。固定資産売却益は投資活動の区分に属する損益なので減算して除外する。',4273),
('f2-174','2021','標準','直接法と間接法とでは、表示方法が異なるだけでなく、算定される営業活動によるキャッシュ・フローの金額も異なる。',false,
 '誤り。両者はキャッシュ・フローの見せ方の違いにすぎず、いずれを採用しても営業活動によるキャッシュ・フローの金額は同じになる。',4274),
('f2-175','2021','応用','売上高が20,000で、期中に売掛金が1,500増加し前受金が300増加した場合、直接法で表示される営業収入は18,800である。',true,
 '正しい。営業収入＝売上高20,000－売掛金の増加1,500＋前受金の増加300＝18,800。前受金の増加は収益に計上されていないが資金として受け取った額である。',4275),
('f2-176','2021','標準','直接法で営業支出を計算する際、未払費用の増加額は損益計算書上の費用額に加算する。',false,
 '誤り。未払費用の増加額は費用には計上されているが支出が生じていない額なので、費用額から減算する。前払費用の増加額は加算する。',4276),
('f2-177','2021','標準','営業債権の大幅な増加によって営業活動によるキャッシュ・フローが小さくなっている場合には、与信基準を緩めて売上を伸ばしている可能性があるので、信用販売の状況を確認する必要がある。',true,
 '正しい。与信を緩めて売上を増やしているなら、利益が出ていても資金繰りは悪くなっているおそれがある。',4277),
('f2-178','2021','標準','間接法は、利益とキャッシュ・フローの差が生じた原因を示さない簡便な表示方法にすぎないため、分析上は直接法の情報を重視すべきである。',false,
 '誤り。間接法は利益とキャッシュ・フローが異なる理由をむしろ直接的に示す表示方法である。ほとんどの企業が採用しており、その情報を積極的に活用することが求められる。',4278),
('f2-179','2022','基礎','株主資本等変動計算書は、上場会社に限らず、会社法によってすべての株式会社に作成が求められている。',true,
 '正しい。会社法で剰余金の配当や株主資本の計数の変動がいつでもできるようになり、貸借対照表と損益計算書だけでは数値の連続性を把握しにくくなったためである。',4279),
('f2-180','2022','標準','株主資本等変動計算書では、株主資本以外の項目についても、期中の変動額を原因別に分けて示さなければならない。',false,
 '誤り。変動事由ごとの区分表示が必要なのは株主資本の項目である。株主資本以外の項目は純額での表示が許されている（企業の判断で区分してもよい）。',4280),
('f2-181','2022','標準','「株主資本等変動計算書」という名称が用いられているのは、純資産の部のうち特に株主資本の変動原因を示すことに重点が置かれているためである。',true,
 '正しい。対象は純資産の部のすべての項目だが、変動事由の表示が重視されるのは株主資本なので、純資産変動計算書ではなくこの名称とされている。',4281),
('f2-182','2022','標準','安定配当政策を採る企業では、業績が悪化すると配当額も減額されるため、当期純利益が出ている年に株主資本が減ることはない。',false,
 '誤り。安定配当政策では業績にかかわらず配当額を一定に保つので、当期純利益が配当総額を下回ると株主資本が減少することがある。業績に応じて配当が減るのは配当性向一定の政策である。',4282),
('f2-183','2022','応用','配当性向を一定に保つ政策を採る企業は、安定配当政策を採る企業に比べて、業績が向上した局面で内部留保が進みにくい。',true,
 '正しい。配当性向一定の政策では増益分の一部が配当の増額に回されるため、増益分が主に内部留保に回る安定配当政策よりも内部留保による規模拡大は小さくなる。',4283),
('f2-184','2022','標準','企業会計上、自己株式の取得は剰余金の処分として扱われ、株主資本等変動計算書では繰越利益剰余金の減少として表示される。',false,
 '誤り。自己株式の取得は株主資本のマイナスとして処理され、剰余金の処分には当たらない。ただし現金の支払いという点で配当と実質的な違いはない。',4284),
('f2-185','2022','応用','シグナリング仮説によれば、継続が求められる増配に比べ、一回限りで実施できる自己株式の取得の方が、企業にとってシグナルを送る負担は小さいとされる。',true,
 '正しい。自己株式の取得が増配と同じシグナルを送る目的で行われるなら、配当政策と自己株式の売買の方針は一体として捉えられ、これをペイアウト政策と呼ぶ。',4285),
('f2-186','2022','標準','期首の株主資本が1,000の企業が当期純利益50を計上し、安定配当政策に基づいて配当80を支払った場合（他の変動なし）、期末の株主資本は1,050となる。',false,
 '誤り。期末の株主資本＝1,000＋50－80＝970となり、当期純利益を計上していても株主資本は減少する。安定配当政策では過去の留保利益で配当の不足分を補うことがある。',4286),
('f2-187','2023','基礎','連結損益計算書では、個別損益計算書の税引前当期純利益に相当する利益は「経常利益」という名称で表示される。',false,
 '誤り。連結損益計算書では税金等調整前当期純利益として表示される。その後、当期純利益を計算し、非支配株主に帰属する当期純利益を差し引いて親会社株主に帰属する当期純利益を示す。',4287),
('f2-188','2023','標準','キャッシュ・フロー計算書は会社法上の作成義務がないため、実務では個別キャッシュ・フロー計算書を開示せず、連結キャッシュ・フロー計算書だけを開示する例が多い。',true,
 '正しい。そのため間接法の場合、営業活動によるキャッシュ・フローは連結損益計算書の科目名である税金等調整前当期純利益を出発点として表示される。',4288),
('f2-189','2023','標準','連結キャッシュ・フロー計算書は、個別キャッシュ・フロー計算書を基礎に連結会社相互間のキャッシュ・フローを相殺消去して作成するのが原則だが、連結貸借対照表と連結損益計算書から作成する簡便な方法も認められている。',true,
 '正しい。原則的な方法は実務上の負担が大きいため、個別キャッシュ・フロー計算書を作らずに連結財務諸表の科目金額から作成する簡便法も認められている。',4289),
('f2-190','2023','標準','連結株主資本等変動計算書の株主資本の変動に含まれる利益は、非支配株主に帰属する部分も含めた連結損益計算書上の当期純利益である。',false,
 '誤り。連結株主資本等変動計算書の株主資本の変動に含まれるのは、親会社株主に帰属する当期純利益である。',4290),
('f2-191','2023','標準','日本の「四半期財務諸表に関する会計基準」は予測主義を採用しており、年度決算では認められない費用の繰延べなど四半期固有の会計処理が行われる。',false,
 '誤り。日本基準は実績主義を採用しており、四半期会計期間を1会計期間とみて原則として年度と同じ会計方針を適用する。費用の繰延べ等を認めるのは予測主義の考え方である。',4291),
('f2-192','2023','応用','四半期財務諸表で実績主義が採用された理由の一つとして、予測主義よりも経営者の恣意が決算に入り込みにくいことが挙げられている。',true,
 '正しい。このほか、業績予測には四半期の実績を示すことが大切であること、事務が簡単なこと、国際的にも実績主義が主流になりつつあることが挙げられた。',4292),
('f2-193','2023','標準','四半期財務諸表としては株主資本等変動計算書を作成しなくてよいが、株主資本が大きく変動したときはその旨の注記を要する。',true,
 '正しい。実務負担の軽減のため株主資本等変動計算書は不要とされる一方、株主資本の著しい変動や減価償却費・のれんの償却額などは注記が求められる。',4293),
('f2-194','2023','応用','貸借対照表以外の四半期財務諸表は各四半期の3ヵ月間を対象とするものの開示が義務付けられており、期首からの累計期間の財務諸表の開示は任意とされている。',false,
 '誤り。義務付けられているのは各四半期決算日までの累計期間の財務諸表であり、3ヵ月ごとの財務諸表の開示は任意である。累計情報の方が年間見通しへの進捗度を示すうえで有用と考えられている。',4294),
('f2-195','2023','標準','IFRSに基づく連結財政状態計算書では、資産と負債を流動性配列法によって配列することが義務付けられている。',false,
 '誤り。日本基準は原則として流動性配列法によるが、IFRSには資産・負債をどの順に並べるかの定めがなく、配列に対する柔軟性が高い。',4295),
('f2-196','2023','応用','IFRSに基づく連結財政状態計算書では、新株予約権は日本基準と同様に株主資本とは別建てで示され、「親会社の株主に帰属する持分」の外に置かれる。',false,
 '誤り。IFRSでは新株予約権は資本剰余金に含められ、その他の包括利益累計額も含めて「親会社の株主に帰属する持分」に合算される。このため同持分は日本基準の株主資本とは異なる。',4296),
('f2-197','2023','標準','IFRSに基づく連結財政状態計算書では、日本基準でいうその他の包括利益累計額の部分は「その他の資本の構成要素」に含められる。',true,
 '正しい。IFRSでは株主資本という区分はなく、資本金、資本剰余金、利益剰余金、自己株式、その他の資本の構成要素の合計が親会社の株主に帰属する持分となる。',4297),
('f2-198','2023','応用','IFRSの連結損益計算書における継続事業から生じる損益は、非継続事業に分類された事業がグループ内にあった期間の損益も除外されるため、日本基準の経常損益とは意味が異なる。',true,
 '正しい。非継続事業から生じる損益には、処分に伴う損益だけでなくその事業が集団に属している間の損益も含まれるので、継続事業の損益は経常損益と一致しない。',4298),
('f2-199','2023','標準','IFRSでは、日本基準のその他有価証券評価差額金に相当する項目についても、売却したときに純損益へリサイクリングしなければならない。',false,
 '誤り。日本基準ではリサイクリングが必要とされるが、IFRSでは義務付けられておらず、この項目はリサイクリングされない。そのため、対象となるOCIとならないOCIを区分して表示する。',4299),
('f2-200','2023','基礎','連結キャッシュ・フロー計算書については日本基準とIFRSの間で資金の範囲や表示区分に差異はなく、IFRSでも営業活動の表示に直接法と間接法のいずれを用いてもよい。',true,
 '正しい。キャッシュ・フロー計算書は日本基準とIFRSで実質的に同じであり、営業活動によるキャッシュ・フローの表示方法も選択できる。',4300),
('f3-021','2034','基礎','収益認識会計基準等は、2021年4月1日以後に始まる連結会計年度・事業年度の期首から適用され、それ以前からの早期適用も可能とされていた。',true,
 '正しい。同基準と適用指針は2018年3月に公表、2020年3月に改正され、2021年4月1日以後開始の年度の期首から強制適用された。早期適用も認められていた。',5121),
('f3-022','2034','基礎','収益認識会計基準は、金融商品会計基準が対象とする金融商品の取引にも適用されるため、貸付金の利息収益もこの基準に従って認識する。',false,
 '誤り。金融商品会計基準が対象とする金融商品の取引は収益認識会計基準の適用範囲から除かれ、従来の金融商品会計基準で処理される。',5122),
('f3-023','2034','基礎','履行義務とは、顧客と結んだ契約の中で、別個の財又はサービス（またはその束）か、特性と移転パターンが同じ一連の別個の財又はサービスを引き渡すことを約束したものをいう。',true,
 '正しい。収益認識会計基準7項は、①別個の財又はサービス（の束）、②一連の別個の財又はサービスのどちらかを顧客へ移転する約束を履行義務としている。',5123),
('f3-024','2034','基礎','契約の識別の要件を満たすには、当事者が契約書などの書面で契約を承認していることが必要であり、口頭や取引慣行による承認では足りない。',false,
 '誤り。契約の承認と義務履行の約束は、書面のほか口頭や取引慣行等によるものでもよく、書面に限定されない。',5124),
('f3-025','2034','標準','契約の識別要件の1つに、企業が受け取る権利を持つ対価の回収可能性が高いことがあり、その判断では支払期限の時点で顧客に支払う意思と能力があるかを考慮する。',true,
 '正しい。収益認識会計基準19項(5)の要件である。回収可能性は、支払期限到来時に顧客が支払う意思と能力を有するかという観点で評価する。',5125),
('f3-026','2034','基礎','取引価格には第三者のために回収する額を含めないため、売上に係る消費税等は収益に含めない税抜方式で処理する。',true,
 '正しい。取引価格は、財又はサービスの移転と交換に企業が得ると見込む対価から第三者のために回収する額を除いたもので、消費税等は売上高に含めない税抜方式だけが採られる。',5126),
('f3-027','2034','標準','約束した対価にリベートや値引きなどの変動対価が含まれていても、取引価格の算定では変動対価を考慮せず、契約書に記載された金額をそのまま取引価格とする。',false,
 '誤り。取引価格の算定では変動対価、重要な金融要素、現金以外の対価、顧客に支払われる対価の影響をすべて考慮し、変動対価が含まれる場合は企業が権利を得る対価の額を見積る。',5127),
('f3-028','2034','標準','取引開始日の時点で、財を移転してから顧客が支払うまでの期間が1年以内と見込まれるときは、重要な金融要素による影響を対価の額に反映させないことができる。',true,
 '正しい。重要な金融要素がある場合は金利相当分を調整し現金販売価格で収益を認識するのが原則だが、移転と支払の間隔が1年以内と見込まれるときは調整しないことができる（58項）。',5128),
('f3-029','2034','標準','製品800個を1個15千円、合計12,000千円で販売し全額を請求した。販売数量に応じたリベートが1個当たり1.5千円になると見込む場合、計上する収益は10,800千円で、差額1,200千円は返金負債となる。',true,
 '正しい。リベートは変動対価であり、取引価格は（15千円－1.5千円）×800個＝10,800千円と見積られる。請求額12,000千円との差額1,200千円は返金負債として計上する。',5129),
('f3-030','2034','標準','製品X・Y・Zを合計80千円で一括販売し、独立販売価格がX60千円、Y30千円、Z10千円である場合、独立販売価格の比率で配分すると製品Xの取引価格は48千円となる。',true,
 '正しい。独立販売価格合計100千円と取引価格80千円の差20千円は全履行義務に比例配分される。製品Xは80千円×60／100＝48千円となる。',5130),
('f3-031','2034','応用','商品1台の販売と2年間にわたる保守サービスを合わせて9,000千円で契約し、独立販売価格が商品8,000千円、保守2,000千円の場合、契約初年度に認識する収益は合計9,000千円である。',false,
 '誤り。取引価格は商品7,200千円、保守1,800千円に配分される。商品は引渡時に7,200千円、保守は2年にわたり認識するので初年度は900千円で、合計8,100千円となる。',5131),
('f3-032','2034','基礎','契約資産には、売掛金のように対価に対する無条件の権利である顧客との契約から生じた債権も含めて表示する。',false,
 '誤り。契約資産は、移転済みの財又はサービスの対価に対する企業の権利のうち、顧客との契約から生じた債権に当たらないものである。売掛金等の無条件の権利は後者として区別する。',5132),
('f3-033','2034','標準','財又はサービスを引き渡す前に顧客から対価を受け取るときは、受領した時点と支払期限が到来した時点のうち早い方で契約負債を計上する。',true,
 '正しい。収益認識会計基準78項による。契約負債は企業の履行義務に対して顧客から受け取った（又は期限が到来した）対価であり、前受金等として表示されることもある。',5133),
('f3-034','2034','標準','契約に重要な金融要素が含まれていても、顧客との契約から生じる収益と、金融要素から生じる受取利息等は損益計算書上で合算して示す。',false,
 '誤り。重要な金融要素がある契約では、顧客との契約から生じる収益と、金融要素による受取利息または支払利息を損益計算書で分けて表示する（78－3項）。',5134),
('f3-035','2034','標準','収益に関する重要な会計方針の注記として、主要事業での主な履行義務の中身と、その履行義務を通常どの時点で充足するかを記載する。',true,
 '正しい。収益認識会計基準80－2項は、主な履行義務の内容と、収益を認識する通常の時点である履行義務の充足時点を重要な会計方針として注記するよう求めている。',5135),
('f3-036','2034','標準','製品に付けた保証が、製品が合意された仕様に従っていることを保証するだけのものである場合、その保証は履行義務とせず、企業会計原則注解18の引当金として処理する。',true,
 '正しい。仕様どおりであることの保証のみであれば引当金処理となる（適用指針34項）。仕様の保証に加えて顧客にサービスを提供する保証サービスを含む場合は、それが履行義務となる。',5136),
('f3-037','2034','標準','保証の中に、仕様どおりであることの保証に加えて顧客にサービスを提供する保証サービスが含まれる場合でも、保証全体を引当金で処理し、取引価格の配分は行わない。',false,
 '誤り。保証サービスは別個の履行義務となるため、取引価格を製品と保証サービスに配分する（適用指針35項）。引当金処理は仕様どおりであることの保証のみの場合に限られる。',5137),
('f3-038','2034','応用','製品と操作研修を900千円で同時に契約し、独立販売価格が製品900千円、研修300千円である。研修は後日提供する場合、製品引渡時に認識する収益は900千円である。',false,
 '誤り。取引価格900千円を独立販売価格の比率で配分すると、製品は900×900／1,200＝675千円、研修は225千円となる。引渡時の収益は675千円で、225千円は契約負債となる。',5138),
('f3-039','2034','標準','通販サイト運営会社が出品者の商品販売を手配し、販売代金の8％を手数料として受け取る。運営会社が代理人に該当する場合、顧客が2,500千円の商品を購入した時点の収益は200千円である。',true,
 '正しい。代理人に該当するときは、手配と交換に権利を得る報酬又は手数料の額を収益とする。2,500千円×8％＝200千円が収益で、販売代金の総額は収益にならない。',5139),
('f3-040','2034','標準','本人・代理人の判定により売上高が大きく変わり得る取引の例として、小売業のいわゆる消化仕入やECサイトの運営に関する取引が挙げられている。',true,
 '正しい。代理人に該当すると純額表示しか認められないため売上高への影響が大きくなり得る。卸売業の取引、消化仕入、返品条件付買取仕入、有償支給取引、EC運営取引などが例とされる。',5140),
('f3-041','2034','基礎','収益認識会計基準のもとでも、販売時に顧客へ付与したポイントは、将来の使用見込額をポイント引当金として計上し、繰入額を販売費とする処理が認められている。',false,
 '誤り。ポイントが重要な権利を提供する場合は別個の履行義務とし、取引価格の一部を契約負債として認識する。ポイントの引当金処理は2021年4月1日以降認められない。',5141),
('f3-042','2034','応用','商品を90,000円で現金販売し12,000ポイントを付与、うち10,000ポイント（10,000円相当）の使用を見込む。年度中に4,000ポイントが使われた場合、その年度の売上高は84,600円である。',true,
 '正しい。販売時に商品90,000×90／100＝81,000円、ポイント9,000円に配分する。年度末に9,000×4,000／10,000＝3,600円を契約負債から売上へ振り替え、81,000＋3,600＝84,600円となる。',5142),
('f3-043','2034','標準','ライセンス供与の約束が独立した履行義務であり、供与時点で存在する知的財産を使用する権利を顧客に与えるものである場合、ライセンス期間にわたり収益を認識する。',false,
 '誤り。使用する権利であれば一時点で充足される履行義務となり、顧客がライセンスを使って便益を得られるようになった時点で収益を計上する。期間にわたり認識するのはアクセスする権利の場合である。',5143),
('f3-044','2034','標準','返品権付きで商品を販売した場合、返品が見込まれる商品に対応する売上原価は認識せず、顧客から商品を回収する権利を返品資産として流動資産に計上する。',true,
 '正しい。返品見込分は売上を計上せず返金負債を、対応する売上原価は計上せず返品資産を認識する。売上と売上原価の両方を調整する点で、かつての返品調整引当金処理と異なる。',5144),
('f3-045','2034','応用','1個50千円の製品100個を現金販売し、4個の返品を見込む場合、収益5,000千円を計上したうえで、返品見込分の売上総利益に相当する額を返品調整引当金として負債に計上する。',false,
 '誤り。返品見込の4個分は収益を認識せず、収益は50千円×96個＝4,800千円、返金負債は50千円×4個＝200千円となる。返品調整引当金を計上する処理は認められなくなった。',5145),
('f3-046','2035','基礎','清掃サービスのように、企業が義務を履行するにつれて顧客が便益を享受する契約は、一定の期間にわたり充足される履行義務の要件を満たす。',true,
 '正しい。収益認識会計基準38項の(1)の要件であり、清掃サービスが例とされる。要件(1)～(3)のいずれかに当てはまれば、収益は一定期間にわたって計上する。',5146),
('f3-047','2035','標準','一定の期間にわたり充足される履行義務の要件(3)は、別の用途に転用できない資産が生じることと、履行完了部分の対価を収受する強制力ある権利を有することの、どちらか一方を満たせばよい。',false,
 '誤り。要件(3)は、転用できない資産が生じることと、履行を完了した部分の対価を受け取る強制力ある権利を持つことの両方が必要である。',5147),
('f3-048','2035','標準','進捗度を合理的に見積もれないものの、履行に伴って生じる費用は回収できると見込まれる場合は原価回収基準で処理し、その契約から生じる利益はゼロとなる。',true,
 '正しい。原価回収基準は、発生する費用のうち回収が見込まれる額で収益を認識する方法である。収益と費用が同額となるため、算定される利益はゼロになる（45項、15項）。',5148),
('f3-049','2035','基礎','一定の期間にわたり充足される履行義務の3つの要件のいずれも満たさない場合、その履行義務は一時点で充足されるものとして、支配が顧客に移転した時に収益を認識する。',true,
 '正しい。収益認識会計基準39項による。要件(1)～(3)のいずれにも当たらない履行義務は一時点で充足されるものとし、資産の支配を顧客へ移した時点で収益を認識する。',5149),
('f3-050','2035','標準','商品を販売業者に引き渡しても販売業者がその支配を獲得していない場合は、委託販売契約の可能性があるため、販売業者への引渡時点では収益を認識しない。',true,
 '正しい。適用指針75項による。販売業者が最終顧客に販売するまで企業が支配している、企業が返還を要求できる、販売業者に無条件の支払義務がないこと等が委託販売の指標である。',5150),
('f3-051','2035','標準','所定の大きさや重量を顧客が確認するだけの検収であり、合意された仕様に従っていることを客観的に判断できる場合でも、検収が完了するまでは収益を認識できない。',false,
 '誤り。仕様に合っていることを客観的に判断できるなら検収は形式的なものにすぎず、支配移転の時点の判断を左右しない。客観的に判断できない場合は検収完了まで支配は移転しない。',5151),
('f3-052','2035','標準','出荷基準を用いる代替的な取扱いは、主に国外販売のように出荷から顧客の検収まで長期間を要する取引を対象として設けられたものである。',false,
 '誤り。代替的な取扱いは国内販売で、出荷から支配移転（例えば検収）までが通常の期間（国内配送では数日程度）である場合に、出荷時や着荷時に収益を認識できるとするものである。',5152),
('f3-053','2035','基礎','収益認識会計基準の適用後も、割賦販売については、代金を回収する期日の到来に応じて収益を計上する割賦基準を選択することが認められている。',false,
 '誤り。割賦基準による収益計上は、ポイントの引当金処理や返品調整引当金の計上とともに代替的な取扱いが設けられておらず、2021年4月1日以降は採用できない。',5153),
('f3-054','2035','応用','請負金額240億円、見積総工事原価160億円の工事で、第1期の実際発生原価が40億円であった。原価に基づく進捗度で収益を認識する場合、第1期の工事利益は40億円である。',false,
 '誤り。進捗度は40／160＝25％で、第1期の工事収益は240億円×25％＝60億円、工事原価40億円を差し引いた工事利益は20億円となる。',5154),
('f3-055','2035','基礎','工事完成基準のもとでは、工事が完成した段階では収益と費用のいずれも計上せず、各期に発生した原価は未成工事支出金として繰り越し、引渡年度に完成工事原価とする。',true,
 '正しい。工事完成基準は販売基準を請負工事に当てはめた方法で、引渡し完了時に収益を認識する。それまでの発生原価は製造業の仕掛品に当たる未成工事支出金（資産）となる。',5155),
('f3-056','2035','標準','工事損失引当金は工事進行基準を適用している場合にのみ計上され、工事完成基準を適用している工事では工事損失が見込まれても計上しない。',false,
 '誤り。いずれの基準でも、工事原価総額が工事収益総額を超過する可能性が高く合理的に見積れる場合は、既計上損益を控除した超過見込額を損失処理し工事損失引当金を計上する。',5156),
('f3-057','2035','応用','請負金額1,000億円、見積総工事原価800億円で、各期の実際発生原価が第1期200億円、第2期240億円であった。見積りに変更がなければ、第2期の工事利益は60億円である。',true,
 '正しい。第2期末の累計進捗度は440／800＝55％で累計収益550億円、第1期の収益250億円を差し引いた第2期収益は300億円である。原価240億円を引くと工事利益は60億円となる。',5157),
('f3-058','2035','標準','発生した労働時間や機械使用時間は、移転した財やサービスが顧客にもたらす価値を直接見積もるアウトプット法の指標である。',false,
 '誤り。労働時間、機械使用時間、発生コスト、消費した資源などはインプット法の指標である。アウトプット法の指標には、達成した成果の評価、マイルストーン、生産単位数や引渡単位数などがある。',5158),
('f3-059','2035','応用','取引価格6,000千円の改装工事で、第三者から調達した設備の原価2,000千円を進捗度の測定から除外し、その他の予想原価3,000千円のうち600千円が発生した。この時点の収益は2,800千円である。',true,
 '正しい。進捗度は600／3,000＝20％である。（6,000－2,000）×20％＝800千円に、調達設備分を原価と同額の2,000千円（利益ゼロ）で加え、収益は2,800千円となる。',5159),
('f3-060','2035','標準','11月1日に1年分の賃貸料（月額200万円）を前受けした3月決算の会社は、決算日に未経過7ヵ月分の1,400万円を未収収益として資産の部に計上する。',false,
 '誤り。対価は受け取ったがまだ提供していない期間の分は、前受収益（前受家賃）という負債とする。金額は200万円×7ヵ月＝1,400万円である。',5160),
('f3-061','2035','標準','3月決算の会社が1月1日から月額8万円で清掃サービスを提供し、料金は6月末にまとめて受け取る。決算日には3ヵ月分24万円を売上高に計上し、同額を未収収益とする。',true,
 '正しい。提供済みのサービスの代金が未収のときは、経過期間に見合う額を当期の収益とし、未収収益を計上する。8万円×3ヵ月＝24万円である。',5161),
('f3-062','2035','基礎','ASBJの討議資料である概念フレームワークでは、多義的な「実現」に代えて、純利益や収益・費用の認識を包摂的に説明する用語として「投資のリスクからの解放」を用いている。',true,
 '正しい。投資のリスクとは投資成果の不確定性であり、投資のリスクからの解放とは、投資時に期待した成果が事実として確かになることをいう。',5162),
('f3-063','2035','標準','事業投資では、製品を生産して在庫として保有した段階で、販売計画に基づく期待キャッシュフローが見積れれば収益が実現したとみなされる。',false,
 '誤り。事業投資では、生産しても販売前は販売の不確実性が解消されていない。販売により対価が流入してキャッシュを得たことが事実で確認された時点で収益の実現とみなす。',5163),
('f3-064','2035','標準','いつでも換金できる市場がある金融資産に余剰資金を投じる金融投資では、市場価格の変動が投資成果を左右するため、売却しなくても年度中の時価評価差額が成果とみなされる。',true,
 '正しい。金融投資では市場価格が事前の期待と事後の事実を兼ねて表すため、時価が動けば投資成果はすでに実現したと考える。事業目的に拘束された子会社株式などは別である。',5164),
('f3-065','2035','基礎','収益を計上する時点で分類した収益認識基準には生産基準・販売基準・現金基準の3つがあり、原則的な基準は商品・製品を引き渡した時点で計上する販売基準である。',true,
 '正しい。生産時点の生産基準や代金回収時点の現金基準は例外的な基準とされる。販売基準が原則である点は、2021年4月から適用されている収益認識会計基準でも変わらない。',5165),
('f3-066','2035','基礎','建設や造船などに多い受注生産は、市場の需給を見ながら生産量を自ら決めるため、市場見込み生産よりも在庫を抱えるリスクが大きい。',false,
 '誤り。受注生産は取引先との請負契約に応じて原材料の仕入れや生産を行うため、通常は在庫リスクがない。需給の不一致から在庫や機会損失が生じるのは市場見込み生産である。',5166),
('f3-067','2036','基礎','一般事業会社の売買目的有価証券について、期末の時価が帳簿価額を上回った場合、その差額は有価証券運用益として特別利益に計上する。',false,
 '誤り。売買目的有価証券の評価差額は有価証券運用損益として処理し、運用益は営業外収益、運用損は営業外費用として損益計算書に計上する。',5167),
('f3-068','2036','基礎','満期保有目的の債券は、1年以内に満期が到来するものは有価証券として、1年を超えて満期が到来するものは投資有価証券として貸借対照表に表示する。',true,
 '正しい。満期保有目的の債券の評価は原則として取得原価（または償却原価）により、満期までの期間に応じて有価証券または投資有価証券として表示される。',5168),
('f3-069','2036','標準','償却原価法を適用する満期保有目的の債券では、損益計算書の有価証券利息に、クーポン受取額のほか金利調整差額の償却分も含まれる。',true,
 '正しい。償却原価法は取得価額と額面金額との差額を利息期間にわたって配分する方法であり、その配分額はクーポン受取額とともに有価証券利息として計上される。',5169),
('f3-070','2036','基礎','債券の発行時に市場利子率が約定利子率（クーポンレート）より低い場合、その債券は額面未満で発行されるアンダーパー発行となる。',false,
 '誤り。市場利子率の方が低ければ額面を超える金額で発行できるオーバーパー発行となる。市場利子率の方が高い場合に額面未満でしか発行できないアンダーパー発行となる。',5170),
('f3-071','2036','標準','償却原価法で金利調整差額を配分する方法は利息法を原則とするが、継続して適用することを条件に簡便な定額法も採用できる。',true,
 '正しい。利息法は帳簿価額に実効利子率を乗じた利息配分額とクーポン受取額の差を償却額とする方法、定額法は差額を毎期一定額ずつ配分する方法である。',5171),
('f3-072','2036','応用','帳簿価額950万円の満期保有目的の債券に利息法を適用し、実効利子率4％、当期のクーポン受取額20万円とすると、当期の金利調整差額の償却額は18万円、期末帳簿価額は968万円となる。',true,
 '正しい。利息配分額は950万円×4％＝38万円で、これからクーポン20万円を差し引いた18万円が償却額である。帳簿価額に加算して968万円となる。',5172),
('f3-073','2036','応用','額面3,000万円の社債を2,880万円で取得し、満期まで4年保有する。差額が金利の調整と認められ定額法で処理する場合、毎期の償却額は40万円となる。',false,
 '誤り。定額法では（額面金額－取得価額）を取得から満期までの年数で割る。（3,000－2,880）÷4年＝30万円が毎期の償却額で、帳簿価額は毎期30万円ずつ増える。',5173),
('f3-074','2036','基礎','額面より高い価額で取得した債券について、償却原価法により帳簿価額を毎期一定額ずつ減額していくことをアキュムレーションという。',false,
 '誤り。額面より高く取得し毎期減額するのはアモチゼーションである。額面より低い価額で取得し毎期増額することがアキュムレーションである。',5174),
('f3-075','2036','標準','市場価格のない子会社株式について実質価額が著しく低下した場合は、実質価額を貸借対照表価額とし、帳簿価額との差額を子会社株式評価損として特別損失に計上する。',true,
 '正しい。市場価格のない子会社・関連会社の株式は実質価額（1株当たり純資産額）まで切り下げる。子会社株式は子会社株式評価損、関連会社株式は投資有価証券評価損として特別損失とする。',5175),
('f3-076','2036','基礎','その他有価証券に区分される市場価格のない株式等も、期末には合理的に算定した時価で評価し、評価差額を純資産の部に計上する。',false,
 '誤り。その他有価証券のうち市場価格のない株式等（非上場株式や出資金など）は、時価評価せず、取得原価で貸借対照表に計上する。',5176),
('f3-077','2036','標準','政策保有株式など、売買目的にも支配目的にも当たらないが事業上の目的で換金が制約されている株式は、その他有価証券に区分される。',true,
 '正しい。政策保有株式は純投資目的以外の目的で保有する投資株式である。その他有価証券は時価で評価されるが、評価差額は売却まで損益計算書に反映させない。',5177),
('f3-078','2036','標準','市場価格がある満期保有目的の債券の時価が大幅に下がり、回復が見込めない場合、時価まで切り下げた評価差額は投資有価証券評価損として営業外費用に計上する。',false,
 '誤り。この評価差額は当期の損失とし、特別損失の投資有価証券評価損として損益計算書に計上する。',5178),
('f3-079','2036','標準','時価算定会計基準でいう時価とは、算定日に市場参加者どうしの秩序ある取引を想定したときに、資産を売れば受け取り、負債を移転すれば支払うことになる価格をいう。',true,
 '正しい。時価算定会計基準5項の定義である。同基準は2019年7月に公表され、金融商品とトレーディング目的の棚卸資産の時価に適用される。',5179),
('f3-080','2036','基礎','2019年公表の時価算定会計基準はIFRS第13号の定めの一部しか取り入れていないため、時価の定義には現在もIFRSとの差異が残っている。',false,
 '誤り。時価算定会計基準はIFRS第13号の定めを基本的に全面的に取り入れており、時価の定義に関する両者の差異は解消された。',5180),
('f3-081','2036','応用','期首に1株400円で20万株を取得した売買目的の株式の期末時価は、1期目430円、2期目410円だった。3期目に1株450円で全株を売却すると、3期目の売却益は800万円である。',true,
 '正しい。売買目的有価証券は毎期末の時価に評価替えされるため、売却時の帳簿価額は2期目末時価の410円である。（450円－410円）×20万株＝800万円が売却益となる。',5181),
('f3-082','2036','応用','1株400円で20万株を取得した関連会社株式を、期末時価が1期目430円、2期目410円と推移した後、3期目に1株450円で全株売却した。個別損益計算書の売却益は800万円である。',false,
 '誤り。関連会社株式は時価評価せず取得原価のまま据え置くため、売却時の帳簿価額は400円のままである。売却益は（450円－400円）×20万株＝1,000万円となる。',5182),
('f3-083','2036','応用','当期取得の売買目的株式（評価益150）、額面で取得した満期保有債券（時価上昇50）、上場子会社株式（時価上昇200）、その他有価証券（評価益300）を保有する。当期純利益に反映される評価益は150である。',true,
 '正しい。売買目的有価証券の評価益のみが当期純利益に入る。額面取得の満期保有債券と子会社株式は時価評価せず、その他有価証券の評価差額は純資産の部に計上される。',5183),
('f3-084','2037','基礎','その他有価証券の評価差額は全部純資産直入法で処理するのが原則であり、継続適用を前提に部分純資産直入法を選ぶこともできる。',true,
 '正しい。評価差額は洗い替え法により全部純資産直入法または部分純資産直入法で処理する。全部純資産直入法が原則で、部分純資産直入法は継続適用が条件となる。',5184),
('f3-085','2037','基礎','その他有価証券の洗い替え法とは、前期末に計上した評価差額を当期首に戻し入れ、帳簿価額をいったん取得原価に戻す方法である。',true,
 '正しい。洗い替え法により毎期首に帳簿価額が取得原価に戻るため、その他有価証券の売却損益は原則として売却価額と取得原価との差額で算定される。',5185),
('f3-086','2037','基礎','その他有価証券の評価差額の処理方法は、保有するすべての有価証券に同じ方法を適用しなければならず、株式と債券など種類ごとに異なる方法を選ぶことは認められない。',false,
 '誤り。株式、債券といった有価証券の種類別に、全部純資産直入法か部分純資産直入法かを選んで適用できる。',5186),
('f3-087','2037','応用','その他有価証券のP社株（原価40・時価50）、Q社株（原価45・時価30）、R社債（原価62・時価70）を部分純資産直入法で処理すると、税効果を無視して評価差額金は18、評価損は15となる。',true,
 '正しい。評価益の銘柄P（＋10）とR（＋8）の合計18は純資産の部のその他有価証券評価差額金とし、評価損の銘柄Q（－15）は当期の損失となる。',5187),
('f3-088','2037','応用','その他有価証券のS社株（評価益25）とT社株（評価損10）に全部純資産直入法を適用すると、評価差額金25を純資産の部に計上し、評価損10は当期の損失とする。',false,
 '誤り。全部純資産直入法では、評価損と評価益を相殺した額を純資産の部に計上し、損益計算書に評価損は計上しない（強制評価減を除く）。評価差額金は25－10＝15となる。',5188),
('f3-089','2037','標準','税効果を無視すれば、評価益と評価損の銘柄が混在していても、自己資本比率はどちらの方法でも同じだが、自己資本利益率は部分純資産直入法を採る方が低い。',true,
 '正しい。純資産の合計額は両方法で等しいが、部分純資産直入法だと評価損が当期純利益を押し下げるため、分子の利益が小さくなり自己資本利益率が低くなる。',5189),
('f3-090','2037','標準','部分純資産直入法では、評価損が生じた銘柄の評価差額だけでなく、評価益が生じた銘柄の評価差額も当期の利益として損益計算書に計上する。',false,
 '誤り。部分純資産直入法では評価益の銘柄の評価差額は純資産の部に計上し、評価損の銘柄のみを当期の損失とする。どちらの方法でも評価益は損益計算書に計上されない。',5190),
('f3-091','2037','標準','取得原価300のその他有価証券の前期末時価が360（評価差額金60）で、当期に400で売却した。洗い替え法による場合、当期の投資有価証券売却益は100である。',true,
 '正しい。期首に評価差額が振り戻され帳簿価額は取得原価300に戻るため、売却益は400－300＝100となる。前期に計上した評価差額金60はリサイクリングによりその他の包括利益から減額される。',5191),
('f3-092','2041','基礎','現金主義は支出に基づいて費用を計上するため客観性・確実性に優れる一方、収益と対応させて利益を計算するうえでは合理性に欠ける。',true,
 '正しい。掛取引が主流の経済では、支払時点まで費用の計上を遅らせることは合理的とはいえない。そこで経済的価値の消費に基づく発生主義が費用認識の一般的基準とされる。',5192),
('f3-093','2041','標準','債務が発生した時点で費用を認識する債務確定基準によれば、減価償却費のような価値の消費も反映でき、期間損益を適正に算定できる。',false,
 '誤り。債務の発生に基づくだけでは減価償却費など収益獲得のために消費された経済的価値を反映できず、期間損益を適正に算定できない。そのため今日では発生主義が採用されている。',5193),
('f3-094','2041','応用','単価200円の商品300個を現金で仕入れ、当期に250個を単価260円で現金販売した。当期の利益は現金主義では5,000円、発生主義では15,000円となる。',true,
 '正しい。売上は65,000円である。現金主義の費用は仕入支出60,000円で利益5,000円、発生主義の売上原価は販売した250個分の50,000円で利益15,000円となる。',5194),
('f3-095','2041','応用','単価200円で仕入れて前期から繰り越した商品50個を、当期に単価260円ですべて現金販売した。当期に仕入がない場合、発生主義による当期の利益は13,000円である。',false,
 '誤り。13,000円は仕入支出がない現金主義による利益である。発生主義では販売した50個の原価10,000円を売上原価とするので、利益は3,000円となる。',5195),
('f3-096','2041','標準','引当金の計上は、財・サービスの消費がすでに生じているが支出がまだ行われていない「消費が支出に先行するパターン」の代表例である。',false,
 '誤り。引当金は、支出も消費もまだ生じていない将来の費用を見積計上するパターンである。消費が支出に先行するパターンの例は費用の見越しである。',5196),
('f3-097','2041','標準','発生主義のもとでは、費用認識のパターンにかかわらず、費用は経済的価値の消費によって認識され、その金額は支出に基づいて測定される。',true,
 '正しい。消費と支出が一致する給料、支出が先行する仕入、将来費用の引当金、消費が先行する見越しのいずれでも、費用は消費で認識し支出に基づいて測定する。',5197),
('f3-098','2041','基礎','2期間にわたる取引を通算すると、売上と売上原価の合計額は現金主義と発生主義とで異なるため、2期間合計の利益も両者で一致しない。',false,
 '誤り。各期の利益は異なっても、通算すれば売上と売上原価の合計は両方式で一致する。発生主義はキャッシュフローの期間配分の手続きだからである。',5198),
('f3-099','2042','基礎','費用と収益の直接的対応（個別的対応）の典型例は、売上高と売上原価の関係であり、販売された商品の原価がその売上高に対応づけられる。',true,
 '正しい。売上高と売上原価は直接的（個別的）に対応する。これに対し、販売費や一般管理費は売上高との関係が間接的であり、期間的対応と呼ばれる。',5199),
('f3-100','2042','基礎','販売費や一般管理費は、売上高と個別に結びつけられるため、売上原価と同じく直接的対応によって当期の費用とされる。',false,
 '誤り。販売費・一般管理費は売上高と直接結びつくとは限らないが、売上高の獲得に何らかの形で役立っていると推測されるため、間接的対応（期間的対応）とされる。',5200),
('f3-101','2042','標準','収益の獲得に貢献しなかった損失は、費用収益対応の原則に忠実に従うと損益計算に含められないが、実際に価値は減少しているため、損失が生じた期間の損益に算入する。',true,
 '正しい。発生主義で認識された費用は費用収益対応の原則で選別されるが、損失は収益と対応しなくても実際に価値が減っているので、発生期間の損益に算入する。',5201),
('f3-102','2042','基礎','将来の特定の費用で、発生の可能性が高く金額を合理的に見積もれるものであれば、その発生原因が当期以前の事象でなくても引当金を計上できる。',false,
 '誤り。引当金の計上には、将来の特定の費用又は損失であること、発生が当期以前の事象に起因すること、発生の可能性が高いこと、金額を合理的に見積れることの4要件をすべて満たすことが必要である。',5202),
('f3-103','2042','標準','収益認識会計基準の適用で変動対価を返金負債として処理することになったため、企業会計原則注解18に例示されていた返品調整引当金と売上割戻引当金は廃止された。',true,
 '正しい。返品権付き販売では返品見込分を返金負債とし、売上割戻も変動対価として返金負債で処理する。このため両引当金は廃止された。',5203),
('f3-104','2042','標準','製品保証引当金8,000円を計上していたところ、修理費11,000円を支払った。引当金8,000円を取り崩し、超過する3,000円は製品保証費などとして処理する。',true,
 '正しい。支出時に引当金を取り崩し、引当額を上回る修理費は製品保証費等の名目で営業外費用または特別損失に計上する。',5204),
('f3-105','2042','標準','製品保証引当金は、会計上の4つの計上要件を満たせば、繰入額を計上した時点で税務上も損金算入が認められる。',false,
 '誤り。税法上損金算入が認められる引当金は貸倒引当金などに限られる。製品保証引当金は繰入時点では損金算入できず、実際に費用負担が生じたときに損金算入される。',5205),
('f3-106','2042','標準','費用収益対応の原則では、まず当期に発生した費用を確定し、それに見合う収益を選び出して当期の収益とする。',false,
 '誤り。費用収益対応の原則で対応の基準になるのは収益である。発生した費用の中から、実現した収益に対応する部分を当期の費用とする。',5206),
('f3-107','2042','基礎','企業会計原則注解18に例示された退職給与引当金は、退職給付会計基準の適用により、企業年金も含めた退職給付全体に係る負債として、退職給付引当金と呼ばれることになった。',true,
 '正しい。退職給付引当金は退職一時金に加え企業年金も対象とする負債であり、資産項目ではない。',5207),
('f3-108','2043','基礎','不動産会社が販売目的で保有する土地・建物や、証券会社が販売目的で保有する有価証券は、通常の営業過程で販売するために保有する財貨として棚卸資産に分類される。',true,
 '正しい。棚卸資産の第1のグループは通常の営業の中で販売目的で保有する財貨・用役であり、業種によっては土地・建物や有価証券も棚卸資産となる。',5208),
('f3-109','2043','基礎','製造過程の途中にあって、その状態ではまだ販売できないものを半製品といい、製造途中でも販売可能なものを仕掛品という。',false,
 '誤り。説明が逆である。製造過程にありその状態では販売できないものが仕掛品、未完成であっても販売可能なものが半製品である。建設会社の半成工事も後者に該当する。',5209),
('f3-110','2043','標準','連結財務諸表規則では、棚卸資産のうち資産総額の5％以下で一括表示が適当なものは、適当な名称の科目で一括して掲記できるとされている。',false,
 '誤り。一括掲記が認められるのは資産総額の1％以下の場合である。原則は「商品及び製品（半製品を含む。）」「仕掛品」「原材料及び貯蔵品」の科目で掲記する。',5210),
('f3-111','2043','標準','材料費120、労務費40、経費50、仕掛品の期首残高20・期末残高30、製品の期首残高35・期末残高25、売上高350の製造業者の売上総利益は140である。',true,
 '正しい。当期製品製造原価は20＋120＋40＋50－30＝200、売上原価は35＋200－25＝210となる。売上総利益は350－210＝140である。',5211),
('f3-112','2043','標準','有価証券報告書で開示される製造原価明細書は、提出会社の個別財務諸表だけでなく、連結財務諸表についても作成・開示が求められている。',false,
 '誤り。製造原価明細書の開示は提出会社の個別財務諸表に限られ、連結財務諸表についての製造原価明細書は求められていない。',5212),
('f3-113','2043','標準','2014年の財務諸表等規則の改正により、連結財務諸表でセグメント情報を注記している会社は、個別財務諸表に製造原価明細書を添付しないことができる。',true,
 '正しい。単体開示簡素化の一環である。セグメント情報を開示しない単一事業の会社などには、引き続き同明細書の添付が求められる。',5213),
('f3-114','2043','標準','定期棚卸法は、期首数量と受入数量の合計から実地棚卸数量を差し引いて払出数量を求めるため、紛失や盗難による減少を正規の消費量と区別して把握できる。',false,
 '誤り。定期棚卸法では払出数量を間接的に把握するため、紛失や盗難による減少分も消費量に含めてしまう可能性がある。継続記録法と併用することで両者を区別できる。',5214),
('f3-115','2043','基礎','個別法は、取得原価が異なる棚卸資産をそれぞれ分けて記録するため手間がかかり、比較的高価で個別に在庫管理できる貴金属などを扱う企業に向いている。',true,
 '正しい。個別法は記録に手間を要するため多品種を扱う企業にはなじまない。高価で個別管理が可能な商品・製品を扱う企業に向くとされる。',5215),
('f3-116','2043','基礎','物価が上昇し続ける局面で先入先出法を採用すると、新しく高い単価の在庫から払い出されるため、売上原価が大きくなり売上総利益は小さめに計算される。',false,
 '誤り。先入先出法では先に取得した安い単価の在庫から払い出されるため、インフレ時には売上原価が低く、売上総利益が多めに計算される。期末在庫は時価に近い価額となる。',5216),
('f3-117','2043','基礎','総平均法は、期末にまとめて1回平均単価を計算すれば済むため事務が簡単な反面、期末にならないと払出単価が分からないという欠点がある。',true,
 '正しい。総平均法は受入れた棚卸資産の金額合計を数量合計で割って単価を出す。新たな受入れのたびに単価を計算し直すのは移動平均法である。',5217),
('f3-118','2043','応用','期首在庫50個（単価200円）に100個（単価220円）を仕入れ、120個を払い出した。先入先出法によると期末棚卸資産は6,000円である。',false,
 '誤り。先入先出法では期首の50個と仕入分の70個が払い出され、売上原価は10,000＋15,400＝25,400円となる。期末に残るのは単価220円の30個で、期末棚卸資産は6,600円である。',5218),
('f3-119','2043','応用','期首在庫100個（単価100円）に100個（単価120円）を仕入れて150個を払い出し、その後50個（単価130円）を仕入れた。移動平均法では、最後の仕入後の平均単価は120円である。',true,
 '正しい。最初の仕入後の平均単価は110円で、150個の払出後に50個（5,500円）が残る。これに6,500円を加えると100個で12,000円となり、平均単価は120円である。',5219),
('f3-120','2043','応用','期首商品の原価30,000円・売価40,000円、当期仕入原価120,000円、原始値入額30,000円、値上額15,000円、値下額5,000円で、期末売価が20,000円のとき、売価還元原価法による期末棚卸高は15,000円である。',true,
 '正しい。原価率は（30,000＋120,000）÷（40,000＋120,000＋30,000＋15,000－5,000）＝150,000÷200,000＝75％で、期末棚卸高は20,000円×75％＝15,000円となる。',5220),
('f3-121','2043','標準','棚卸資産の評価方法を変更すると、各年度の売上原価が変わるだけでなく、全期間を通算した売上原価の総額も変わることになる。',false,
 '誤り。評価方法によって各年度の売上原価と期末在庫への配分は異なるが、原価の総額自体は変わらないため、全期間を通算した売上原価の総額は等しくなる。',5221),
('f3-122','2044','基礎','帳簿上の在庫数量より実地棚卸による数量が少ない場合、その不足数量に棚卸資産の原価を乗じた額を棚卸減耗損とする。',true,
 '正しい。例えば原価100円の商品が帳簿上1,000個で実地棚卸が980個なら、20個×100円で2,000円の減耗損となる。',5222),
('f3-123','2044','基礎','毎期繰り返し正常な数量の範囲内で生じる棚卸減耗損は、原価性がないものとして特別損失に計上する。',false,
 '誤り。毎期正常な範囲で生じる減耗は営業上避けられないため原価性があるとされ、売上原価または販売費に含める。臨時的・異常な減耗は原価性がなく特別損失（僅少なら営業外費用も可）とする。',5223),
('f3-124','2044','標準','臨時的に異常な数量の棚卸減耗が生じた場合は原価性がないため特別損失とするが、金額が僅少なら重要性を考慮して営業外費用とすることもできる。',true,
 '正しい。原価性のない減耗損は売上高と対応させるのが合理的でないため特別損失とする。金額が僅少なら営業外費用への計上も認められる。',5224),
('f3-125','2044','標準','製造業の原材料の期末評価では、正味売却価額が再調達原価と連動して動く場合であっても、再調達原価を用いることは認められない。',false,
 '誤り。原材料等は再調達原価の方が把握しやすいため、正味売却価額が再調達原価に比例して変動するなら、継続適用を条件として最終仕入原価を含む再調達原価を用いることができる。',5225),
('f3-126','2044','基礎','棚卸資産の期末評価で取得原価と比べる正味売却価額は、売価から見積追加製造原価と見積販売直接経費を差し引いた額である。',true,
 '正しい。この売価は、購買市場と売却市場が分かれる場合の売却市場の時価をいう。正味売却価額が取得原価を下回るときは正味売却価額を貸借対照表価額とする。',5226),
('f3-127','2044','応用','原価500円の商品500個について、X1年度末の正味売却価額が470円、X2年度末（数量同じ）が490円であった。切放し法では、X2年度末に5,000円の商品評価損を計上する。',false,
 '誤り。切放し法ではX1年度末に切り下げた470円が新たな簿価となり、X2年度末の正味売却価額490円を下回らないため評価損は計上しない。5,000円の評価損を計上するのは洗い替え法の場合である。',5227),
('f3-128','2044','応用','帳簿上は原価150円の商品が3,000個あるが実地棚卸では2,950個で、期末の正味売却価額は140円であった。棚卸減耗損は7,500円、商品評価損は29,500円で、期末商品棚卸高は413,000円となる。',true,
 '正しい。減耗損は150円×50個＝7,500円、評価損は（150－140）円×2,950個＝29,500円である。期末商品棚卸高は140円×2,950個＝413,000円となる。',5228),
('f3-129','2044','標準','収益性の低下による棚卸資産の簿価切下額は、原則として営業外費用に計上し、売上原価には含めない。',false,
 '誤り。収益性低下による簿価切下額は売上原価として表示する。製造に不可避的に発生するものは製造原価とし、重要な事業部門の廃止や災害など臨時の事象に起因し多額なときは特別損失とする。',5229),
('f3-130','2044','標準','企業会計基準第9号では、品質低下や陳腐化による評価損も市場価格の下落による評価損も、収益性の低下という点で相違はないとして、区分せずに会計処理する。',true,
 '正しい。かつては原価性の有無で計上区分が異なっていたが、同基準では正味売却価額の下落による収益性の低下という点で共通するため、区分して処理する意義は乏しいとした。',5230),
('f3-131','2045','基礎','建設仮勘定は、製作途上の建物や機械装置に投入したコストを集計する勘定であり、価値が減少していくため毎期減価償却を行う。',false,
 '誤り。建設仮勘定は未だ営業活動に使用されていないため減価償却の対象とならず、土地と同じく非償却資産に分類される。',5231),
('f3-132','2045','基礎','鉱山、油井、山林のように採掘や伐採によって数量的に減少する減耗性資産は、資源の見積数量をもとに消費分を償却する減耗償却により原価配分する。',true,
 '正しい。有形固定資産は償却資産・減耗性資産・非償却資産に分類され、償却資産は減価償却、減耗性資産は減耗償却を行い、非償却資産は原価配分を要しない。',5232),
('f3-133','2045','基礎','購入した有形固定資産の付随費用のうち重要性が乏しいものは、取得原価に算入しないことが認められる。',true,
 '正しい。購入した有形固定資産の取得原価は購入代価に付随費用（引取運賃・荷役費・買入手数料・据付費等）を加えたものだが、重要性の乏しい付随費用は含めなくてもよい。',5233),
('f3-134','2045','応用','機械を500万円で取得し、4年後の除去に法令上20万円の支出が見込まれる。割引率3％で資産除去債務を計上すると、機械の取得原価は約517.8万円となる。',true,
 '正しい。除去支出の現在価値は20万円÷1.03^4≒17.77万円で、これを資産除去債務として負債に計上し、同額を取得原価に加える。500＋17.77≒517.8万円となる。',5234),
('f3-135','2045','標準','自家建設した有形固定資産については、建設に要した借入金の利子は、建設との関係が明確であっても、資産の原価に加えることはできない。',false,
 '誤り。自家建設の取得原価は適正な原価計算基準による製造原価である。建設中の借入金利子は、関係が明確な場合に限り例外として取得原価に含められる。',5235),
('f3-136','2045','標準','現物出資で受け入れた有形固定資産は、交付した自社株式の公正な評価額と受け入れた資産の公正な評価額のうち、より高い信頼性で測定できる方を取得原価とする。',true,
 '正しい。実務ではまず受入資産の時価等を評価して交付株式数を決めるので、通常は交付した株式の発行価額と受け入れた資産の時価が等しくなる。',5236),
('f3-137','2045','標準','自己所有の固定資産と交換して有形固定資産を受け入れた場合、受け入れた資産の時価で取得原価を決めなければならない。',false,
 '誤り。交換に供した自己の資産が固定資産の場合、その資産の適正な簿価を取得原価とする。交換に供したのが自己所有の株式や社債等なら、その時価または適正な簿価とする。',5237),
('f3-138','2045','基礎','有形固定資産の耐用年数を延ばしたり価値を高めたりする追加支出は、修繕として収益的支出に分類され、支出した年度の費用となる。',false,
 '誤り。耐用年数の延長や資産価値の増加をもたらす支出は改良であり資本的支出として資産の価額に加算する。単なる現状維持のための定期的な補修等が修繕で収益的支出となる。',5238),
('f3-139','2046','基礎','日本基準には、IAS第38号のように無形資産を包括的に定義し会計処理を定めた会計基準があり、国際会計基準との収れんは完了している。',false,
 '誤り。日本基準には現在のところIAS第38号や米国Topic350のような無形資産の会計基準はなく、企業会計原則、企業結合会計基準、研究開発費等に係る会計基準に個別の定めがあるだけである。',5239),
('f3-140','2046','標準','自家創設した特許権などの法律上の権利の取得原価は、調査・研究等に要した支出額に、出願料や登録料などの付随費用を加えた額である。',true,
 '正しい。法律上の権利の取得原価は取得方法で異なり、購入は購入代価と付随費用、現物出資は交付株式の発行価額、交換は自己資産の適正な簿価、贈与は公正な評価額による。',5240),
('f3-141','2046','基礎','研究開発を目的として制作したソフトウェアの制作費は、将来の収益獲得に役立つと見込まれれば、無形固定資産として計上することができる。',false,
 '誤り。研究開発を目的とするソフトウェアの制作費は研究開発費に当たるため、発生時に費用とする。',5241),
('f3-142','2046','標準','受注制作のソフトウェアに要した制作費は研究開発費に該当するため、2021年4月以後も発生時にすべて費用処理する。',false,
 '誤り。受注制作のソフトウェアは収益認識会計基準に従い、履行義務の充足状況や進捗度により処理する。発生原価は売上原価や未成工事支出金などの棚卸資産となる。',5242),
('f3-143','2046','標準','市場販売目的のソフトウェアでは、最初に製品化される製品マスターが完成するまでの制作活動を研究開発とし、それまでに生じた費用を研究開発費として処理する。',true,
 '正しい。製品マスターとは複写して製品を作るためのデータや原版である。製品マスター完成後に行う通常の機能改良・強化の費用は原則として無形固定資産とする。',5243),
('f3-144','2046','標準','市場販売目的のソフトウェアについて、製品マスター完成後に行う著しい改良の費用は、無形固定資産として資産に計上する。',false,
 '誤り。製品マスター完成後でも著しい改良に当たるものは研究開発が終わっていないとみなされ、研究開発費として処理する。資産計上されるのは通常の改良・強化の費用である。',5244),
('f3-145','2046','標準','市場販売目的のソフトウェアの製品マスターの完成時点は、製品として成り立つか判断できる程度の試作品（プロトタイプ）が完成したかどうかなどで判断する。',true,
 '正しい。実務指針では、プロトタイプを作らない場合は、販売に必要な重要機能が完成し、重大な不具合も解消されていることで判断するとしている。',5245),
('f3-146','2046','基礎','無形固定資産は、借地権のように時の経過で価値が減少しない資産を除いて償却を行い、その手続きは有形固定資産の減価償却（depreciation）と区別してamortizationと呼ばれる。',true,
 '正しい。有形固定資産はdepreciation、無形固定資産はamortizationと呼ぶ。税法では無形固定資産について定められた耐用年数で定額法により償却するとされる。',5246),
('f3-147','2046','応用','3億円で受注したソフトウェア制作（総制作原価1.2億円）で、初年度の発生原価が3,000万円であった。進捗度を合理的に見積れる場合、初年度の売上高は7,500万円である。',true,
 '正しい。発生原価に基づく進捗度は3,000万円÷1.2億円＝25％で、売上高は3億円×25％＝7,500万円となる。従来の工事進行基準に相当する処理である。',5247),
('f3-148','2046','応用','3億円で受注したソフトウェア制作（総制作原価1.2億円）で、初年度は進捗度を見積れず、2年目末に累計原価6,000万円で見積可能となった。契約初期段階の代替的な取扱いでは2年目の売上高は1.2億円となる。',false,
 '誤り。初期段階の代替的な取扱いでは初年度は収益も費用も計上せず、2年目に3億円×6,000万円÷1.2億円＝1.5億円を計上する。1.2億円は初年度に原価回収基準で3,000万円を計上した場合の金額である。',5248),
('f3-149','2047','基礎','減価償却は、有形固定資産の期末の時価を貸借対照表に反映させることを目的とした評価の手続きである。',false,
 '誤り。減価償却は時価評価の手続きではなく、規則的に配分した減価償却費を資産の利用による収益と期間的に対応させ、期間損益を適切に計算するためのものである。',5249),
('f3-150','2047','基礎','定額法でも定率法でも、減価償却費を計算するには、取得原価・耐用年数・残存価額の3要素が必要となる。',true,
 '正しい。耐用年数は資産を使用する期間、残存価額は耐用年数経過後の処分価格である。実務では財務省令に従って耐用年数を設定する例が多い。',5250),
('f3-151','2047','標準','2007年度税制改正により償却可能限度額と残存価額が廃止され、耐用年数が経過した時点で帳簿価額がゼロになるまで全額を償却できるようになった。',false,
 '誤り。改正後は耐用年数経過時点で備忘価額の1円まで償却でき、残存簿価1円が残る。従来は残存価額10％や、取得原価の95％を上限とする償却可能限度額が用いられていた。',5251),
('f3-152','2047','標準','取得原価360万円、耐用年数6年、残存価額ゼロの備品を10月1日に取得した3月決算の会社が定額法で月割償却すると、初年度の減価償却費は30万円である。',true,
 '正しい。1年分の減価償却費は360万円÷6年＝60万円で、使用月数6ヵ月の月割により60万円×6／12＝30万円となる。',5252),
('f3-153','2047','応用','取得原価500万円、耐用年数10年の機械に200％定率法（償却率0.2）を適用すると、2年目の減価償却費も1年目と同じ100万円となる。',false,
 '誤り。定率法は期首の未償却残高に償却率を乗じるため、1年目は500万円×0.2＝100万円、2年目は（500－100）万円×0.2＝80万円と逓減する。',5253),
('f3-154','2047','応用','取得原価100万円、耐用年数5年に200％定率法（償却率0.4、改定償却率0.5、保証率0.108）を適用すると、4年目は改定償却率が適用され減価償却費は10.8万円となる。',true,
 '正しい。4年目期首簿価は21.6万円で調整前償却額は8.64万円となり、償却保証額100万円×0.108＝10.8万円を下回る。そこで21.6万円×0.5＝10.8万円となる。',5254),
('f3-155','2047','標準','250％定率法は、2012年4月1日以後に取得した資産に適用される償却方法であり、償却率は1÷耐用年数×2.5で求める。',false,
 '誤り。250％定率法は2007年4月1日～2012年3月31日の取得資産に適用され、2012年4月1日以後の取得資産には200％定率法（1÷耐用年数×2）が適用される。',5255),
('f3-156','2047','標準','100万円で取得した機械（耐用年数4年、残存価額なし）を級数法で償却すると、2年目の減価償却費は25万円である。',false,
 '誤り。級数の総和は1＋2＋3＋4＝10で、2年目は100万円×3／10＝30万円となる。1年目は40万円で、級数法も定率法と同じく初期に多く償却する逓減法である。',5256),
('f3-157','2047','標準','生産高比例法は、総利用可能量を物理的に確定でき、減価が主として利用に伴って生じる資産に限って適用でき、鉱業用設備や航空機などが該当する。',true,
 '正しい。生産高比例法は生産高や利用高に基づき原価配分する方法で、減価償却費＝（取得原価－残存価額）×当期の実際生産量÷総生産可能量で計算する。',5257),
('f3-158','2047','応用','取得原価480万円、残存価額ゼロ、利用可能走行距離20万kmの車両を当期に5万km走行させた場合、生産高比例法による当期の減価償却費は120万円である。',true,
 '正しい。480万円×5万km÷20万km＝120万円となる。生産高比例法は利用度を基準に原価配分する方法である。',5258),
('f3-159','2047','標準','取替法を採用する鉄道のレールなどの取替資産は、通常の減価償却を行い、老朽部分を取り替えたときの支出は資産として計上する。',false,
 '誤り。取替法では取替えまで減価償却を行わず取得原価を維持し、老朽部分を取り替えて新たな資産を調達したときに、その支出を費用として計上する。',5259),
('f3-160','2047','標準','現行の日本基準では臨時償却は廃止され、固定資産の耐用年数の変更については、変更の影響を当期以降の原価配分に反映させるプロスペクティブ方式のみが認められている。',true,
 '正しい。企業会計基準第24号により、2011年4月以後開始年度の期首以後の変更から適用された。変更した期だけで影響を処理する方法はキャッチ・アップ方式と呼ばれる。',5260),
('f3-161','2047','応用','取得原価300万円、耐用年数6年、残存価額ゼロで定額法償却していた機械の残存耐用年数を、3年目の期首に残り3年へ見直した。プロスペクティブ方式による3年目の減価償却費は75万円である。',false,
 '誤り。2年経過後の未償却残高は300万円－50万円×2＝200万円で、これを残り3年で償却するので約66.7万円となる。',5261),
('f3-162','2047','標準','減価償却累計額を有形固定資産全体の控除科目として一括表示する方式では、資産科目別の簿価を把握しにくく、この方式を採る企業はまれである。',true,
 '正しい。表示方法には科目別の控除科目表示、全体の一括控除表示、直接控除して注記する方式がある。科目別に表示すれば資産ごとの償却の進行度を分析できる。',5262),
('f3-163','2047','標準','定率法を採用すると、定額法に比べて耐用年数全体で支払う法人税の総額を減らすことができる。',false,
 '誤り。耐用年数全体の利益や納税総額はどの方法でも同じである。定率法は初期に多く償却するため納税を将来に繰り延べられ、その資金を再投資できる点に利点がある。',5263),
('f3-164','2048','基礎','実務対応報告第19号で繰延資産に計上できるのは、株式交付費、社債発行費等、創立費、開業費、開発費の5項目に限られる。',true,
 '正しい。繰延資産として計上できる項目は限定列挙されており、それぞれ償却方法と償却期間が定められている。これらは支出時に全額費用とすることも選べる。',5264),
('f3-165','2048','基礎','創立費を繰延資産に計上した場合は、会社成立後3年以内のその効果の及ぶ期間にわたり、定額法で償却する。',false,
 '誤り。創立費の償却期間は会社成立後5年以内のその効果の及ぶ期間である。3年以内とされるのは株式交付費と新株予約権発行費である。',5265),
('f3-166','2048','標準','繰延資産に計上した社債発行費は定額法で償却するのが原則であり、継続適用を条件に利息法を採用することもできる。',false,
 '誤り。社債発行費は発行から償還までの期間で利息法により償却するのが原則で、継続適用を条件として定額法も認められる。',5266),
('f3-167','2048','標準','株式交付費を繰延資産に計上した場合は、株式の交付時から3年以内で効果が及ぶ期間にわたり、定額法により償却する。',true,
 '正しい。図表2－1のとおり、株式交付費と新株予約権発行費は3年以内、創立費・開業費・開発費は5年以内の効果の及ぶ期間で償却する。',5267),
('f3-168','2048','基礎','日本の会計基準では、研究開発費を繰延資産に計上したうえで、一定期間で償却することが求められる。',false,
 '誤り。日本基準のもとでは、研究開発費は原則として支出年度に全額を費用として計上する。',5268),
('f3-169','2048','応用','10月1日に開業した3月決算の会社が開業費240万円を繰延資産に計上し、5年（60ヵ月）にわたり月割で定額償却する場合、初年度の償却額は48万円である。',false,
 '誤り。月割計算では240万円÷60ヵ月×6ヵ月＝24万円が初年度の償却額となる。48万円は年数基準で1年分を償却した場合の金額である。',5269),
('f3-170','2048','標準','3月決算の会社が8月1日に1年分の保険料24万円を支払った。決算日には未経過の4ヵ月分8万円を前払保険料として資産に振り替える。',true,
 '正しい。継続的な役務提供の契約で、支払済みだが未提供の役務に対応する部分は当期の費用から切り離して次期に繰り延べる。24万円×4／12＝8万円である。',5270),
('f3-171','2048','標準','継続して役務の提供を受ける契約で、既に提供を受けた役務の対価が未払いの場合、支出が行われるまでは当期の費用として計上しない。',false,
 '誤り。提供済みの役務に対する未払分は未払費用であり、支出がなくても当期の費用に計上する必要がある。これを費用の見越しという。',5271),
('f3-172','2048','標準','3月決算の会社は事務所家賃（月額20万円）を6月末と12月末に6ヵ月分ずつ後払いしている。決算日に見越計上する未払家賃は120万円である。',false,
 '誤り。決算日時点で未払いなのは1月から3月までの3ヵ月分であり、未払家賃は20万円×3ヵ月＝60万円となる。借方は支払家賃（費用）、貸方は未払家賃（負債）である。',5272),
('f3-173','2049','基礎','固定資産の減損処理は、資産の時価変動を帳簿価額に反映させるためのものではなく、取得原価基準のもとで過大な帳簿価額を減額し将来に損失を繰り延べないための処理である。',true,
 '正しい。減損処理は、収益性の低下で投資額を回収できる見込みがなくなったときに、帳簿価額を回収可能性に見合う額まで減らす臨時的な手続きである。',5273),
('f3-174','2049','標準','減損の判定単位は、他の資産グループとはおおむね独立したキャッシュフローをもたらす単位のうち、できるだけ大きなものとする。',false,
 '誤り。資産のグルーピングは、おおむね独立したキャッシュフローをもたらす最小の単位で行う。実務上は管理会計の区分や投資の意思決定単位などを考慮する。',5274),
('f3-175','2049','標準','資産グループを使う営業活動の損益やキャッシュフローがマイナスを続けていることは、減損の兆候の一例である。',true,
 '正しい。減損の兆候には、営業損益等の継続的なマイナス、事業の廃止・再編成など回収可能価額を大きく下げる変化、経営環境の著しい悪化、市場価格の著しい下落がある。',5275),
('f3-176','2049','標準','減損損失を認識するかの判定に使う割引前将来キャッシュフローは、主要資産の経済的残存使用年数と10年のうち短い方の期間で見積もる。',false,
 '誤り。見積期間は経済的残存使用年数と20年のうち短い方である。20年を超えるときは、20年経過時点の回収可能価額を20年目までの割引前の将来キャッシュフローに加える。',5276),
('f3-177','2049','基礎','減損損失の測定に使う回収可能価額は、正味売却価額と使用価値のうち低い方の金額である。',false,
 '誤り。回収可能価額は、売却による回収額（正味売却価額）と使用による回収額（使用価値）のうち高い方である。',5277),
('f3-178','2049','標準','減損会計の使用価値は、資産の継続使用と使用後の処分から見込まれるキャッシュフローを現在価値に割り引いたもので、割引率には貨幣の時間価値を反映する税引前の利率を使う。',true,
 '正しい。使用価値は将来のキャッシュフローを割り引いて求め、割引率は税引後ではなく税引前の利率とされる。',5278),
('f3-179','2049','応用','減損の兆候がある資産の帳簿価額800、割引前将来キャッシュフロー760、使用価値620、正味売却価額650のとき、計上すべき減損損失は150である。',true,
 '正しい。帳簿価額800が割引前将来キャッシュフロー760を上回るため減損を認識し、使用価値620と正味売却価額650の高い方650を回収可能価額とする。減損損失は150となる。',5279),
('f3-180','2049','応用','減損の兆候がある資産の帳簿価額500、割引前将来キャッシュフロー520、使用価値430、正味売却価額410のとき、帳簿価額と使用価値の差額70を減損損失として計上する。',false,
 '誤り。割引前将来キャッシュフロー520が帳簿価額500を上回っているため、減損損失は認識しない。回収可能価額との比較に進むのは、帳簿価額が割引前将来キャッシュフローを上回る場合である。',5280),
('f3-181','2049','標準','日本の減損会計基準では、減損処理の後に回収可能価額が回復した場合、回復した額を限度として減損損失の戻入れを行う。',false,
 '誤り。日本の減損会計基準では減損損失の戻入れは行わない。減損後の減価償却費は、減損処理後の帳簿価額に基づいて計算される。',5281),
('f3-182','2049','標準','減損損失は原則として特別損失とし、貸借対照表では減損前の取得原価から直接差し引くのが原則だが、減損損失累計額として間接的に控除する表示も認められる。',true,
 '正しい。直接控除では、減額後の金額が以後の取得原価となる。累計額を取得原価から間接的に差し引く形式も認められている。',5282),
('f3-183','2050','基礎','金融商品会計基準では、貸倒見積高の算定に当たり、債務者の財政状態と経営成績に応じて債権を一般債権、貸倒懸念債権、破産更生債権等の3つに区分する。',true,
 '正しい。区分ごとに算定方法が異なり、一般債権は過去の貸倒実績率等、貸倒懸念債権は財務内容評価法かキャッシュ・フロー見積法、破産更生債権等は担保・保証による回収見込額の控除による。',5283),
('f3-184','2050','標準','経営破綻には至っていないものの、債務の返済に重大な問題が生じている、またはその可能性が高い債務者への債権は、破産更生債権等に区分する。',false,
 '誤り。これは貸倒懸念債権の説明である。破産更生債権等は、経営破綻している、または実質的に経営破綻している債務者に対する債権である。',5284),
('f3-185','2050','応用','一般債権の期末残高がt－3期2,000、t－2期2,500、t－1期3,000、当期3,600で、各期の貸倒実績がt－2期20、t－1期20、当期18である。期首残高に対する過去3期の平均実績率を用いると、当期の貸倒引当金は28.8となる。',true,
 '正しい。実績率は20÷2,000＝1.0％、20÷2,500＝0.8％、18÷3,000＝0.6％で平均0.8％となる。当期末残高3,600×0.8％＝28.8である。',5285),
('f3-186','2050','標準','貸倒懸念債権の貸倒見積高は、一般債権と同じく、債権をまとめて、または同種の債権ごとに過去の貸倒実績率を用いて算定する。',false,
 '誤り。貸倒懸念債権は、債権の状況に応じて財務内容評価法またはキャッシュ・フロー見積法のいずれかで貸倒見積高を算定する。実績率による算定は一般債権の方法である。',5286),
('f3-187','2050','応用','債権金額1,000万円（約定利子率4％、残存2年）の金利を1％に引き下げる条件緩和を行った。キャッシュ・フロー見積法では、条件緩和後に見込まれるキャッシュフローを緩和後の利率1％で割り引いて貸倒見積高を求める。',false,
 '誤り。キャッシュ・フロー見積法では当初の約定利子率4％で割り引く。緩和後のキャッシュフロー10万円と1,010万円の現在価値は約943.4万円で、帳簿価額との差の約56.6万円が貸倒見積高となる。',5287),
('f3-188','2050','標準','貸倒懸念債権の貸倒見積高の算定方法は、債務者の状況に変化がなくても、各期末に財務内容評価法とキャッシュ・フロー見積法のうち有利な方を選び直すことができる。',false,
 '誤り。債務者の財政状態や経営成績などに変化がない限り、同じ債権には同じ算定方法を継続して適用する。',5288),
('f3-189','2050','標準','一般債権について算定した貸倒見積高は貸倒引当金として計上し、同時に貸倒引当金繰入を当期の費用とする。',true,
 '正しい。債権の貸借対照表価額は取得価額から貸倒見積高に基づく貸倒引当金を控除した金額となり、引当金の設定額は貸倒引当金繰入として費用計上される。',5289),
('f3-190','2051','基礎','企業会計基準第34号「リースに関する会計基準」は、2027年4月1日以後に始まる事業年度の期首から適用され、2025年4月1日以後に始まる事業年度の期首から早期適用することもできる。',true,
 '正しい。同基準はASBJが2024年に、国際的な基準との整合性と比較可能性の向上を目的に公表したもので、使用権モデルを採っている。',5290),
('f3-191','2051','標準','新しいリース会計基準のもとでも、借手はオペレーティング・リースについて賃貸借処理を行い、使用権資産やリース負債を計上しない。',false,
 '誤り。新基準では、借手はリースの形態を問わず原則としてすべてのリースで使用権資産・リース負債を計上する。リースの分類が処理に違いをもたらすのは貸手の会計処理である。',5291),
('f3-192','2051','標準','フルペイアウトの判定における現在価値基準は、貸手のリース料の現在価値が原資産の現金購入価額の概ね75％以上であるかどうかで判断する。',false,
 '誤り。現在価値基準は概ね90％以上である。概ね75％以上という数値は、リース期間が経済的耐用年数のおおむね75％以上かを見る経済的耐用年数基準のものである。',5292),
('f3-193','2051','標準','契約に資産が明記されていれば、貸手が使用期間を通じて資産を入れ替える実質上の能力を持ち、入替えによる経済的利益がコストを上回る場合でも、その資産は特定された資産に当たる。',false,
 '誤り。この場合、貸手は資産を入れ替える実質的な権利を持つとされ、その資産は特定された資産に当たらない。資産が特定できなければ契約にリースは含まれない。',5293),
('f3-194','2051','標準','借手に資産の使用を支配する権利が移ったといえるには、借手が使用によって得られる経済的利益のほぼすべてを受け取り、かつ使用方法を指図する権利を持つことが必要である。',true,
 '正しい。リースの識別は特定された資産の存在と使用を支配する権利の移転で判断し、後者は経済的利益の享受と指図権の両方で判断する。',5294),
('f3-195','2051','応用','契約対価60,000千円の契約で、リースを構成する部分の独立価格が50,000千円、リースを構成しない部分の独立価格が25,000千円であれば、リース部分に配分される対価は40,000千円である。',true,
 '正しい。対価は各部分の独立価格の比率で配分する。60,000×50,000÷75,000＝40,000千円がリース部分、残り20,000千円がリースを構成しない部分となる。',5295),
('f3-196','2051','標準','借手のリース期間は解約不能期間のみで決定し、行使することが合理的に確実な延長オプションの対象期間は含めない。',false,
 '誤り。借手のリース期間は、解約不能期間に、行使することが合理的に確実な延長オプションの期間と、行使しないことが合理的に確実な解約オプションの期間を加えて決定する。',5296),
('f3-197','2051','応用','年額10,000千円を毎期末に3年間支払うリースで、借手の追加借入利子率が4％の場合、リース開始日に計上するリース負債はリース料総額の30,000千円である。',false,
 '誤り。リース負債は未払リース料から利息相当額を控除した現在価値で計上する。4％で割り引くと約27,751千円となり、使用権資産も同額で計上する。',5297),
('f3-198','2051','応用','リース開始日のリース負債が27,751千円、割引率4％、年額リース料10,000千円の期末払いのリースに利息法を適用すると、初年度の支払利息は利息総額を3年で均等に割った約750千円となる。',false,
 '誤り。利息法では未返済元本に一定の利率を乗じるため、初年度の支払利息は27,751×4％≒1,110千円となる。利息総額を均等配分する定額法は重要性が乏しい場合の簡便法である。',5298),
('f3-199','2051','基礎','借手のリース期間が24ヵ月以内で購入オプションのないリースは短期リースとして、使用権資産やリース負債を計上せずにリース料を費用処理できる。',false,
 '誤り。短期リースとは借手のリース期間が12ヵ月以内で購入オプションのないリースである。短期リースは使用権資産等を計上せず、リース料を原則として定額法で費用計上できる。',5299),
('f3-200','2051','標準','新リース会計基準では、旧基準で営業費用とされていたオペレーティング・リースの支払リース料の一部が営業外費用の支払利息となるため、営業利益の改善要因になると考えられる。',true,
 '正しい。一方で使用権資産とリース負債の計上により資産・負債の総額は増え、減価償却費や支払利息の増加は単年度の利益を圧迫する要因になり得る。',5300),
('f4-021','2058','基礎','確定拠出制度では、掛金を拠出した後の運用リスクを従業員が負うので、企業の会計処理は確定給付制度と比べて単純である。',true,
 '正しい。確定拠出制度では取り決めた掛金を拠出すれば企業の義務は消滅し、その後の運用の成否は従業員側に帰する。企業は当期の要拠出額を費用計上するだけでよい。',6121),
('f4-022','2058','基礎','確定拠出制度を採用する企業で、期末時点に当期分の掛金がまだ拠出されていない場合、その金額は「退職給付に係る負債」として計上される。',false,
 '誤り。確定拠出制度で掛金が期末に未拠出であれば、賞与引当金と同じように未払金として負債の部に計上し、実際に拠出した時点で取り崩す。',6122),
('f4-023','2058','標準','確定給付制度では、退職給付債務から年金資産の時価を差し引いた額を、連結では「退職給付に係る負債」、個別では「退職給付引当金」などの科目で固定負債に計上する。',true,
 '正しい。確定給付制度を採る企業の貸借対照表には、退職給付債務と年金資産の時価との差額（積立不足）が、連結・個別で異なる科目名により固定負債の区分に計上される。',6123),
('f4-024','2058','基礎','確定給付制度の内部引当方式では、退職給付の原資として特定の資産が紐付けられ、企業外部の基金で管理される。',false,
 '誤り。内部引当方式（社内積立）では特定の資産が紐付けられているわけではなく、退職給付に充てる原資を企業内部で準備する。外部に積み立てるのは外部積立方式である。',6124),
('f4-025','2058','標準','内部引当方式の企業が従業員の退職時に退職金を支払うと、退職給付に係る負債が取り崩され、同時に企業の現金預金も同じ額だけ減少する。',true,
 '正しい。内部引当方式では、退職給付の支払いによって義務が履行されると負債が取り崩され、企業が支配する資産（通常は現金預金）も同額減少する。',6125),
('f4-026','2058','標準','外部積立方式で退職給付債務と同額の年金資産が積み立てられている場合、年金資産から退職金が支払われると、企業の現金預金が支払額だけ減少する。',false,
 '誤り。外部積立方式では退職給付は企業外部の年金資産から支払われるため、企業が支配する資産は減らず年金資産が減少する。債務も同時に消滅するので、貸借対照表の資産・負債には影響しない。',6126),
('f4-027','2058','標準','複数の確定給付制度をもつ企業では、ある制度の年金資産の超過額を別の制度の退職給付債務から差し引けないため、退職給付に係る資産と負債が同時に計上されることがある。',true,
 '正しい。1つの制度の年金資産が退職給付債務を超えても、その超過分を他制度の債務と相殺できないので、資産と負債が両建てで計上される場合がある。',6127),
('f4-028','2058','標準','内部引当方式では、減価償却費と同様にお金の出ていかない費用を計上し、これに見合う資金が社内に留保されるため、退職金を支払うまでその資金を事業に使えるという副次的な効果がある。',true,
 '正しい。外部積立方式は期待運用収益の分だけ退職給付費用が小さくなるが、年金資産は退職給付以外に使えない。内部引当方式には資金を事業活動に使えるという利点があり、経営者は両者を比較して選ぶと考えられる。',6128),
('f4-029','2058','標準','外部積立方式により積み立てた年金資産は、事業主である企業の資金繰りが苦しくなった場合には、事業活動の資金に充てることができる。',false,
 '誤り。年金資産は法律上、事業主の企業とは切り離されており、退職給付以外の目的には使えない。そのため年金資産への積極的な積立ては、事業に必要な資金の不足を招くおそれがある。',6129),
('f4-030','2058','基礎','確定給付制度を採用する企業は、当期の要拠出額を拠出しさえすれば、将来の給付額について追加の責任を負うことはない。',false,
 '誤り。拠出によって義務が消滅するのは確定拠出制度である。確定給付制度では企業は将来支払う給付の額に責任を持ち続け、積立不足があれば追加負担の義務を負う。',6130),
('f4-031','2059','基礎','期間定額基準とは、退職給付見込額を従業員の全勤務期間で割った金額を、各期に発生した額とする方法である。',true,
 '正しい。期間定額基準では退職給付見込額を全勤務期間に均等に配分する。もう一つの方法である給付算定式基準は、制度の給付算定式に従って各期に帰属させた給付をもとに発生額を見積もる。',6131),
('f4-032','2059','標準','退職給付見込額を各期に配分する方法は期間定額基準が原則であり、給付算定式基準は期間定額基準が使えない場合に限って認められる。',false,
 '誤り。退職給付見込額の期間帰属は、期間定額基準と給付算定式基準のいずれかを企業が選択し、継続して適用する。どちらかが原則という関係ではない。',6132),
('f4-033','2059','応用','勤続2年未満は支給なし、2年以上4年未満は40万円、4年以上は120万円の一時金を支給する制度で、4年勤務後に退職する従業員について給付算定式基準を用いると、3年度目の発生額は40万円である。',true,
 '正しい。最初の2年間の勤務で支給対象となる40万円は1・2年度目に20万円ずつ、残りの80万円は3・4年度目の勤務で支給対象となるため40万円ずつ配分する。4年間の合計は120万円となる。',6133),
('f4-034','2059','標準','日本の会計基準における退職給付債務は、受給権がすでに確定した従業員だけを対象とし、現在の給与水準に基づいて計算される。',false,
 '誤り。退職給付債務は受給権の有無にかかわらず、将来の予想昇給率も考慮して算定する予測給付債務（PBO）である。受給権確定者のみを対象とし現在の給与水準で計算するのは確定給付債務（VBO）である。',6134),
('f4-035','2059','応用','期首の退職給付債務が2,000万円、割引率が2%、当期の勤務費用が300万円で、退職給付の支払いや数理計算上の差異がない場合、期末の退職給付債務は2,340万円となる。',true,
 '正しい。利息費用は期首の退職給付債務×割引率＝2,000万円×2%＝40万円である。期末の債務は2,000万円＋勤務費用300万円＋利息費用40万円＝2,340万円となる。期待運用収益は債務を減らさない。',6135),
('f4-036','2059','基礎','他の事情が一定であれば、退職給付債務の計算に用いる割引率を高く設定するほど、退職給付債務の金額は大きくなる。',false,
 '誤り。割引率が高いほど将来の支払額の現在価値は小さくなるので、退職給付債務は小さくなる。逆に割引率を低くすると債務は大きくなり、退職給付費用はより保守的に計上される。',6136),
('f4-037','2059','標準','退職給付債務や退職給付費用の計算に用いる割引率は、期末時点における国債や優良社債といった信用度の高い債券の利回りをもとに決める。',true,
 '正しい。割引率は、期末の国債、政府機関債、優良社債などの信用度の高い債券の利回りをもとにする。年金資産の運用リスクを反映させて決めるわけではない。',6137),
('f4-038','2059','標準','割引率の基礎となる債券の利回りが期末にマイナスとなった場合について、実務対応報告第34号は利回りの下限をゼロとする方法だけを認めている。',false,
 '誤り。実務対応報告第34号は、利回りの下限としてゼロを用いる方法と、マイナス値をそのまま割引率に使う方法のどちらかを選ぶよう定めている。マイナスの割引率を使えば利息費用はマイナスとなる。',6138),
('f4-039','2059','標準','勤務費用が500、利息費用が60、期首の年金資産が2,000、長期期待運用収益率が3%で、数理計算上の差異と過去勤務費用がない場合、当期の退職給付費用は500となる。',true,
 '正しい。期待運用収益は期首年金資産2,000×3%＝60である。退職給付費用は勤務費用500＋利息費用60－期待運用収益60＝500となる。控除するのは実際の運用収益ではなく期待運用収益である。',6139),
('f4-040','2059','標準','割引率の引下げによって退職給付債務が増加した部分は、その変更を行った期に全額を特別損失として計上しなければならない。',false,
 '誤り。割引率の変更による債務の増減は数理計算上の差異であり、平均残存勤務期間を超えない年数で配分し、当期以降に規則的に費用処理する。',6140),
('f4-041','2059','標準','数理計算上の差異は、毎期発生した額を、平均残存勤務期間を超えない一定年数にわたって規則的に費用化する。',true,
 '正しい。数理計算上の差異は発生額を平均残存勤務期間以内の年数で按分して規則的に費用処理する。未認識の残高に一定率を掛けて費用化する方法も認められている。損益計算書での扱いは個別と連結で同じである。',6141),
('f4-042','2059','応用','当期末に退職給付債務を増やす数理計算上の差異900が発生し、発生年度から3年間で定額で費用処理する場合、当期末の未認識数理計算上の差異は600となる。',true,
 '正しい。900を3年で按分すると1年当たり300であり、発生年度に300を費用処理する。費用処理されていない残り600が、当期末の未認識数理計算上の差異となる。',6142),
('f4-043','2059','標準','数理計算上の差異は、当期に発生した額を翌期から費用処理する方法が認められておらず、発生した年度から費用処理を始めなければならない。',false,
 '誤り。数理計算上の差異は、発生した期の翌期から費用化を始める方法も選べる。この場合、発生年度には費用処理額は生じない。',6143),
('f4-044','2059','標準','個別貸借対照表では、未認識数理計算上の差異も含めて、退職給付の積立状況の全額を負債または資産に計上する。',false,
 '誤り。個別貸借対照表では数理計算上の差異のうち費用処理された部分だけを計上し、未認識部分は計上しない。積立状況をそのまま計上するのは連結貸借対照表である。',6144),
('f4-045','2059','基礎','過去勤務費用とは、年金資産の実際の運用成果と期待運用収益との差によって生じる差異のことをいう。',false,
 '誤り。運用成果と期待運用収益との差は数理計算上の差異である。過去勤務費用は、退職給付水準の改訂によって生じた退職給付債務の増加または減少部分をいう。',6145),
('f4-046','2059','応用','期首に退職給付水準を引き上げたことで過去勤務費用300が生じ、これを当期から5年間で定額で費用処理する場合、当期末の未認識過去勤務費用は180となる。',false,
 '誤り。300を5年で按分すると1年当たり60であり、当期に60が費用処理されるので、当期末の未認識過去勤務費用は300－60＝240となる。',6146),
('f4-047','2059','標準','退職給付水準を引き下げて退職給付債務が減少した場合も過去勤務費用にあたり、その費用処理額は退職給付費用を減らす方向に働く。',true,
 '正しい。水準の引下げによる債務の減少も過去勤務費用であり、引上げの場合に準じて処理される。このとき費用処理額は退職給付費用の減算項目となる。',6147),
('f4-048','2059','基礎','割引率を引き上げたことで退職給付債務が減少した場合、その減少額も数理計算上の差異として扱われる。',true,
 '正しい。割引率の引上げによる債務の減少も数理計算上の差異であり、引下げのときと同じ考え方で処理する。数理計算上の差異は発生原因により加算項目にも減算項目にもなる。',6148),
('f4-049','2064','基礎','税務申告では、税引前当期純利益に益金算入項目と損金不算入項目を加え、益金不算入項目と損金算入項目を差し引いて課税所得を求める。',true,
 '正しい。会計上の利益と課税所得のずれは4つに分類され、益金算入・損金不算入項目は加算、益金不算入・損金算入項目は減算して課税所得を算定する。',6149),
('f4-050','2064','基礎','課税所得の計算上、受取配当金のうち益金に算入されない額は、税引前当期純利益に足し戻す加算項目として扱う。',false,
 '誤り。受取配当金は会計上は収益だが課税所得計算上は益金とならない益金不算入項目なので、税引前当期純利益から減算する。',6150),
('f4-051','2064','標準','法人税や住民税、事業税（所得割）などの所得に対する税金について、企業は事業年度終了日の翌日から2か月以内に申告・納付する。',true,
 '正しい。企業は1会計期間の所得に基づいて税額を計算し、期末日の翌日から2か月以内に申告して納める。損益計算書では税引前当期純利益の次に独立して表示する。',6151),
('f4-052','2064','基礎','期末時点で納付すべき法人税等のうち中間納付額を差し引いた未納額は、未払法人税等として貸借対照表の固定負債に表示される。',false,
 '誤り。期末に納付すべき法人税等の額（中間申告・納付分を調整した額）は、未払法人税等として流動負債の区分に表示される。',6152),
('f4-053','2064','基礎','税抜方式では、販売時に顧客から受け取った消費税は売上高に含めず、商品売買に関する消費税は企業の費用としても計上しない。',true,
 '正しい。消費税の最終的な負担者は消費者であり、企業は国などのために回収するにすぎない。そのため売上高・売上原価とも消費税を除いた額で表示し、費用にも計上しない。',6153),
('f4-054','2064','基礎','企業が納付した固定資産税は、所得に対して課される税金と同じく、損益計算書の税引前当期純利益の次に表示される。',false,
 '誤り。固定資産税は企業が保有する財産に課される税金であり、租税公課として販売費及び一般管理費の区分に計上される。',6154),
('f4-055','2064','応用','税引前利益が8,000、交際費の損金不算入額が200、貸倒引当金の損金算入限度超過額が150、受取配当金の益金不算入額が300、特別償却額が250のとき、課税所得は7,800である。',true,
 '正しい。加算項目は交際費200と貸倒引当金超過額150、減算項目は受取配当金300と特別償却額250である。課税所得＝8,000＋200＋150－300－250＝7,800となる。',6155),
('f4-056','2064','応用','税引前利益が5,000、賞与引当金繰入額400が損金不算入、受取配当金の益金不算入額が100で、全部純資産直入法によるその他有価証券の評価差益が600あるとき、課税所得は5,900である。',false,
 '誤り。純資産の部に直接計上した評価差益は会計上の収益でも益金でもないため調整項目にならない。課税所得＝5,000＋400－100＝5,300となる。',6156),
('f4-057','2064','標準','全部純資産直入法でその他有価証券の評価差益を純資産の部に直接計上した場合、その評価差益は税務申告上の加算・減算の調整項目には該当しない。',true,
 '正しい。純資産に直接計上した評価差益は収益にも益金にも当たらないため、申告調整の対象とならない。部分純資産直入法による評価差損は損益に計上されるので損金不算入項目となる。',6157),
('f4-058','2064','標準','事業税のうち付加価値割と資本割は、所得割と同様に、税引前当期純利益の次に法人税等の一部として表示される。',false,
 '誤り。事業税の付加価値割と資本割は所得に対する税金ではないため、販売費及び一般管理費として表示する（合理的な配分により一部を売上原価に含めることも可）。',6158),
('f4-059','2065','基礎','税効果会計は、所得など利益に連動する額に課される税金を各期に適切に配分し、税引前当期純利益と税金費用とを見合わせるための手続きである。',true,
 '正しい。会計上の利益と課税所得は一致しないため、納付税額をそのまま計上すると税引前利益と税金費用の対応関係が崩れる。税効果会計はこのずれを調整する手続きである。',6159),
('f4-060','2065','基礎','現行の税効果会計基準は繰延法を採用しているため、税効果会計の対象となるのは期間差異である。',false,
 '誤り。現行基準は資産負債法を採用しており、対象は期間差異を含む一時差異である。繰延法は収益・費用と益金・損金の差である期間差異を対象とする方法である。',6160),
('f4-061','2065','標準','その他有価証券の時価評価で生じ、純資産の部へ直接計上する評価差額は、一時差異には該当するが、期間差異には該当しない。',true,
 '正しい。会計上と税務上で資産の評価額が異なるので一時差異になるが、収益・費用でも益金・損金でもないため期間差異ではない。一時差異は期間差異を含むより広い概念である。',6161),
('f4-062','2065','標準','繰延法でいう期間差異に該当する項目の中には、資産負債法でいう一時差異に含まれないものがある。',false,
 '誤り。期間差異に該当する項目はすべて一時差異に含まれる。例えば損金算入限度を超える減価償却費は、費用＞損金であると同時に、会計上の資産＜税務上の資産でもある。',6162),
('f4-063','2065','基礎','将来減算一時差異が発生した期は、繰延税金資産を計上し、法人税等調整額により損益計算書の税金費用を減らす。',true,
 '正しい。将来減算一時差異が生じた期は税金を前払いした状態なので、その前払相当額を繰延税金資産として計上し、法人税等調整額で税金費用を減額する。金額は差異×法定実効税率である。',6163),
('f4-064','2065','標準','損金算入限度を超える貸倒引当金を繰り入れた期は、他の事情が同じであれば、税引前当期純利益が課税所得を上回る状態となる。',false,
 '誤り。限度超過額は会計上は費用だが税務上は損金にならないため、課税所得の方が大きくなり、税引前当期純利益＜課税所得となる。このため税金を多く払った状態と考え繰延税金資産を計上する。',6164),
('f4-065','2065','応用','税引前利益が6,000の期に賞与引当金繰入額200が損金不算入となり、翌期に損金算入される。実効税率30%で税効果会計を適用すると、当期の納付税額は1,860、税金費用は1,800となる。',true,
 '正しい。課税所得は6,000＋200＝6,200、納付税額は6,200×30%＝1,860である。将来減算一時差異200×30%＝60を繰延税金資産とし法人税等調整額で60を減額するので、税金費用は1,800となる。',6165),
('f4-066','2065','応用','取得原価600の設備を会計上は3年の定額法で償却し、税務上は特別償却により初年度に全額を損金算入した。実効税率30%なら、初年度末の繰延税金負債は180である。',false,
 '誤り。初年度の会計上の償却費は200で、税務上は600を損金算入するので、初年度末の将来加算一時差異は400である。繰延税金負債は400×30%＝120となる。',6166),
('f4-067','2065','標準','特別償却を利用して、税務上の償却額が会計上の償却額より大きくなると将来加算一時差異が生じ、繰延税金負債が計上される。',true,
 '正しい。特別償却を使うと初期には税務上の資産額が会計上より小さくなり、将来の課税所得を増やす効果をもつ将来加算一時差異が生じる。税金の未払相当額を繰延税金負債として計上する。',6167),
('f4-068','2065','標準','税務上の繰越欠損金は、将来の課税所得を増やす効果をもつため、将来加算一時差異に準じて繰延税金負債を計上する。',false,
 '誤り。繰越欠損金は将来の課税所得と相殺され税額を減らす効果をもつので、将来減算一時差異に準じて扱い、軽減が見込まれる税額を繰延税金資産として計上する。',6168),
('f4-069','2065','応用','欠損金2,000を翌期に繰り越し、翌期の繰越控除前の課税所得が3,000、控除の上限がその50%、実効税率30%と仮定する。回収可能性に問題がなければ、翌期末の繰延税金資産は150である。',true,
 '正しい。控除できる欠損金は3,000×50%＝1,500なので、未控除の欠損金500が残る。繰延税金資産は当初600（2,000×30%）から450を取り崩し、残高は500×30%＝150となる。',6169),
('f4-070','2065','標準','繰越欠損金の制度には、業績が不安定な企業の税負担を、業績が安定した企業の税負担と釣り合わせる効果がある。',true,
 '正しい。欠損金を将来の課税所得と相殺できないと、赤字と黒字を繰り返す企業は利益合計が同じ安定企業より多く税を負担することになる。繰越控除はこれを平衡させる。',6170),
('f4-071','2065','基礎','当期末に計上した事業税のうち、翌期の納付時に損金算入される部分は永久差異にあたるため、税効果会計の対象とならない。',false,
 '誤り。事業税（特別法人事業税も同様）は翌期に納付した時点でその期の損金に算入されるので、将来減算一時差異にあたり税効果会計の対象となる。',6171),
('f4-072','2065','標準','全部純資産直入法でその他有価証券に評価損が生じた場合に税効果会計を適用すると、繰延税金資産を計上し、その分だけ借方のその他有価証券評価差額金を減らす。',true,
 '正しい。将来の売却時に見込まれる売却損による税負担の軽減額を繰延税金資産とし、相手勘定として評価差額金を調整する。損益計算書の法人税等調整額は使わない。',6172),
('f4-073','2065','標準','その他有価証券の評価益に税効果会計を適用すると、繰延税金負債の計上とともに法人税等調整額が計上され、当期純利益がその分だけ減少する。',false,
 '誤り。その他有価証券の評価益に係る繰延税金負債は、貸方のその他有価証券評価差額金を減らす形で計上され、法人税等調整額には影響しない。したがって当期純利益は変わらない。',6173),
('f4-074','2065','基礎','将来加算一時差異が解消する期には、繰延税金負債を取り崩すとともに、法人税等調整額を通じて税金費用を減らす。',true,
 '正しい。解消する期は課税所得が税引前利益より大きく、過去に未払いだった税金を支払うことになる。その税金費用は過去に計上済みなので、繰延税金負債を取り崩して税金費用を減額する。',6174),
('f4-075','2065','応用','法定実効税率は、事業税が納付した年度の損金に算入されることを考慮せず、法人税率・住民税率・事業税率などを単純に合計して求める。',false,
 '誤り。法定実効税率は課税所得1円当たりの税額合計を表し、事業税と特別法人事業税が納付年度の損金に算入され税金を減らす効果を考慮して計算する。日本では現在約30%である。',6175),
('f4-076','2066','標準','繰延税金資産の回収可能性は、企業本来の収益力から生じる課税所得の見込みのほか、保有資産の売却計画といったタックス・プランニングや将来加算一時差異の解消見込みも踏まえて判断する。',true,
 '正しい。回収可能性に関する適用指針では、これら3つの観点から、将来減算一時差異を相殺するのに十分な課税所得が生じるかを判断する。',6176),
('f4-077','2066','標準','繰延税金資産に回収可能性がないと判断して計上額を減らした場合、修正額が法人税等調整額の貸方に入り、当期純利益を押し上げる。',false,
 '誤り。回収可能性がない金額を繰延税金資産から控除するときは、修正額を法人税等調整額の借方に計上するので、税金費用が増えて当期純利益は押し下げられる。',6177),
('f4-078','2066','標準','過年度に繰延税金資産から控除した金額について、再び回収が見込まれると判断した場合には、その金額を繰延税金資産に計上し、当期純利益が増加する。',true,
 '正しい。回収が見込まれる金額を改めて繰延税金資産に計上すると、修正額が法人税等調整額の貸方に入り、当期純利益を押し上げる。',6178),
('f4-079','2066','基礎','繰延税金資産の算定で控除された回収不能見込額は、評価性引当額という名称で負債として貸借対照表に載る。',false,
 '誤り。回収可能性がない部分は繰延税金資産から控除され、その額は評価性引当額として注記で開示される。負債として計上されるわけではない。',6179),
('f4-080','2066','標準','税務上の繰越欠損金に係る繰延税金資産は、将来減算一時差異に係る繰延税金資産と比べて、一般に回収の不確実性が高いと考えられている。',true,
 '正しい。両者は回収の不確実性が異なり、繰越欠損金に係るものの方が一般に不確実性が高い。このため注記では評価性引当額を両者に分けて示す。',6180),
('f4-081','2066','標準','2018年の基準改正では、評価性引当額を税務上の繰越欠損金に係るものと将来減算一時差異に係るものとに分けず、合計額だけを注記すればよいこととされた。',false,
 '誤り。2018年の改正では、評価性引当額を繰越欠損金の分と将来減算一時差異の分に分けて示し、大きな変動があればその中身を文章で説明することが求められた。',6181),
('f4-082','2066','標準','税務上の繰越欠損金について重要な額の繰延税金資産を計上する企業は、回収できると判断した根拠を文章で注記することが求められる。',true,
 '正しい。2018年の改正で、繰越欠損金とそれに係る繰延税金資産の繰越期限別の金額に加え、重要な繰延税金資産を計上する場合は回収可能と判断した理由の記述が注記事項に加わった。',6182),
('f4-083','2066','基礎','繰延税金資産の回収可能性についての企業の判断は、貸借対照表の金額には影響するが、損益計算書の当期純利益には影響しない。',false,
 '誤り。回収可能性の判断を変えると、その修正額が法人税等調整額を通じて損益計算書に計上されるため、当期純利益にも影響する。',6183),
('f4-084','2114','基礎','2018年の基準改正後は、繰延税金資産は投資その他の資産の区分に、繰延税金負債は固定負債の区分に表示する。',true,
 '正しい。以前は関連する資産・負債の分類に応じて流動・固定に分けていたが、企業会計基準第28号により、すべて固定項目として表示することになった。',6184),
('f4-085','2114','標準','繰延税金資産と繰延税金負債は、納税主体が異なる場合であっても、貸借対照表上で相殺して純額で表示する。',false,
 '誤り。相殺表示するのは同一の納税主体の繰延税金資産と負債であり、異なる納税主体のものは相殺しない。このため連結では両方が表示されることも多い。',6185),
('f4-086','2114','基礎','損益計算書では、法人税等調整額は「法人税、住民税及び事業税」に含めて一つの金額で表示し、区分しない。',false,
 '誤り。当期に納付すべき額は「法人税、住民税及び事業税」などの科目で独立表示し、税効果会計による法人税等調整額とは区分して表示しなければならない。',6186),
('f4-087','2114','標準','税引前当期純利益に対する税負担率と法定実効税率との間に重要な差異がある場合、その差異の原因となった主な項目別の内訳を注記する。',true,
 '正しい。この注記により、利用者は差異のうち一過性の原因によるものを取り除いて、今後の税負担率を見通すことができる。',6187),
('f4-088','2114','応用','税金等調整前当期純利益が50,000、法人税・住民税及び事業税が18,000、法人税等調整額が△3,000の企業の税負担率は30%である。',true,
 '正しい。税負担率は法人税等調整額を含む税金費用を税引前利益で割って求める。（18,000－3,000）÷50,000＝30%となる。',6188),
('f4-089','2114','標準','資産負債法では、繰延税金資産・負債の金額を、一時差異が発生した年度の課税所得計算に適用された税率で計算する。',false,
 '誤り。資産負債法では、一時差異が解消し回収・支払いが行われると見込まれる年度の税率を用いる。差異が生じた年度の税率を用いるのは繰延法である。',6189),
('f4-090','2114','応用','将来減算一時差異が1,000あり繰延税金負債がない企業で、法定実効税率が30%から32%に引き上げられた場合、繰延税金資産は20減少し、当期純利益も20減少する。',false,
 '誤り。税率の引上げで将来の税負担軽減額が増えるため、繰延税金資産は1,000×（32%－30%）＝20増加する。修正額は法人税等調整額の貸方に計上され、当期純利益は20増加する。',6190),
('f4-091','2114','標準','決算日後に税率が変更された場合には、その内容と財務諸表への影響を注記することが求められる。',true,
 '正しい。税率の変更で繰延税金資産・負債を修正したときはその旨と修正額を、決算日後に税率が変わったときはその内容と影響を注記する。',6191),
('f4-092','2114','基礎','税効果会計の注記では、繰延税金資産と繰延税金負債について、どのような一時差異から生じたかを示す発生原因別の主な内訳を開示する。',true,
 '正しい。発生原因別の注記により、貸借対照表に計上された繰延税金資産・負債がどの一時差異から生じたものかが分かる。',6192),
('f4-093','2114','応用','繰延税金資産が繰延税金負債を上回る企業では、将来の税率引下げが決まると、繰延税金資産の再計算を通じて当期純利益が押し上げられる。',false,
 '誤り。税率が引き下げられると将来の税負担軽減額が減るため、繰延税金資産は一部取り崩される。その減少額が法人税等調整額を通じて計上され、当期純利益は押し下げられる。',6193),
('f4-094','2070','基礎','単一の資産を買う場合と同じく、企業や事業を現金で取得した場合も、支払った対価の額が取得原価となり、以後の費用測定の基礎となる。',true,
 '正しい。資産取得でも企業取得でも基本的な考え方は同じで、被取得企業は支払った対価の額で評価される。その取得原価が資産・負債とのれんに配分され、以後に費用化される。',6194),
('f4-095','2070','基礎','他社の全事業を現金で譲り受けたとき、支払額が受け入れた純資産の時価を上回る部分は、譲受日の費用として処理する。',false,
 '誤り。対価と純資産時価との差額はのれんとして無形固定資産に計上し、以後に規則的に償却する。譲受日に一括して費用処理するのではない。',6195),
('f4-096','2070','応用','A社は現金7,500で他社の全事業を譲り受けた。受け入れた資産の時価は11,000（簿価9,500）、負債の時価は5,000であった。A社が計上するのれんは1,500である。',true,
 '正しい。受け入れた純資産の時価は11,000－5,000＝6,000である。のれんは対価7,500－純資産時価6,000＝1,500となる。資産は簿価ではなく時価で計上する。',6196),
('f4-097','2070','応用','現金4,000で他社の発行済株式の100%を取得した。取得日の相手先の資産は時価9,000（簿価8,000）、負債は時価・簿価とも6,000である。連結上ののれんは2,000となる。',false,
 '誤り。のれんは純資産の時価との差額で求める。純資産時価は9,000－6,000＝3,000なので、のれんは4,000－3,000＝1,000である。2,000は簿価で計算した場合の誤った金額である。',6197),
('f4-098','2070','標準','他社株式の100%を現金で取得した企業の個別貸借対照表には子会社株式が計上されるが、連結貸借対照表ではこれが子会社の資産・負債とのれんに置き換えられる。',true,
 '正しい。株式の取得は、事業そのものを買ったとみることができる。親会社の持つ子会社株式を、子会社の資産と負債に置き換えるのが連結の核心である。',6198),
('f4-099','2070','基礎','企業を丸ごと取得するときの取得原価は、通常、その企業の資産・負債の時価の合計（純資産時価）を下回る。',false,
 '誤り。複数の資産の結合により無形の価値が生まれるため、企業を取得するには通常、純資産時価を上回る対価が必要となる。取得原価にはその無形の価値への支払額が含まれる。',6199),
('f4-100','2070','基礎','取得の対価が純資産時価を上回る部分であるのれんは、取得された企業の貸借対照表には載っていないブランドやノウハウなどの無形の価値への支払額と解される。',true,
 '正しい。のれんは相手企業独自のブランドや技術・ノウハウといった目に見えない価値に対する支払額であり、取得企業は無形固定資産として計上する。',6200),
('f4-101','2070','標準','他社の発行済株式の100%を現金で取得した場合、取得された企業は消滅し、その株主は取得企業の株式を割り当てられる。',false,
 '誤り。現金で100%取得した場合、被取得企業は完全子会社として存続し、その株主は現金を受け取って持分を清算する。株主が相手企業の持分を受け取るのは株式を対価とする合併である。',6201),
('f4-102','2071','基礎','自社株式との交換による合併をパーチェス法で処理する場合、取得日の時価で評価した交付株式の総額が、被合併会社の取得原価となる。',true,
 '正しい。対価が現金でも株式でも、被取得企業の評価額は支払対価の時価となる。株式を対価とする場合は、交付した株式の時価総額が取得原価となる。',6202),
('f4-103','2071','標準','株式を対価とする合併をパーチェス法で処理すると、合併会社の払込資本は、被合併会社から引き継いだ純資産の簿価と同じ額だけ増加する。',false,
 '誤り。パーチェス法では時価発行増資と同じように、払込資本（資本金または資本剰余金）が発行株式の時価総額だけ増加する。純資産簿価だけ増加させるのは持分プーリング法である。',6203),
('f4-104','2071','標準','持分プーリング法では、存続会社が消滅会社の資産・負債を帳簿価額で受け入れ、存続会社の株主資本は消滅会社の純資産簿価の分だけ増加する。',true,
 '正しい。持分の結合では双方の投資がそのまま継続していると見るため、資産・負債を簿価で引き継ぎ、株主資本も純資産簿価だけ増やす。のれんは生じない。',6204),
('f4-105','2071','標準','持分プーリング法を適用した場合、消滅会社の留保利益を存続会社が承継することは認められない。',false,
 '誤り。持分プーリング法では、存続会社が消滅会社の利益剰余金を引き継ぐこともできる。パーチェス法では株主資本は払込資本として増加する。',6205),
('f4-106','2071','標準','合併で引き継ぐ有形固定資産の時価が簿価を上回っている場合、合併後の減価償却費は、パーチェス法による方が持分プーリング法によるより大きくなる。',true,
 '正しい。パーチェス法では引き継いだ資産を時価で計上し、それを基礎に減価償却するので、簿価で引き継ぐ持分プーリング法より減価償却費が大きくなる。',6206),
('f4-107','2071','標準','パーチェス法を適用すると、持分プーリング法を適用した場合と比べて、一般に合併後の利益は大きくなる。',false,
 '誤り。パーチェス法では時価で引き継いだ資産の減価償却費が大きくなり、のれんの償却費も将来の利益を圧迫するので、一般に合併後の利益は小さくなる。',6207),
('f4-108','2071','応用','時価総額9,000の自社株式を交付して吸収合併した。被合併会社の資産は簿価15,000・時価16,500、負債は12,000（簿価＝時価）、合併会社の合併前の払込資本は6,000である。のれんは4,500、合併後の払込資本は15,000となる。',true,
 '正しい。純資産時価は16,500－12,000＝4,500なので、のれんは9,000－4,500＝4,500である。払込資本は発行株式の時価総額だけ増え、6,000＋9,000＝15,000となる。',6208),
('f4-109','2071','標準','合併会社が新株の代わりに自己株式を処分して合併の対価とした場合、被合併会社の取得原価は、その自己株式の帳簿価額で測る。',false,
 '誤り。自己株式を対価とする場合も、取得原価はその自己株式の取得日時点の時価で測る。',6209),
('f4-110','2071','標準','現行のパーチェス法のもとでも、株式を対価とする企業結合で取得企業と被取得企業がはっきり見分けられない場合には、取得企業の選び方に恣意性が入る余地がある。',true,
 '正しい。株式を対価とする結合では、どちらが取得企業か判然としないケースもあり、その場合は当事企業の中から取得企業を決めてパーチェス法を適用するため、恣意的な選択の余地が生じる。',6210),
('f4-111','2071','基礎','株式を対価とする企業結合では、現金を対価とする場合と異なり、被取得企業から引き継ぐ資産・負債は被取得企業の帳簿価額で評価する。',false,
 '誤り。パーチェス法では対価が株式でも現金でも、引き継ぐ資産・負債は取得日の時価で評価し、その後の減価償却などはこの時価をもとに行う。',6211),
('f4-112','2071','標準','企業結合で対価として交付する株式の時価は、原則として企業結合日の株価にもとづいて算定する。',true,
 '正しい。株式を対価とする企業結合では、発行する株式の時価は原則として企業結合日の株価を基礎とし、それが被取得企業の取得原価となる。',6212),
('f4-113','2071','標準','かつての日本基準において、パーチェス法と持分プーリング法は、企業が将来の利益の見え方を考えて自由に選べる代替的な方法であった。',false,
 '誤り。両者は企業結合の経済的実態に応じた方法であり、「取得」にはパーチェス法、「持分の結合」には持分プーリング法を適用した。利益を大きく見せるために選択することはできなかった。',6213),
('f4-114','2072','標準','日本基準のもとで、取得時に計上したのれん3,000を15年の定額法で償却する場合、2年経過後ののれんの帳簿価額は2,600となる。',true,
 '正しい。日本基準ではのれんを20年以内の効果の及ぶ期間にわたり規則的に償却する。1年当たりの償却額は3,000÷15＝200なので、2年後の簿価は3,000－400＝2,600である。',6214),
('f4-115','2072','標準','IFRSでは、のれんを規則的に償却したうえで、減損の兆候がある場合に限って減損テストを行う。',false,
 '誤り。IFRSではのれんを償却せず、減損の兆候の有無にかかわらず少なくとも年1回（毎年同じ時期に）減損テストを行う。兆候がある場合はそのたびに実施する。',6215),
('f4-116','2072','基礎','日本基準では、のれんの減損テストは毎年必ず行うのではなく、減損の兆候がある場合に実施される。',true,
 '正しい。日本基準ではのれんを規則的に償却し、必要に応じて減損処理を行う。減損テストは減損の兆候がある場合に行うので、兆候がなくても毎年行うIFRSとは異なる。',6216),
('f4-117','2072','応用','簿価300と400の2つの資産グループにはそれぞれ減損が生じていない。これらにのれん100を加えた単位の割引前将来キャッシュフローが760、回収可能価額が740のとき、のれんは全額が減損される。',false,
 '誤り。のれんを含む単位の簿価800が割引前将来キャッシュフロー760を上回るので減損を認識し、回収可能価額740まで減額する。減損損失60がのれんに配分され、のれんは40残る。',6217),
('f4-118','2072','標準','のれんの簿価を資産グループに合理的に配分できる場合には、配分した後に資産グループごとに減損を判定し、認識された減損損失はのれんに優先的に配分する。',true,
 '正しい。のれんを各資産グループに配分して判定する方法も認められており、その場合の減損損失はまずのれんに配分し、のれんを超える部分を各構成資産に配分する。',6218),
('f4-119','2072','標準','日本基準のもとで子会社の取得により生じたのれんの償却額は、連結損益計算書の営業外費用に計上される。',false,
 '誤り。連結上ののれん償却額は販売費及び一般管理費に含めて計上され、その分だけ連結貸借対照表ののれんが減少する。',6219),
('f4-120','2072','基礎','被取得企業の取得原価が純資産時価を下回って負ののれんが生じた場合、これを負債に計上して規則的に償却する。',false,
 '誤り。負ののれんが見込まれる場合は資産・負債の把握と取得原価の配分を見直し、それでもなお生じる場合は発生年度の利益として処理する。日本基準では原則として特別利益に表示する。',6220),
('f4-121','2072','標準','負ののれんの発生が見込まれるときは、取得企業は資産・負債の識別に漏れがないか、取得原価の配分に誤りがないかを確かめ直す必要がある。',true,
 '正しい。見直しをしてもなお負ののれんが生じる場合に、その期の利益に計上する。日本基準では原則として特別利益に表示する。',6221),
('f4-122','2072','標準','テキストによれば、のれんを償却しないIFRSでは、企業結合で取得したのれんと結合後に自ら形成したのれんを区別して減損テストしているため、後者が資産計上されることはない。',false,
 '誤り。両者を分離するのは極めて困難で、実際には分離しないまま減損テストが行われている。そのため規則的償却をしないIFRSでは、結合後に形成されたのれんが実質的に資産計上されることになる。',6222),
('f4-123','2072','標準','日本基準がのれんを建物や設備のように毎期規則的に償却することは、投資原価を上回って回収された部分を企業の利益と捉える考え方と整合している。',true,
 '正しい。のれんは取得企業の投資原価の一部であり、その価値は超過収益への期待がずっと続くのでなければ時の経過とともに減少する。規則的な償却はこの考え方と首尾一貫している。',6223),
('f4-124','2073','基礎','連結財務諸表は、親会社とその支配下の子会社からなる企業グループを一つの事業体とみなし、親会社がグループ全体の財政状態や経営成績を報告するために作る。',true,
 '正しい。連結財務諸表は、親会社が企業集団全体を単一の事業体として報告するものである。子会社を取得した親会社は、個別財務諸表に加えて連結財務諸表を作成する。',6224),
('f4-125','2073','標準','議決権の45%を所有し、自社の現在または過去の役員・従業員が取締役会メンバーの半数超を占めている会社は、子会社として連結される。',true,
 '正しい。支配力基準では、議決権の所有割合が40%以上50%以下で、役員等が取締役会の過半数を占めるなどの要件に該当すれば、意思決定機関を支配しているとして子会社となる。',6225),
('f4-126','2073','標準','議決権の所有割合が40%未満の会社は、緊密な関係にある者の議決権を合わせて過半数となり、取締役会の過半数を自社の役員が占めていても、子会社にはならない。',false,
 '誤り。40%未満でも、緊密な者などの議決権を合わせて過半数を占め、かつ取締役会の過半数を占めるなどの要件に該当すれば、子会社として連結される。',6226),
('f4-127','2073','標準','議決権の42%を所有し、その会社の負債に計上された資金調達額の総額の過半を自社が融資している場合、その会社は子会社に該当する。',true,
 '正しい。議決権の40%以上50%以下を所有し、資金調達額の過半を融資（債務保証や担保提供を含む）していることは、意思決定機関の支配を推測させる要件の一つである。',6227),
('f4-128','2073','応用','議決権の30%を所有し、自社の役員が取締役会の過半数を占めているが、緊密な関係にある者の議決権を加えても過半数に達しない会社は、子会社として連結される。',false,
 '誤り。40%未満の場合は、緊密な者等の議決権を合わせて過半数を占めることが前提となり、そのうえで取締役会の支配などの要件に該当する必要がある。前提を満たさないので子会社にはならない。',6228),
('f4-129','2073','標準','子会社に対する支配が一時的なものにすぎないと判断される場合でも、その子会社は連結の範囲に含めなければならない。',false,
 '誤り。支配が一時的と認められる子会社や、連結すると利害関係者の判断を大きく誤らせかねない子会社は、連結の範囲から除かれる。',6229),
('f4-130','2073','基礎','更生会社や破産会社などで有効な支配従属関係がなく組織の一体性を欠く企業であっても、議決権の過半数を持っている限り子会社として扱われる。',false,
 '誤り。更生会社・整理会社・破産会社などのうち、実質的な支配従属関係がなく一体の組織とはいえない企業は、子会社とはみなされない。',6230),
('f4-131','2073','標準','適正な対価で取得した資産からの収益を、自らが発行した証券の保有者に配る目的で設立され、その目的どおり事業が営まれている特別目的会社は、資産の譲渡元企業の子会社には当たらないと推定される。',true,
 '正しい。こうした特別目的会社は、資産の譲渡元から独立していると認められるため、譲渡元の子会社ではないと推定される。',6231),
('f4-132','2074','基礎','連結財務諸表は、まず親会社と子会社の個別財務諸表を単純に足し合わせ、そのうえで投資と資本の相殺消去などを行う。',true,
 '正しい。単純合算したままでは子会社の純資産が二重に計上されるので、親会社の投資勘定と子会社の資本勘定を相殺し、投資を子会社の資産・負債に置き換える。',6232),
('f4-133','2074','標準','投資と資本の相殺消去に先立って子会社の資産・負債を時価に評価替えすると、子会社の個別貸借対照表もその時価に書き替えられる。',false,
 '誤り。この評価替えは連結財務諸表を作成するためだけに行うものであり、子会社の個別貸借対照表が書き替えられるわけではない。',6233),
('f4-134','2074','標準','現行の連結会計基準では、子会社の資産・負債の評価替えについて部分時価評価法が廃止され、全体を時価に評価替えする全面時価評価法が採用されている。',true,
 '正しい。全面時価評価法では、親会社の持分比率にかかわらず子会社の資産・負債の全体を支配獲得日の時価に評価替えする。',6234),
('f4-135','2074','応用','現金3,000で他社株式の70%を取得し子会社とした。取得日の子会社の資産は時価8,000（簿価7,000）、負債は時価4,000である。全面時価評価法によると、のれんは200、非支配株主持分は1,200となる。',true,
 '正しい。時価による純資産は8,000－4,000＝4,000である。のれんは3,000－4,000×70%＝200、非支配株主持分は4,000×30%＝1,200となる。',6235),
('f4-136','2074','標準','子会社の評価替えに部分時価評価法を用いた場合、全面時価評価法を用いた場合と比べて、計上されるのれんの金額は小さくなる。',false,
 '誤り。のれんは親会社の持分の取得対価から純資産時価の親会社持分を差し引いた残りなので、どちらの方法でも同額になる。差が出るのは非支配株主持分の金額である。',6236),
('f4-137','2074','標準','支配獲得日に行った子会社資産の評価替えや投資と資本の相殺消去は、翌期以降の連結財務諸表の作成では繰り返す必要がない。',false,
 '誤り。各期の連結は個別財務諸表を足し合わせる作業からスタートし、個別財務諸表には過去の連結修正が反映されていない。そのため毎期、評価替えや相殺消去を繰り返す必要がある。',6237),
('f4-138','2074','応用','期首の非支配株主持分が1,000の子会社（非支配株主の持分比率30%）が、当期純利益400を計上し配当金100を支払った。期末の非支配株主持分は1,120となる。',false,
 '誤り。非支配株主持分は純利益の30%（120）だけ増える一方、非支配株主への配当（100×30%＝30）だけ減る。期末残高は1,000＋120－30＝1,090となる。',6238),
('f4-139','2074','基礎','子会社が親会社に支払った配当金は企業集団内部の取引にすぎないため、親会社の受取配当金と子会社の配当金を相殺消去する。',true,
 '正しい。親会社の損益計算書から子会社からの受取配当金を消去し、子会社の株主資本等変動計算書から親会社への配当金を消去する。',6239),
('f4-140','2074','応用','親会社の個別の当期純利益が3,000（子会社からの受取配当金160を含む）、80%子会社の当期純利益が1,000、のれん償却額が50のとき、親会社株主に帰属する当期純利益は3,590となる。',true,
 '正しい。合算した4,000から、のれん償却額50、内部取引である受取配当金160、非支配株主に帰属する当期純利益1,000×20%＝200を差し引くと、3,590となる。',6240),
('f4-141','2074','基礎','連結貸借対照表上、子会社の純資産のうち非支配株主に帰属する部分は、親会社の株主資本に含めて表示する。',false,
 '誤り。非支配株主持分は子会社の純資産のうち親会社以外の株主に帰属する部分であり、純資産の部の中で親会社の株主資本とは区別して表示する。',6241),
('f4-142','2074','標準','投資と資本の相殺消去で消去されるのは子会社の資本金と資本剰余金だけであり、支配獲得時に子会社が計上していた利益剰余金は消去の対象にならない。',false,
 '誤り。支配を獲得した時点で子会社が計上していた利益剰余金（取得時剰余金）も、資本勘定として相殺消去の対象となる。',6242),
('f4-143','2074','標準','親会社が全額出資して自ら設立し、持分比率100%を維持している子会社についても、連結上はのれんが計上される。',false,
 '誤り。このような子会社では、子会社株式の取得原価が相殺消去される子会社の純資産額と原理的に一致するため、のれんは生じない。',6243),
('f4-144','2074','基礎','連結上、子会社への投資成果は、子会社株式の値動きではなく、子会社があげた実現利益で測られる。',true,
 '正しい。連結では子会社株式を子会社の資産と負債に置き換えるため、投資の成果は子会社が実現した利益で測る。',6244),
('f4-145','2075','基礎','親会社から子会社への売上高と子会社の仕入高（売上原価）は連結上相殺消去され、企業集団の外部への売上高だけが連結売上高となる。',true,
 '正しい。単純合算したままでは集団内部の取引が二重に計上されるため、内部取引による売上高と売上原価を相殺消去する。',6245),
('f4-146','2075','基礎','親会社が子会社に対してもつ売掛金と、子会社が親会社に対して負う買掛金は、連結貸借対照表でもそれぞれ総額で表示する。',false,
 '誤り。内部取引から生じた債権と債務も、売上高と仕入高と同じく連結上相殺消去される。',6246),
('f4-147','2075','応用','親会社が原価800の製品を1,000で子会社に販売し、子会社は期末にその全量を在庫として保有している。連結貸借対照表に計上されるこの在庫の金額は800である。',true,
 '正しい。親会社が上乗せした利益200は外部に販売されていない未実現利益なので消去し、在庫を1,000から800に減額する。連結上は売上高・売上原価ともゼロで、在庫が原価で繰り越される。',6247),
('f4-148','2075','応用','親会社は原価に25%の利益を加えて子会社に商品を販売している。子会社の期末在庫のうち親会社から仕入れた分が2,500のとき、消去すべき未実現利益は625である。',false,
 '誤り。在庫2,500は原価に25%を加えた売価なので、含まれる利益は2,500×0.25÷1.25＝500である。2,500×25%＝625は売価に利益率を掛けた誤った計算である。',6248),
('f4-149','2075','標準','子会社から親会社への販売で生じた未実現利益は全額を消去し、そのうえで非支配株主の持分比率に見合う部分を非支配株主に帰属する当期純利益から控除する。',true,
 '正しい。消去した未実現利益を親会社と非支配株主に持分比率に応じて負担させる。その結果、非支配株主持分もその分だけ減少する。',6249),
('f4-150','2075','標準','子会社から親会社へ商品を販売して生じた未実現利益については、親会社の持分比率に対応する部分だけを消去する。',false,
 '誤り。子会社から親会社への販売でも未実現利益は全額消去する。そのうえで非支配株主の持分比率に見合う額を非支配株主に帰属する当期純利益から控除する。',6250),
('f4-151','2075','標準','親会社が利益を付加して子会社に販売した製品を、子会社が期末までにすべて外部に販売していれば、親会社が付加した利益は連結上も実現した利益となる。',true,
 '正しい。内部売上高と売上原価を相殺すると、外部への売上高と親会社の当初の原価が残り、その差額に親会社が付加した利益も含まれる。未実現利益の消去が必要なのは在庫が集団内に残る場合である。',6251),
('f4-152','2075','応用','非支配株主の持分比率が30%の子会社が親会社に商品を販売し、期末の親会社在庫に未実現利益400が含まれている。このとき非支配株主に帰属する当期純利益から280を控除する。',false,
 '誤り。未実現利益400を全額消去し、非支配株主の持分比率30%に見合う400×30%＝120を、非支配株主に帰属する当期純利益から控除する。280は親会社の負担分である。',6252),
('f4-153','2080','基礎','外貨建取引は、原則として、取引が発生した時点の為替相場で換算した円の金額で記録する。',true,
 '正しい。外貨建取引の発生日には、その時点の為替相場（HR）による円換算額で記録する。この点は一取引基準でも二取引基準でも同じである。',6253),
('f4-154','2080','基礎','一取引基準とは、外貨建取引とその代金の決済取引を別個の取引とみて、取引発生日から決済日までの為替変動による差額を為替差損益として処理する方法である。',false,
 '誤り。これは二取引基準の説明である。一取引基準は取引と決済を一連の取引とみて、為替変動による差額を当初の取引額（仕入や売上）の修正として処理する。',6254),
('f4-155','2080','基礎','一取引基準では、外貨建で掛け仕入れをした場合、仕入の円換算額は代金の支払いが済むまで確定しない。',true,
 '正しい。一取引基準では仕入と支払いを一つの取引とみるので、取引発生日の換算額は決済日までの為替変動に応じて修正される。二取引基準では取引発生日に確定する。',6255),
('f4-156','2080','応用','商品2百万ドルを1ドル130円のときに掛けで仕入れ、1ドル125円のときに代金を支払った。間に決算日はない。二取引基準では、決済日に為替差益10百万円が計上される。',true,
 '正しい。買掛金は260百万円で計上され、支払額は2百万ドル×125円＝250百万円である。二取引基準では差額10百万円を為替差益として処理し、仕入は260百万円のまま確定している。',6256),
('f4-157','2080','応用','商品2百万ドルを1ドル130円で掛け仕入れし、1ドル125円で代金を支払った（間に決算日はない）。一取引基準では仕入は260百万円のまま、決済日に為替差益10百万円を計上する。',false,
 '誤り。一取引基準では決済差額を仕入の修正として処理するため、仕入は10百万円減額され250百万円となり、為替差益は計上しない。為替差益として処理するのは二取引基準である。',6257),
('f4-158','2080','基礎','二取引基準によって外貨建取引の決済時に生じた為替差損益は、損益計算書上、売上原価の修正として表示される。',false,
 '誤り。二取引基準では決済取引を財務取引とみるので、為替差損益は営業外損益として表示する。売上原価の修正となるのは一取引基準の場合である。',6258),
('f4-159','2080','標準','外貨建の仕入取引に一取引基準を適用した場合と二取引基準を適用した場合とでは、商品を販売した後の最終的な損益が為替変動分だけ異なる。',false,
 '誤り。為替変動の影響は、一取引基準では売上原価の修正、二取引基準では為替差損益として表れるだけで、商品販売後の最終的な損益は同じになる。',6259),
('f4-160','2080','標準','取引発生時の為替相場には取引日の直物為替相場しか用いることができず、前月の直物為替相場の平均などを用いることは認められていない。',false,
 '誤り。取引日の直物為替相場のほか、前月や前週の直物為替相場の平均など合理的な基礎で算定した平均相場や、前月末日など直近の一定の日の直物為替相場を用いることも認められている。',6260),
('f4-161','2080','応用','1百万ドルの買掛金を1ドル120円で計上し、決算日が116円、決済日が113円だった。決算時に決算日の相場で換算し直し二取引基準を適用すると、決算日に為替差益4百万円、決済日に3百万円が計上される。',true,
 '正しい。決算日には120百万円を116百万円に換算し直して4百万円の差益、決済日には116百万円と支払額113百万円の差の3百万円の差益を計上する。通算の7百万円は換算し直さない方法と同じである。',6261),
('f4-162','2080','標準','現行の外貨建取引等会計処理基準では、決済前の決算日に決算時の為替相場で換算し直す方法と、二取引基準を組み合わせた処理が原則となっている。',true,
 '正しい。外貨建金銭債権債務は決算時の為替相場で換算し換算差額を当期の為替差損益とし、決済による損益も為替差損益とする。つまり第2の方法と二取引基準の組み合わせが原則である。',6262),
('f4-163','2080','応用','外貨建の仕入で為替相場が円高に動き、一取引基準により仕入の円換算額が減額された場合、商品を販売したときの売上総利益は二取引基準より小さくなる。',false,
 '誤り。一取引基準では円高による差額が仕入（売上原価）を減らすので、売上総利益は二取引基準より大きくなる。二取引基準ではその分が営業外の為替差益として計上される。',6263),
('f4-164','2080','基礎','外貨建取引には、取引価額が外貨で表示された物品の売買だけでなく、決済金額が外貨で表示された資金の借入や貸付も含まれる。',true,
 '正しい。外貨建取引とは売買価額や取引価額が外貨建てとなっている取引をいい、外貨表示の物品売買や資金の借入・貸付がその代表例である。',6264),
('f4-165','2081','基礎','流動・非流動法は、外貨建項目のうち流動項目を決算時の為替相場で、非流動項目を取引発生時の為替相場で換算する方法である。',true,
 '正しい。流動項目は決算日後短期間で決済されるので決算時の相場による換算が回収額・支払額の予想に役立つ、という考え方に立つ方法である。',6265),
('f4-166','2081','標準','流動・非流動法では、流動資産である棚卸資産も、取得原価を重視して取引発生時の為替相場で換算する。',false,
 '誤り。流動・非流動法では棚卸資産は流動項目なので決算時の為替相場で換算する。棚卸資産を取引発生時の相場で換算するのは貨幣・非貨幣法である。',6266),
('f4-167','2081','標準','貨幣・非貨幣法では棚卸資産などの非貨幣項目を取引発生時の為替相場で換算するので、取得原価主義会計と相性のよい方法と解される。',true,
 '正しい。非貨幣項目は過去に支出した貨幣額（取得原価）で表示されるため、取引発生時の相場で換算すれば本国通貨による取得原価を示せる。',6267),
('f4-168','2081','標準','テンポラル法では、収益性の低下により簿価を切り下げた棚卸資産も、取得原価で測定される他の非貨幣項目と同じく取引発生時の為替相場で換算する。',false,
 '誤り。テンポラル法は時価で測定されている項目を決算時の為替相場で換算するので、簿価を切り下げた棚卸資産は決算時の相場で換算する。取引発生時の相場で換算するのは貨幣・非貨幣法である。',6268),
('f4-169','2081','標準','テンポラル法は換算後も各項目の測定属性が保たれるため理論的とされる一方、為替変動が激しいと、外貨表示では純利益なのに換算後は純損失となる「換算のパラドックス」が生じうる。',true,
 '正しい。減価償却費などを取得時の相場で換算するため、こうした逆転が起こりうる。かつての日本基準では在外子会社について、純利益を決算時の相場で換算する修正テンポラル法を用いていた。',6269),
('f4-170','2081','標準','決算日レート法は、資本金や剰余金などの資本項目も含め、貸借対照表のすべての項目を決算時の為替相場で換算する方法である。',false,
 '誤り。決算日レート法では資産・負債項目を決算時の相場で換算するが、資本項目は取引発生時の相場で換算する。そのため換算後の純資産と資本の間にずれが生じる。',6270),
('f4-171','2081','応用','決算日レート法のもとでは、減価償却費は、テンポラル法と同じく有形固定資産を取得した時点の為替相場で換算する。',false,
 '誤り。決算日レート法では収益・費用はそれが認識された時点の相場で換算するのが原則で、減価償却費も同様である（実務上は期中平均相場も可）。取得時の相場で換算するのはテンポラル法である。',6271),
('f4-172','2081','標準','外貨建の長期貸付金は非流動項目であるが、保有することで為替変動のリスクにさらされる点を重視して、決算時の為替相場で換算する。',true,
 '正しい。外貨建取引等会計処理基準では、外貨建金銭債権債務は流動・非流動を問わず決算時の為替相場で換算する。',6272),
('f4-173','2081','応用','1ドル110円のときに外貨建の長期借入金3百万ドルを借り入れ、決算日の為替相場が1ドル115円となった場合、決算日に為替差損15百万円を計上する。',true,
 '正しい。借入金は330百万円で計上され、決算日に3百万ドル×115円＝345百万円に換算し直す。負債が15百万円増えるので、その分を当期の為替差損として処理する。',6273),
('f4-174','2081','応用','1ドル108円のときに計上した外貨建の買掛金2百万ドルについて、決算日の為替相場が1ドル104円となった場合、決算日に為替差損8百万円を計上する。',false,
 '誤り。買掛金は216百万円から2百万ドル×104円＝208百万円に換算し直され、負債が8百万円減少する。したがって計上するのは為替差益8百万円である。',6274),
('f4-175','2081','基礎','外貨建金銭債権債務を決算時の為替相場で換算して生じた差額は、原則として純資産の部に直接計上する。',false,
 '誤り。外貨建金銭債権債務の換算差額は、原則として当期の為替差損益として損益計算書に計上する。決済時に生じた損益も同様である。',6275),
('f4-176','2081','標準','貨幣・非貨幣法で通貨や金銭債権債務を決算時の為替相場で換算するのは、これらが将来受け取る・支払う貨幣の額で示されるため、本国通貨での回収額・支払額を示せるからである。',true,
 '正しい。貨幣項目を決算時の相場で換算すると本国通貨による回収額・支払額を表示でき、非貨幣項目を取引発生時の相場で換算すると本国通貨による取得原価を表示できる。',6276),
('f4-177','2082','基礎','外貨建の売買目的有価証券は、外貨による時価を決算時の為替相場で換算した金額で貸借対照表に計上する。',true,
 '正しい。売買目的有価証券やその他有価証券は時価で評価するので、円建ての時価を得るため、外貨による時価に決算時の為替相場を掛けて換算する。',6277),
('f4-178','2082','基礎','外貨建の満期保有目的の債券は、非貨幣項目として扱われ、取得時の為替相場で換算する。',false,
 '誤り。満期保有目的の債券は金銭債権との類似性を重視し、外貨による取得原価または償却原価を決算時の為替相場で換算する。',6278),
('f4-179','2082','標準','外貨建の満期保有目的債券に償却原価法を適用する場合、外貨による当期の償却額は期中平均相場で換算する。',true,
 '正しい。償却原価法による利息調整額（外貨による償却額）は期中平均相場で換算する。決算時の相場で換算するのは償却原価そのものである。',6279),
('f4-180','2082','応用','1ドル120円のときに外貨建のその他有価証券（株式）を50千ドルで取得した。決算日の時価が55千ドル、為替相場が1ドル110円なら、貸借対照表価額は6,050千円で、差額50千円は純資産の部に計上される。',true,
 '正しい。取得原価は50×120＝6,000千円、期末は55×110＝6,050千円である。その他有価証券（株式）の評価差額と換算差額は、ともにその他の包括利益を通じて純資産の部に計上する。',6280),
('f4-181','2082','応用','1ドル125円のときに20千ドルで取得した外貨建の関連会社株式について、決算日の時価が22千ドル、為替相場が1ドル105円であれば、決算日の円換算額は2,310千円である。',false,
 '誤り。関連会社株式は実質的に事業資産であり非貨幣項目とみなされるので、外貨による取得原価を取得時の為替相場で換算する。円換算額は20×125＝2,500千円のままである。',6281),
('f4-182','2082','標準','外貨建の満期保有目的の債券を決算時の為替相場で換算して生じた差額は、その他の包括利益を通じて純資産の部に計上する。',false,
 '誤り。満期保有目的の債券の換算差額は、金銭債権債務と同様に為替差損益として当期の損益に計上する。',6282),
('f4-183','2082','標準','その他有価証券に属する外貨建の債券については、外貨による取得原価を決算時の為替相場で換算して生じた差額を当期の為替差損益に計上する方法も認められる。',true,
 '正しい。時価の変動による部分と為替変動による部分を分け、金銭債権債務との整合性を考えて為替変動による部分を損益とする処理が認められている。',6283),
('f4-184','2082','基礎','外貨建の売買目的有価証券を決算時の為替相場で換算した際に生じた差額は、純資産の部に直接計上する。',false,
 '誤り。売買目的有価証券については、時価の変動による評価差額も為替変動による換算差額も当期の損益として処理する。',6284),
('f4-185','2083','基礎','在外支店の財務諸表項目を円に換算する際に生じた差額は、純資産の部の為替換算調整勘定に計上する。',false,
 '誤り。在外支店の換算差額は、本店の外貨建取引と同様にすべて為替差損益として処理する。為替換算調整勘定が生じるのは在外子会社の財務諸表の換算である。',6285),
('f4-186','2083','標準','在外支店の棚卸資産や有形固定資産などの非貨幣項目で取得原価により記録されているものは、取得時の為替相場で換算する。',true,
 '正しい。在外支店の非貨幣項目は、取得原価で記録されていれば取得時の相場、それ以外の価額で記録されていればその価額を付した時の相場で換算する。',6286),
('f4-187','2083','標準','在外支店の貸借対照表に計上されている本店勘定は、本支店の財務諸表を合わせる際に決算時の為替相場で換算する。',false,
 '誤り。本店勘定は本支店合併財務諸表の作成時に本店の支店勘定と相殺されるため、本店側の支店勘定と同じ金額で記録する。',6287),
('f4-188','2083','標準','在外支店の収益・費用は原則として本店と同じく取引発生時の為替相場で換算するが、期中平均相場による換算も認められている。',true,
 '正しい。在外支店の収益・費用は原則として取引発生時の相場によるが、期中平均相場による換算も認められる。ただし費用性資産の費用化額などは別の扱いとなる。',6288),
('f4-189','2083','標準','在外支店の収益・費用を期中平均相場で換算することにした場合、有形固定資産の減価償却費も期中平均相場で換算する。',false,
 '誤り。期中平均相場で換算する場合でも、棚卸資産や有形固定資産の費用化額である売上原価や減価償却費は、資産を取得した時の為替相場で換算する。',6289),
('f4-190','2083','標準','低価法を適用して時価300千ドルに評価を切り下げた在外支店の棚卸資産は、決算日の為替相場が1ドル104円であれば、31,200千円に換算される。',true,
 '正しい。在外支店が棚卸資産に低価法を適用している場合は、外貨による時価を決算時の為替相場で換算する。300千ドル×104円＝31,200千円となる。',6290),
('f4-191','2083','基礎','本国主義とは、在外支店や在外子会社の事業が本国の事業と不可分であったりその延長であったりする場合に、その取引を本店や親会社自身の外貨建取引とみて換算する考え方である。',true,
 '正しい。本国主義に対し、在外事業が現地の経済環境で自立している場合に現地通貨での事業成果に合うように換算する考え方を現地主義という。',6291),
('f4-192','2083','応用','在外支店の収益を期中平均相場で換算している場合、前受金を当期に収益化した額も期中平均相場で換算する。',false,
 '誤り。前受金や前受収益の収益化額は、その負債が発生した時の為替相場で換算する。期中平均相場が使えるのは通常の収益・費用である。',6292),
('f4-193','2084','基礎','在外子会社の財務諸表を連結のために円換算する場合、資産と負債は決算時の為替相場で換算する。',true,
 '正しい。外貨建取引等会計処理基準は在外子会社の換算に決算日レート法の考え方を採用しており、資産・負債は決算時の為替相場で換算する。',6293),
('f4-194','2084','標準','在外子会社の財務諸表を換算する際、親会社が株式を取得した時点の資本金は、資産・負債と同じく決算時の為替相場で換算する。',false,
 '誤り。親会社による株式取得時の株主資本項目は、株式取得時の為替相場で換算する。資本金は取得時の相場で換算されたままとなる。',6294),
('f4-195','2084','基礎','在外子会社の収益・費用は原則として期中平均相場で換算するが、決算時の為替相場を用いる換算も認められている。',true,
 '正しい。在外子会社の収益・費用は原則として期中平均相場で換算し、決算時の相場による換算も認められる。親会社との取引によるものは別の扱いとなる。',6295),
('f4-196','2084','標準','在外子会社の親会社との取引による収益・費用は期中平均相場で換算し、それによって生じる差額は為替換算調整勘定として処理する。',false,
 '誤り。親会社との取引による収益・費用は、親会社が換算に用いる為替相場で換算し、そこで生じる差額は当期の為替差損益として処理する。',6296),
('f4-197','2084','応用','在外子会社の資産が20,000千ドル、負債が12,000千ドル、資本金6,000千ドル（取得時1ドル100円）、利益剰余金2,000千ドル（円貨額210,000千円）で、決算日の相場が1ドル112円なら、為替換算調整勘定は86,000千円である。',true,
 '正しい。純資産は（20,000－12,000）×112円＝896,000千円である。資本は資本金600,000千円と利益剰余金210,000千円の合計810,000千円なので、差額86,000千円が為替換算調整勘定となる。',6297),
('f4-198','2084','標準','在外子会社で、親会社による株式取得の後に増加した利益剰余金は、親会社が株式を取得した時の為替相場で換算する。',false,
 '誤り。株式取得後に生じた株主資本項目は、その発生時の為替相場で換算する。株式取得時の相場で換算するのは取得時に存在した株主資本項目である。',6298),
('f4-199','2084','応用','在外子会社の期首利益剰余金の円貨額が50,000千円、当期純利益300千ドルを期中平均相場106円、配当金100千ドルを配当決議日の相場104円で換算すると、期末利益剰余金は71,400千円となる。',true,
 '正しい。当期純利益は300×106＝31,800千円、配当金は100×104＝10,400千円である。期末残高は50,000＋31,800－10,400＝71,400千円となる。',6299),
('f4-200','2084','基礎','現行の外貨建取引等会計処理基準は、在外子会社の財務諸表項目の換算方法としてテンポラル法の考え方を採用している。',false,
 '誤り。在外子会社については、現地通貨による事業成果と整合させる現地主義の考え方から、決算日レート法の考え方がとられている。テンポラル法の考え方は在外支店の非貨幣項目に用いられる。',6300),
('f5-021','2087','基礎','財務諸表分析で比率分析が中心となるのは、企業の規模の大きさよりも、財務内容の質的な特徴を比べることを重んじるからである。',true,
 '正しい。複数の財務諸表項目を関連付けた比率を用いることで、規模の違いに左右されずに財務の質的な側面を評価できる。',7121),
('f5-022','2087','基礎','債務超過で自己資本がマイナスとなっている企業についても、ROEや負債比率はマイナスの値として算出し、他社と比較することができる。',false,
 '誤り。分母の自己資本がマイナスの企業では、ROEや負債比率は計算できない（マイナス分母の問題）。比率分析では分母の符号に注意が必要である。',7122),
('f5-023','2087','標準','分母がプラスでもゼロに近いと比率の絶対値が極端に大きくなるため、指標を統計的に分析する場合には、平均値に代えて中央値を用いるなどの対処が求められる。',true,
 '正しい。これを分母の過小問題という。外れ値への対処として、中央値の使用や外れ値の除外・置換などが挙げられている。',7123),
('f5-024','2087','基礎','当期の財務比率を同一年度のライバル企業や業界平均と照らし合わせる手法は、タイムシリーズ分析と呼ばれる。',false,
 '誤り。同じ年度の同業他社や業界平均との比較は企業間比較（クロスセクション分析）である。タイムシリーズ分析は、その企業の過去期間との比較（期間比較）をいう。',7124),
('f5-025','2087','標準','流動比率の目安とされる1.0という水準は、売上債権や棚卸資産が少ない業界では大きく下回るのが実態であり、目安が有名無実化している指標の例とされる。',true,
 '正しい。インタレスト・カバレッジ・レシオの1.0のように理論値が今も機能する指標がある一方、流動比率など多くの指標では目安が有名無実化している。',7125),
('f5-026','2087','基礎','財務諸表分析の5つの視点のうち、本テキストは収益性・生産性・安全性・成長性の4つを対象とし、不確実性の分析はほかの学習分野に譲っている。',false,
 '誤り。ほかの学習分野に譲られているのは成長性の分析である。本テキストが対象とするのは収益性・生産性・安全性・不確実性の4つである。',7126),
('f5-027','2087','標準','決算期の変更で10ヵ月決算となった場合、損益計算書と貸借対照表のデータを組み合わせた指標は影響を受けやすいため、10ヵ月分の損益データを12/10倍して年換算するなどの調整が必要となる。',true,
 '正しい。同じ財務諸表どうしの比率は決算期変更の影響が比較的軽微だが、損益計算書と貸借対照表を関連付けた指標では、期間をそろえる修正（可能なら季節性も考慮）が欠かせない。',7127),
('f5-028','2087','標準','利益を捻出する会計手続が選択されると、その後に利益の反転が生じても、企業の存続期間全体を通じた利益の総額は増える。',false,
 '誤り。利益捻出型の会計手続を選んでも、後に利益が反転するため、企業が存続する全期間で合計した利益額に差は生じない。捻出による利益は将来の減益を伴うため、利益の質が相対的に低い。',7128),
('f5-029','2087','標準','見込みを上回る利益が出そうなときに費用を多めに計上し、課税所得を減らそうとすることは、利益圧縮の動機の一例である。',true,
 '正しい。節税は利益圧縮の代表的な動機である。ほかに、労働組合の賃上げ要求や得意先の値下げ要求をかわすなど、利害関係者との交渉で優位に立つ狙いもある。',7129),
('f5-030','2087','基礎','研究開発費は現行制度上、支出した時点で一括して費用処理されるため、研究開発がどの程度成功したかは現在の財務諸表には反映されない。',true,
 '正しい。成功の度合いは将来の財務諸表に反映されるが、残余利益モデルを踏まえると、少なくとも一部は現在の株価に織り込まれている可能性がある。',7130),
('f5-031','2087','標準','期首の自己資本簿価が500億円、親会社株主に帰属する当期純利益が60億円、自己資本コストが8%の企業の残余利益は20億円である。',true,
 '正しい。残余利益＝当期純利益－自己資本コスト×期首自己資本簿価＝60億円－0.08×500億円＝20億円である。',7131),
('f5-032','2087','応用','残余利益が一定率gで成長すると仮定した残余利益モデルでは、成長率gが高いほど割引の分母が大きくなるため、株式価値は低く評価される。',false,
 '誤り。このモデルの分母は（自己資本コスト－成長率g）であり、gが高いほど分母は小さくなる。したがって成長率が高いほど株式価値は高くなる。',7132),
('f5-033','2088','基礎','資本利益率は利益を資本で割って求める尺度であり、分母に用いる資本と分子に用いる利益は、理論的に首尾一貫していなければならない。',true,
 '正しい。その代表が、企業全体の視点からの総資本事業利益率（ROA）と、株主の視点からの自己資本純利益率（ROE）である。',7133),
('f5-034','2088','基礎','本テキストの分析上、持分法による投資利益は、余剰資金運用活動から生じる金融収益の一部として扱われる。',false,
 '誤り。関連会社への投資もグループ経営の一部と考え、持分法による投資利益は営業利益に準ずるものとして扱う。金融収益の代表は受取利息・配当金である。',7134),
('f5-035','2088','標準','ROAの分母となる総資本に期首と期末の平均値を用いるのは、分子の利益が1年間のフローの数値であることに対応させるためである。',true,
 '正しい。期中に平均して投じられた資本を分母とすることで、フローである利益との対応を図っている。ROEの自己資本も同様に期中平均を用いる。',7135),
('f5-036','2088','基礎','ROEの分子には、非支配株主に帰属する部分を含めた企業集団全体の当期純利益を用いる。',false,
 '誤り。ROEは親会社の既存株主からみた収益性を測る指標なので、分子には非支配株主に帰属する当期純利益を控除した、親会社株主に帰属する当期純利益を用いる。',7136),
('f5-037','2088','標準','持分法による投資損失が計上されている場合、ROAの分子となる事業利益の計算では、その損失額を差し引く必要がある。',true,
 '正しい。事業利益＝営業利益＋持分法による投資損益＋金融収益であり、持分法による投資損失のときは減算する。',7137),
('f5-038','2088','標準','企業集団全体の当期純利益が900で、そのうち親会社が70%を支配する子会社の当期純利益が200である場合、ROEの分子とすべき利益は840である。',true,
 '正しい。非支配株主に帰属する当期純利益は200×30%＝60なので、親会社株主に帰属する当期純利益は900－60＝840となる。',7138),
('f5-039','2088','応用','営業利益300、受取利息・配当金20、持分法による投資損失15、総資本（期中平均）4,000の企業のROAは8.4%である。',false,
 '誤り。事業利益は300－15＋20＝305なので、ROA＝305÷4,000＝約7.6%である。8.4%は持分法による投資損失を加算した場合の誤った値である。',7139),
('f5-040','2088','標準','企業全体の視点から収益性をみる場合、調達した資本が自己資本か他人資本かを区別することが第一義的に重要となる。',false,
 '誤り。企業全体の視点では、自己資本か他人資本かの区別は二義的な問題である。調達したすべての資本（総資本）でいかに効率よく事業利益を稼ぐかが一義的に重要となる。',7140),
('f5-041','2088','基礎','ROEは、企業集団を支配している親会社の、現在の株主の立場から収益性を測る指標である。',true,
 '正しい。そのため分母の自己資本は株主資本とその他の包括利益累計額の合計とし、分子は親会社株主に帰属する当期純利益とする。',7141),
('f5-042','2088','標準','ROEの実績値の計算には自己資本の期中平均を用いるが、残余利益モデルの式に現れるROEの分母には、期末の自己資本が用いられている。',false,
 '誤り。残余利益モデルでは式の導出の都合から、ROEの分母に期首の自己資本を用いている。',7142),
('f5-043','2088','標準','使用総資本を分母とする利益率を計算する場合、分母と理論的に整合する分子の利益は経常利益である。',false,
 '誤り。使用総資本と理論的に対応するのは事業利益（営業利益＋持分法による投資損益＋受取利息・配当金）である。経常利益は支払利息を差し引いた後の利益であり、総資本とは対応しない。',7143),
('f5-044','2088','基礎','総資本事業利益率は、総資本と総資産が一致することから、一般にReturn on Assetを略してROAと呼ばれる。',true,
 '正しい。総資本＝総資産であることから、総資本事業利益率はROA（Return on Asset）と略称される。',7144),
('f5-045','2089','基礎','残余利益モデルに基づけば、株式価値を評価するうえでは、当期の実績ROEよりも将来の期待ROEの推移が重要である。',true,
 '正しい。当期のROEが高くても将来のROEが低ければ、株式価値は低く評価される。',7145),
('f5-046','2089','標準','PBRが1倍を下回っている銘柄は、株価が純資産に比べて割安であると判断するのが理論的に適切である。',false,
 '誤り。PBRが1倍を下回るのは、将来のROEが自己資本コストに届かないと市場が予想していることの表れであり、割安を意味しない。PBRは価値創造・破壊の判定尺度と位置付けるべきである。',7146),
('f5-047','2089','標準','ROEがプラスであっても、自己資本コストを下回る水準にとどまると期待される企業は、残余利益モデルの観点では価値を破壊していることになる。',true,
 '正しい。残余利益は（ROE－自己資本コスト）×自己資本であり、ROEが自己資本コストを下回れば残余利益はマイナスとなり、株式価値は自己資本を下回る。',7147),
('f5-048','2089','基礎','伊藤レポートは、日本企業が最低ラインとして達成すべきROEの水準を5%と提言した。',false,
 '誤り。伊藤レポートは、グローバルな機関投資家が期待する資本コストの平均が7%超であることを踏まえ、最低ラインとして8%を上回るROEの達成を提言した。',7148),
('f5-049','2089','標準','伊藤レポートが示したROE8%という水準は日本企業全般に向けた平均的な目安であり、株主の期待収益率が10%の企業にとっては、8%のROEでは資本コストに届かない。',true,
 '正しい。自己資本コストは企業ごとに異なり、10%の企業もあれば6%の企業もある。ROEの基準は個々の企業の自己資本コストで判断する必要がある。',7149),
('f5-050','2089','応用','期首自己資本が1,000、自己資本コストが8%で、ROE12%が将来にわたり続き、残余利益が成長しないと仮定した場合、残余利益モデルによる株式価値は1,500である。',true,
 '正しい。残余利益は（0.12－0.08）×1,000＝40で、成長率0なので現在価値は40÷0.08＝500となる。株式価値＝1,000＋500＝1,500である。',7150),
('f5-051','2089','応用','期首自己資本1,000、自己資本コスト8%、1期先ROE10%で、残余利益が年3%で成長すると仮定した場合、理論上のPBRは1.25倍である。',false,
 '誤り。1期先の残余利益は（0.10－0.08）×1,000＝20で、その現在価値は20÷（0.08－0.03）＝400となる。株式価値は1,400なので理論上のPBRは1.4倍である。',7151),
('f5-052','2089','標準','残余利益モデルによれば、企業が超えるべきROEのハードルレートは、負債の利子率（他人資本コスト）である。',false,
 '誤り。ROEのベンチマーク（ハードルレート）は自己資本コストであり、株主からみれば期待収益率にあたる。',7152),
('f5-053','2089','基礎','PBR（株価純資産倍率）は、株価を1株当たり純資産（BPS）で割って計算される。',true,
 '正しい。BPSの計算に用いる純資産は、新株予約権や非支配株主持分などを控除して算定されるため、ROEの分母の自己資本とおおむね一致する。',7153),
('f5-054','2090','基礎','ROAを本業と余剰資金運用活動に分けて分析する場合、まず余剰資金運用資本を特定し、経営資本は総資本からそれを差し引いて逆算する。',true,
 '正しい。余剰資金運用資本のほうが特定しやすいため、先に計算し、経営資本＝総資本－余剰資金運用資本として求める。',7154),
('f5-055','2090','標準','本テキストでは、投資その他の資産に計上されている関連会社株式は、余剰資金運用資本の構成要素として扱われる。',false,
 '誤り。関連会社への投資は連結グループ経営の一環とみなされ、関連会社株式は経営資本の構成要素として扱われる。',7155),
('f5-056','2090','標準','小売業で出店先の建物を借りるために差し入れた敷金・保証金は、投資その他の資産に計上されていても、経営資本の構成要素とみなす。',true,
 '正しい。敷金・保証金は本業に不可欠なものであり、関連会社株式と同様に経営資本として扱う。',7156),
('f5-057','2090','標準','本業の利益率である経営資本営業利益率は、営業利益に受取利息・配当金を加えた額を、経営資本（期中平均）で割って求める。',false,
 '誤り。経営資本営業利益率の分子は営業利益と持分法による投資利益の合計である。受取利息・配当金などの金融収益は、余剰資金運用活動の利益率の分子となる。',7157),
('f5-058','2090','応用','経営資本営業利益率が6%で構成割合が70%、余剰資金運用活動の利益率が1%で構成割合が30%の企業のROAは4.5%である。',true,
 '正しい。ROAは2つの活動の利益率を資本の構成割合で加重平均したもので、6%×0.7＋1%×0.3＝4.5%となる。',7158),
('f5-059','2090','応用','ROAが4%で、余剰資金運用資本の構成割合が40%、その利益率が1%の企業の経営資本営業利益率は6.5%である。',false,
 '誤り。経営資本営業利益率をxとすると、x×0.6＋1%×0.4＝4%より、x＝（4%－0.4%）÷0.6＝6%である。',7159),
('f5-060','2090','基礎','報告セグメントとして開示されるのは、売上高・利益・資産の3項目すべてについて、全事業セグメント合計の10%以上を占めるものに限られる。',false,
 '誤り。売上高、利益、資産のいずれかが全事業セグメント合計の10%以上であれば報告セグメントとなる。すべてを満たす必要はない。',7160),
('f5-061','2090','標準','マネジメント・アプローチに基づくセグメント情報は、経営者が意思決定や業績評価のために企業を区分した方法を基礎として開示されるため、利用者は経営者と同じ目線で企業を把握できる。',true,
 '正しい。セグメント情報を用いると、多角化や海外展開をしている企業の事業部門別・地域別の利益率を比較できる。',7161),
('f5-062','2090','標準','本業の利益率が余剰資金運用活動の利益率を上回る企業では、余剰資金運用資本の構成割合が高まるにつれて、ROAが押し下げられる可能性がある。',true,
 '正しい。ROAは両活動の利益率の加重平均なので、利益率の低い余剰資金運用活動のウェイトが高まるほど、ROAを押し下げる要因となる。',7162),
('f5-063','2090','標準','ROAにならってセグメントごとに求める利益率は、セグメント利益を期末時点のセグメント資産で割って算出する。',false,
 '誤り。ROAと同様に、セグメント利益を期首と期末のセグメント資産の平均（期中平均）で割って算出する。',7163),
('f5-064','2091','基礎','ROAは、売上高を介在させることで、売上高事業利益率と総資本回転率の積に分解できる。',true,
 '正しい。ROA＝事業利益/売上高×売上高/総資本＝売上高事業利益率×総資本回転率である。',7164),
('f5-065','2091','基礎','ROEを2つの要素に分解する場合、売上高純利益率と総資本回転率の積として表される。',false,
 '誤り。ROEの2分解は売上高純利益率×自己資本回転率である。総資本回転率を用いる場合は、さらに財務レバレッジを掛けた3分解となる。',7165),
('f5-066','2091','基礎','デュポン・システムにおける財務レバレッジは、自己資本に対する総資本の倍率であり、自己資本比率の逆数にあたる。',true,
 '正しい。財務レバレッジ＝総資本÷自己資本であり、自己資本比率（自己資本÷総資本）の逆数である。',7166),
('f5-067','2091','基礎','デュポン・システムでROEを3要素に分解する際の財務レバレッジとは、負債を自己資本で割った負債比率のことである。',false,
 '誤り。財務レバレッジは総資本÷自己資本である。負債比率をD/Eとすると、財務レバレッジはD/E＋1と表せる。',7167),
('f5-068','2091','標準','薄利多売によるシェア拡大策をとると、総資本回転率は上昇しても売上高純利益率は低下しやすく、ROEの3要素を同時に高めることは難しい。',true,
 '正しい。3要素はそれぞれ大きいほどROEを高めるが、同時に上昇させるのは困難である点に注意が必要である。',7168),
('f5-069','2091','基礎','総資本回転率は総資本を売上高で割った比率であり、この値が低いほど資本が効率的に利用されていることを示す。',false,
 '誤り。総資本回転率は売上高÷総資本であり、営業循環を年に何回繰り返せるかを表す。高いほど資本の利用効率が高く、ROAやROEを高める方向に作用する。',7169),
('f5-070','2091','応用','売上高純利益率が4%、総資本回転率が1.5回、自己資本比率が50%の企業のROEは12%である。',true,
 '正しい。財務レバレッジは自己資本比率の逆数で2倍となり、ROE＝4%×1.5×2＝12%である。',7170),
('f5-071','2091','応用','売上高20,000、親会社株主に帰属する当期純利益1,000、総資本回転率0.8回、財務レバレッジ2.5倍の企業のROEは12.5%である。',false,
 '誤り。売上高純利益率は1,000÷20,000＝5%なので、ROE＝5%×0.8×2.5＝10%である。',7171),
('f5-072','2091','標準','総資本回転率が1.2回、自己資本比率が40%の企業の自己資本回転率は3.0回である。',true,
 '正しい。自己資本回転率＝売上高/自己資本＝総資本回転率×財務レバレッジであり、1.2×（1÷0.4）＝3.0回となる。',7172),
('f5-073','2091','標準','ROEの3分解において自己資本に期中平均を用いる場合には、総資本についても期中平均を用いて計算する。',true,
 '正しい。分母の時点をそろえることで、各要素の積がROEに一致する。',7173),
('f5-074','2091','標準','負債の割合を高めて財務レバレッジを効かせると、計算の構造上ROEは低下するが、安全性は高まる。',false,
 '誤り。財務レバレッジを高めれば算式上ROEは上がるが、負債比率の上昇に伴って安全性は損なわれていく。',7174),
('f5-075','2091','基礎','デュポン・システムは、ROEを売上高営業利益率、総資本回転率、財務レバレッジの3要素に分解する方法である。',false,
 '誤り。3分解の第1要素は売上高純利益率（親会社株主に帰属する当期純利益÷売上高）である。分子をROEと同じ利益にそろえる必要がある。',7175),
('f5-076','2092','基礎','サステイナブル成長率とは、増資による自己資本の増加を想定せず、利益を社内に留保して再投資することのみで、長い期間にわたり維持できる成長率をいう。',true,
 '正しい。サステイナブル成長率＝ROE×（1－配当性向）で計算される。',7176),
('f5-077','2092','標準','サステイナブル成長率の前提では、内部留保によって自己資本が増えても、負債の残高は期首の水準のまま一定に保たれる。',false,
 '誤り。資本構成（負債と自己資本の比率）を一定に保つことが前提なので、内部留保で自己資本が増えると、比率を保つために負債も増える。',7177),
('f5-078','2092','基礎','ROEが一定であれば、配当性向が高い企業ほどサステイナブル成長率は高くなる。',false,
 '誤り。サステイナブル成長率＝ROE×（1－配当性向）なので、配当性向が高い（内部留保率が低い）ほど成長率は低くなる。',7178),
('f5-079','2092','応用','期首自己資本が2,000億円、親会社株主に帰属する当期純利益が160億円、配当が48億円の企業のサステイナブル成長率は5.6%である。',true,
 '正しい。ROE＝160÷2,000＝8%、配当性向＝48÷160＝30%なので、サステイナブル成長率＝8%×（1－0.3）＝5.6%である。',7179),
('f5-080','2092','応用','ROEが12%で内部留保率が40%の企業のサステイナブル成長率は7.2%である。',false,
 '誤り。サステイナブル成長率＝ROE×内部留保率＝12%×0.4＝4.8%である。7.2%は配当性向40%と取り違えた場合の値である。',7180),
('f5-081','2092','標準','サステイナブル成長率の算式で使うROEは、式を導く都合上、期首の自己資本を分母とする。',true,
 '正しい。クリーン・サープラス関係を期首の自己資本で割って導出するため、ROEの分母は期首自己資本となる。',7181),
('f5-082','2092','標準','ROEには平均回帰の傾向がみられないため、当期の高いROEを用いて計算したサステイナブル成長率は、将来も実現される可能性が高い。',false,
 '誤り。ROEには平均回帰の性格があり、高いROEも競争激化などで産業平均に収束しやすい。当期の高いROEから求めた成長率は現実には届かないおそれがある。',7182),
('f5-083','2092','標準','配当を減らして内部留保率を高めても、その資金が高い利益率の見込める事業に実際に投資され、しかも成功しなければ、成長率の上昇にはつながらない。',true,
 '正しい。内部留保率が高いほど成長率が高まる関係は、投資の実行と成功という2条件が満たされる必要があり、実際に成り立つかは定かではない。',7183),
('f5-084','2092','応用','ROA10%、自己資本比率50%、負債（全額有利子）の利子率4%、税率30%、配当性向40%の企業のサステイナブル成長率は6.72%である。',true,
 '正しい。総資本1,000とすると負債500・自己資本500で、純利益＝（100－20）×0.7＝56、ROE＝56÷500＝11.2%となる。成長率＝11.2%×（1－0.4）＝6.72%である。',7184),
('f5-085','2092','標準','サステイナブル成長率は、財務諸表の各項目間の比率が変化しながら企業が成長していく状態を想定した尺度である。',false,
 '誤り。財務諸表の各項目の比率が保たれたまま、全体が同じ率で拡大する状態が想定されている。',7185),
('f5-086','2093','基礎','ROAが負債の利子率を上回る業績好調時に負債を利用すると、税引前ROEはROAを上回る。',true,
 '正しい。税引前ROE＝ROA＋（ROA－r）×D/Eであり、ROA＞rなら第2項がプラスとなる。',7186),
('f5-087','2093','標準','税引前ROEとROAの差の大きさは、ROAと負債利子率の差だけで決まり、負債比率（D/E）の大小には左右されない。',false,
 '誤り。差は（ROA－r）×D/Eで表されるので、負債比率D/Eが高いほど税引前ROEとROAの乖離は大きくなる。',7187),
('f5-088','2093','応用','ROAが9%、負債利子率が3%、負債比率（D/E）が1.5倍の企業の税引前ROEは18%である。',true,
 '正しい。税引前ROE＝9%＋（9%－3%）×1.5＝18%である。',7188),
('f5-089','2093','応用','ROAが2%、負債利子率が4%、負債比率（D/E）が3倍の企業の税引前ROEは0%である。',false,
 '誤り。税引前ROE＝2%＋（2%－4%）×3＝－4%である。ROAが利子率を下回るため、税引前ROEはROAを下回りマイナスとなる。',7189),
('f5-090','2093','標準','一般的な税引後のROEは、ROAと負債利子率から求めた税引前ROEに（1－税率）を乗じることで求められる。',true,
 '正しい。税引前ROE＝ROA＋（ROA－r）×D/Eの右辺に（1－税率）を掛ければ、税引後のROEとなる。',7190),
('f5-091','2093','基礎','負債を利用している企業であっても、ROEがROAを上回ることは計算の構造上ありえない。',false,
 '誤り。業績が好調でROAが負債利子率を超えている局面で負債を使えば、財務レバレッジの効果によってROEはROAより高くなり得る。',7191),
('f5-092','2093','標準','財務レバレッジは負債比率（D/E）に1を加えた値として表せるので、負債比率が高いほど財務レバレッジも高くなる。',true,
 '正しい。総資本/自己資本＝（D＋E）/E＝D/E＋1である。',7192),
('f5-093','2093','基礎','総資本の一部を負債で調達すると、一般に業績の変化に対するROEの変動性は小さくなる。',false,
 '誤り。負債を利用すると、ROAの変動が（ROA－r）×D/Eの部分で拡大されるため、ROEの変動性は大きくなる。',7193),
('f5-094','2093','標準','ROAが負債利子率とちょうど等しい場合、負債比率の大小にかかわらず、税引前ROEはROAと等しくなる。',true,
 '正しい。税引前ROE＝ROA＋（ROA－r）×D/Eで、ROA＝rなら第2項がゼロとなるため、D/Eに関係なく税引前ROE＝ROAとなる。',7194),
('f5-095','2094','基礎','百分率財務諸表は各項目を売上高や総資産で割って表すため、企業規模の影響を取り除いたうえで財務諸表の質的な特徴を比べることができる。',true,
 '正しい。百分率損益計算書は売上高、百分率貸借対照表は総資産を100%として各項目の割合を示し、企業間比較と期間比較に用いる。',7195),
('f5-096','2094','標準','売上高が前期より10%減少し、売上原価は5%しか減少しなかった場合、売上原価率は前期より低下する。',false,
 '誤り。分母の売上高が分子の売上原価より大きく減少するので、売上原価率は上昇する。例えば売上高100・原価60が売上高90・原価57になると、原価率は60%から約63%に上がる。',7196),
('f5-097','2094','標準','特別利益が計上されると、売上高純利益率の低下幅が売上高事業利益率の低下幅より小さくなることがある。',true,
 '正しい。事業利益より下の段階で特別利益が加わると、純利益ベースの利益率の落ち込みは緩和される。ただし損失の穴埋めのような特別利益は継続性に乏しく、内容に注意が必要である。',7197),
('f5-098','2094','応用','前期は売上高1,000、売上原価600、販管費300、当期は売上高900、売上原価560、販管費290であった企業の売上高営業利益率は、約4.4ポイント低下した。',true,
 '正しい。営業利益率は前期100÷1,000＝10%、当期50÷900＝約5.6%であり、約4.4ポイント低下している。',7198),
('f5-099','2094','応用','前期は売上高1,000・販管費300、当期は売上高900・販管費290であった企業の販管費率は、前期より低下した。',false,
 '誤り。販管費率は前期300÷1,000＝30%、当期290÷900＝約32.2%であり、上昇している。販管費の減少率が売上高の減少率より小さいためである。',7199),
('f5-100','2094','標準','同業他社と比べて売上原価率が高いことは、その企業の商品が消費者にとって相対的に魅力的であることを示している。',false,
 '誤り。売上原価率の高さは、顧客を引きつける商品が相対的に乏しいことを示す。そうした企業では、コスト削減に加えて魅力的な商品開発が課題となる。',7200),
('f5-101','2094','基礎','百分率損益計算書は、収益・費用・利益の各項目を総資産に対する割合で示したものである。',false,
 '誤り。百分率損益計算書は売上高を100%として各項目の割合を示す。総資産を100%とするのは百分率貸借対照表である。',7201),
('f5-102','2094','標準','ROAやROEの分解によって売上高利益率の低さが判明した場合、その原因となる費用項目を突き止めるには、百分率損益計算書による企業間比較と期間比較が有効である。',true,
 '正しい。売上原価率や販管費率など、売上高に対する各項目の割合を比べることで、利益率が低い原因を追跡できる。',7202),
('f5-103','2095','基礎','百分率貸借対照表は、資産・負債・純資産の各項目が総資産の何%にあたるかを示したもので、どの資産が金額的に重要かを把握するのに役立つ。',true,
 '正しい。売上債権、棚卸資産、有形固定資産、手元流動性などの割合を確認したうえで、項目ごとの回転率を分析する。',7203),
('f5-104','2095','標準','売上債権回転率を計算する際は、分母には貸倒引当金を差し引いた後の売上債権の額を用いる。',false,
 '誤り。貸倒引当金は控除しない。差し引くと、回収の怪しい債権が多い企業ほど回転率が高めに出てしまうからである。',7204),
('f5-105','2095','標準','銀行で割り引いた受取手形を売上債権回転率の分母に足し戻さないのは、現行の会計基準では手形を割り引いた時点でその消滅を認識するためである。',true,
 '正しい。裏書譲渡した手形も同様であり、これらの金額は分母の売上債権に足し戻さない。',7205),
('f5-106','2095','基礎','売上債権回転期間（日数）は、売上債権回転率に365日を掛けて求める。',false,
 '誤り。売上債権回転期間＝365日÷売上債権回転率である。売上債権が回収されるまでに平均的にかかる日数を表し、短いほど回収が効率的である。',7206),
('f5-107','2095','標準','現金販売の割合が高い小売業では売上債権がごくわずかであるため、売上債権回転率が著しく高く算定されやすい。',true,
 '正しい。こうした業種では回転率の高さをそのまま回収効率の良さと解釈できない。売上債権が重要な業種では、その動向が収益性と資金繰りの両面で重要となる。',7207),
('f5-108','2095','応用','売上高が7,300、売上債権が期首380・期末420の企業の売上債権回転期間は20日である。',true,
 '正しい。売上債権（期中平均）は400なので回転率は7,300÷400＝18.25回となり、回転期間は365÷18.25＝20日である。',7208),
('f5-109','2095','応用','売上原価が6,000、棚卸資産が期首1,100・期末900の企業について、売上原価を用いて計算した棚卸資産回転期間は約73日である。',false,
 '誤り。棚卸資産（期中平均）は1,000なので回転率は6,000÷1,000＝6回となり、回転期間は365÷6＝約61日である。',7209),
('f5-110','2095','標準','総資本回転率との整合性を重視するなら、棚卸資産回転率の分子には売上高ではなく売上原価を用いるのが望ましい。',false,
 '誤り。総資本回転率の分解要素とみる場合は、分子に総資本回転率と同じ売上高を用いるのが望ましい。売上原価を使うのは、取得原価で評価された棚卸資産との対応を重視する考え方である。',7210),
('f5-111','2095','標準','棚卸資産回転率が低下して在庫の滞留期間が長くなると、資金繰りが圧迫されるおそれがあるほか、商品が陳腐化する危険も増す。',true,
 '正しい。在庫が長く滞留するほど資金が寝てしまうため、棚卸資産回転率の低下傾向には注意が必要である。',7211),
('f5-112','2095','標準','有望な製品の生産設備に大規模な投資を行ったことで有形固定資産回転率が一時的に低下した場合、その投資は資産効率を悪化させる誤った意思決定と評価すべきである。',false,
 '誤り。将来の収益獲得につながる投資であれば実行すべきものであり、必要な投資を延期して回転率を保つほうが望ましくない。回転率は将来の見通しも考慮して慎重に評価する必要がある。',7212),
('f5-113','2095','基礎','手元流動性とは、現金・預金と、流動資産に計上されている有価証券の合計額をいう。',true,
 '正しい。すぐに支払いに充てられる資金であることから、手元流動性と呼ばれる。',7213),
('f5-114','2095','応用','手元流動性（期中平均）が1,500、年間売上高が6,000の企業の手元流動性比率は3.0ヵ月である。',true,
 '正しい。平均月商は6,000÷12＝500なので、手元流動性比率＝1,500÷500＝3.0ヵ月分となる。',7214),
('f5-115','2095','標準','手元流動性比率が高い企業ほど短期的な支払能力が高く、資金が手元に大量に滞留していても、将来の成長や買収リスクの面で懸念はない。',false,
 '誤り。手元流動性が過大だと、回収した資金が再投資されず将来の成長に結び付かないうえ、余剰資金に目を付けた敵対的買収を招きやすくなる。',7215),
('f5-116','2095','基礎','売上債権や棚卸資産など総資産の主な項目ごとに回転率を求める場合、分母の各資産残高には期末残高を用いるのが原則である。',false,
 '誤り。総資本回転率の計算と同様に、分母の各資産残高には期首と期末の平均（期中平均）を用いる。',7216),
('f5-117','2096','基礎','付加価値とは企業活動によって新たに付け加えられた経済価値であり、生産性とはそれを生み出す企業の力をいう。',true,
 '正しい。外部から購入したものに企業内の資源を投じて加えた価値が付加価値である。',7217),
('f5-118','2096','基礎','控除法では、総生産高から人件費を差し引いて付加価値を計算する。',false,
 '誤り。控除法では、総生産高から前給付費用（原材料費・燃料費・外注加工費など、前段階の企業から購入した部分）を差し引いて付加価値を求める。人件費は付加価値の構成要素である。',7218),
('f5-119','2096','標準','原材料費や外注加工費、運賃、保険料など、生産のために前段階の企業から買い入れた部分は、前給付費用と呼ばれる。',true,
 '正しい。前給付費用に付加価値を加えたものが総生産高となり、控除法ではここから前給付費用を差し引く。',7219),
('f5-120','2096','標準','控除法は、前給付費用の金額を有価証券報告書から具体的に特定できるため、加算法よりも実務上の計算が容易である。',false,
 '誤り。前給付費用の構成要素は公表資料から具体的に特定できないため、控除法の適用には問題がある。そこで本テキストでは、計算が比較的容易な加算法を用いる。',7220),
('f5-121','2096','標準','加算法の考え方では利益は付加価値の一部にすぎないため、赤字の企業であっても、付加価値を生み出す限り社会的な存在価値がある。',true,
 '正しい。付加価値は人件費・賃借料・他人資本利子・税金費用・当期純利益の合計であり、純損失でも他の分配先に価値を生んでいる。',7221),
('f5-122','2096','標準','本テキストの加算法では、非支配株主に帰属する当期純利益は、親会社株主に帰属する当期純利益とあわせて当期純利益の項目に含める。',false,
 '誤り。非支配株主に帰属する当期純利益は支払利息に準じるものとして、他人資本利子に含める。非支配株主持分を固定負債に準じて扱う取扱いと整合させるためである。',7222),
('f5-123','2096','標準','加算法の税金費用には法人税等調整額を加えた「法人税等合計」を用い、販管費に租税公課が区分表示されていればその金額も含める。',true,
 '正しい。税効果会計による調整後の税金費用を用い、固定資産税などの租税公課も税金費用に含める。',7223),
('f5-124','2096','標準','加算法で付加価値を計算する際、優先株に対する配当は他人資本利子に含めて扱う。',false,
 '誤り。優先株配当には契約上の支払義務がないこともあるため、他人資本利子には含めない。',7224),
('f5-125','2096','応用','人件費500、賃借料120、支払利息30、非支配株主に帰属する当期純利益10、税金費用80、親会社株主に帰属する当期純利益150の企業の付加価値（加算法）は890である。',true,
 '正しい。非支配株主に帰属する当期純利益は他人資本利子に含めるので、付加価値＝500＋120＋（30＋10）＋80＋150＝890となる。',7225),
('f5-126','2096','応用','加算法で計算した付加価値が700、減価償却費が100の企業の粗付加価値は600である。',false,
 '誤り。加算法で求まるのは減価償却費を控除した純付加価値であり、粗付加価値は減価償却費を加えた700＋100＝800となる。',7226),
('f5-127','2096','応用','他の条件が変わらずに法人税が減税されると、加算法で計算した付加価値はその分だけ増加する。',false,
 '誤り。減税しても税金費用が減り、その分税引後の当期純利益が増えるだけで、両者の付け替えに終わる。付加価値の総額は変わらない。',7227),
('f5-128','2097','基礎','労働生産性は付加価値額を従業員数で割ったもので、従業員1人当たりでどれだけの付加価値を生み出したかを測定する。',true,
 '正しい。付加価値の源泉が従業員の労働であることから、従業員1人当たり付加価値額を観察する。',7228),
('f5-129','2097','基礎','労働生産性の計算では、臨時雇用者も正規従業員と同じく1人として数えて全従業員数を求めるのが一般的である。',false,
 '誤り。一般には臨時雇用者を正規従業員の半人分として扱い、全従業員数を求める。',7229),
('f5-130','2097','基礎','労働生産性の分母となる従業員数には、決算日時点の期末人数を用いる。',false,
 '誤り。分子の付加価値額は1年間のフローなので、それに合わせて分母の従業員数は期中平均とする。',7230),
('f5-131','2097','標準','労働装備率は有形固定資産（平均）を従業員数（平均）で割ったもので、機械化が進んだ資本集約的な産業ほど高くなる傾向がある。',true,
 '正しい。労働装備率は、従業員1人がどれだけの設備を使っているかを示す。機械化が進むほど高くなる。',7231),
('f5-132','2097','標準','設備生産性は、有形固定資産（平均）を付加価値額で割って求める指標であり、低いほど設備が効率的に使われている。',false,
 '誤り。設備生産性は付加価値額÷有形固定資産（平均）であり、高いほど有形固定資産が効率的に使われて多くの付加価値を生み出したことを示す。',7232),
('f5-133','2097','標準','労働装備率が4百万円、設備生産性が250%の企業の労働生産性は10百万円である。',true,
 '正しい。労働生産性＝労働装備率×設備生産性＝4百万円×2.5＝10百万円である。',7233),
('f5-134','2097','応用','付加価値額6,000百万円、正規従業員が期首380人・期末420人、臨時雇用者（期中平均）200人の企業の労働生産性は10百万円である。',false,
 '誤り。臨時雇用者を1/2とみなすと平均従業員数は（380＋420）÷2＋200×0.5＝500人で、労働生産性は6,000÷500＝12百万円となる。10百万円は臨時雇用者を1人と数えた場合の値である。',7234),
('f5-135','2097','標準','設備生産性が低下しないかぎり、設備投資によって労働装備率を高めれば、労働生産性は向上する。',true,
 '正しい。労働生産性＝労働装備率×設備生産性なので、設備生産性が維持されれば労働装備率の上昇がそのまま労働生産性を高める。',7235),
('f5-136','2097','標準','売上高を介在させた労働生産性の分解によれば、付加価値率が一定である場合、従業員1人当たり売上高が増加しても労働生産性は変わらない。',false,
 '誤り。労働生産性＝1人当たり売上高×付加価値率なので、付加価値率が一定なら1人当たり売上高の増加に比例して労働生産性も高まる。',7236),
('f5-137','2097','標準','労働生産性の計算に必要な従業員数は、有価証券報告書の「従業員の状況」から収集でき、臨時雇用者数は年間の平均人員が外数で記載されている。',true,
 '正しい。連結会社と提出会社の両方について従業員数が記載されており、臨時雇用者数は括弧内の外数で示される。',7237),
('f5-138','2098','基礎','生み出された付加価値額のうち人件費に回った割合を労働分配率と呼ぶ。',true,
 '正しい。人件費や賃借料などの構成要素ごとに付加価値額に対する比率を求めると、分配の状況がわかる。',7238),
('f5-139','2098','標準','景気が後退して業績が悪化し始めた段階では、一般に労働分配率は低下する。',false,
 '誤り。人件費は固定費の性格が強く業績悪化時にすぐには削減できない一方、分母の付加価値額は縮むので、労働分配率は高まる。',7239),
('f5-140','2098','標準','労働生産性が20百万円、労働分配率が55%の企業の従業員1人当たり人件費は11百万円である。',true,
 '正しい。1人当たり人件費＝労働生産性×労働分配率＝20百万円×0.55＝11百万円である。',7240),
('f5-141','2098','応用','労働分配率を50%に維持したまま従業員1人当たり人件費を6百万円に引き上げるには、労働生産性を10百万円にすれば足りる。',false,
 '誤り。1人当たり人件費＝労働生産性×労働分配率なので、必要な労働生産性は6百万円÷0.5＝12百万円である。',7241),
('f5-142','2098','標準','人件費は操業度が変わってもあまり増減せず、毎期ほぼ一定額かかる固定費の性格が強い。',true,
 '正しい。そのため売上が増減しても人件費はあまり変わらず、1人当たり人件費は時系列的に安定しやすい。',7242),
('f5-143','2098','標準','労働分配率の引上げは株主など他の利害関係者への影響が小さいため、給与水準を引き上げる手段として際限なく用いることができる。',false,
 '誤り。労働分配率を高めると親会社株主に帰属する当期純利益が減少するなど他の利害関係者へのマイナスの影響が大きく、引上げには限界がある。給与水準の引上げには労働生産性の向上が不可欠である。',7243),
('f5-144','2098','基礎','付加価値の分配状況は、人件費や賃借料などが売上高の何%にあたるかを計算して把握する。',false,
 '誤り。分配状況は、各構成要素が付加価値額に占める割合で把握する。人件費の割合が労働分配率である。',7244),
('f5-145','2098','標準','労働生産性が低下していても、労働分配率が上昇すれば、従業員1人当たり人件費の水準を維持することができる。',true,
 '正しい。1人当たり人件費＝労働生産性×労働分配率なので、一方の低下を他方の上昇で埋め合わせることができる。ただし株主に帰属する利益にしわ寄せが生じる。',7245),
('f5-146','2099','基礎','当座比率は、現金預金・受取手形・売掛金・有価証券からなる当座資産を流動負債で割って求める指標である。',true,
 '正しい。流動資産の中でも特に早期に現金化できる資産で流動負債をどの程度まかなえるかを示し、高いほど短期的な債務返済能力が高い。',7246),
('f5-147','2099','基礎','流動比率や当座比率の計算では、分母・分子とも期首と期末の平均残高を用いる。',false,
 '誤り。流動比率や当座比率は分母・分子ともに貸借対照表のデータなので、当期末残高の値を用いる（期中平均は用いない）。',7247),
('f5-148','2099','標準','当座比率の分子となる当座資産は、貸倒引当金の金額を控除して計算する。',true,
 '正しい。当座比率＝（現金預金＋受取手形・売掛金＋有価証券－貸倒引当金）÷流動負債である。',7248),
('f5-149','2099','標準','売上債権や棚卸資産の回転率を高めるために在庫を圧縮した結果、流動比率が低下した場合には、ただちにその企業の安全性が低下したと判断すべきである。',false,
 '誤り。売上債権や棚卸資産を最適な水準に管理する結果として流動比率が下がることもあり、それだけで安全性の低下と判断してはならない。他の指標と合わせた総合的な評価が必要である。',7249),
('f5-150','2099','基礎','資本構成を表す負債比率は、負債を総資産で割って求める指標であり、低いほど安全性が高い。',false,
 '誤り。負債比率は他人資本÷自己資本で求める。自己資本を総資産（総資本）で割ったものが自己資本比率である。',7250),
('f5-151','2099','標準','本テキストでは、純資産の部の非支配株主持分と新株予約権を固定負債に準じて扱うため、負債比率の他人資本はこれらを負債に加えて計算する。',true,
 '正しい。他人資本＝負債＋非支配株主持分＋新株予約権であり、自己資本は株主資本＋その他の包括利益累計額である。',7251),
('f5-152','2099','標準','自己資本比率が極めて高い企業は、財務レバレッジが高くなるため、ROEが押し上げられやすい。',false,
 '誤り。自己資本比率が高いと、その逆数である財務レバレッジは低くなり、ROEを低下させる。安全性の面では望ましくても、高すぎると株主還元などで自己資本を減らす施策が大切になる。',7252),
('f5-153','2099','基礎','固定比率は固定資産と繰延資産の合計を自己資本で割って求める指標であり、安全性の観点からは低いほど望ましい。',true,
 '正しい。長期的に拘束される資金は、返済不要な自己資本の範囲内にあることが望ましく、固定比率100%が目安とされる。',7253),
('f5-154','2099','標準','固定長期適合率が100%を超えている場合、固定的な資産の取得に短期で返済すべき流動負債が充てられていることになり、資金繰りに行き詰まるおそれが大きくなる。',true,
 '正しい。固定的な資産は、少なくとも自己資本と固定負債などの長期的な資本の範囲内に収まっている必要がある。',7254),
('f5-155','2099','標準','固定長期適合率は、固定資産と繰延資産の合計を、自己資本と流動負債の合計で割って求める。',false,
 '誤り。固定長期適合率の分母は長期的な資本、すなわち純資産（自己資本＋非支配株主持分＋新株予約権）と固定負債の合計である。',7255),
('f5-156','2099','応用','現金預金300、売掛金240、棚卸資産300、その他の流動資産60を保有し、流動負債が600の企業（貸倒引当金なし）の流動比率は150%、当座比率は90%である。',true,
 '正しい。流動資産は900なので流動比率は900÷600＝150%、当座資産は300＋240＝540なので当座比率は540÷600＝90%である。',7256),
('f5-157','2099','応用','負債3,000、非支配株主持分200、自己資本1,800の企業の負債比率は約167%である。',false,
 '誤り。本テキストの定義では他人資本に非支配株主持分を含めるので、負債比率＝（3,000＋200）÷1,800＝約178%である。約167%は非支配株主持分を除いた値である。',7257),
('f5-158','2100','基礎','流動比率や自己資本比率などのストック指標は、特定時点の資産を処分して債務を返済することを仮定しているため、収益・費用などのフロー・データに基づく分析で補う必要がある。',true,
 '正しい。企業は通常、事業活動の成果である収益から利息の支払いや債務の返済を行うので、損益計算書やキャッシュ・フロー計算書に基づく指標で補完する。',7258),
('f5-159','2100','標準','インタレスト・カバレッジ・レシオの金融費用には支払利息のみを含め、手形売却損が別立てで計上されていても含めない。',false,
 '誤り。金融費用の中心は支払利息だが、社債利息や手形売却損が区分して表示されている場合は、これらも加える。',7259),
('f5-160','2100','標準','インタレスト・カバレッジ・レシオの計算では、非支配株主に帰属する当期純利益を分母の金融費用に含めない。',true,
 '正しい。付加価値の計算では他人資本利子に準じて扱うが、ICRの分母には含めない。',7260),
('f5-161','2100','応用','営業利益500、受取利息・配当金40、持分法による投資利益20、支払利息80、社債利息20の企業のインタレスト・カバレッジ・レシオは5.6倍である。',true,
 '正しい。事業利益は500＋40＋20＝560、金融費用は80＋20＝100なので、ICR＝560÷100＝5.6倍である。',7261),
('f5-162','2100','応用','営業利益120、受取配当金10、支払利息100、手形売却損30（別立て計上）の企業のインタレスト・カバレッジ・レシオは1.3倍である。',false,
 '誤り。金融費用には手形売却損も含めるので、ICR＝（120＋10）÷（100＋30）＝1.0倍である。1.3倍は手形売却損を除いた値である。',7262),
('f5-163','2100','標準','インタレスト・カバレッジ・レシオは利息の支払能力だけを測る指標であり、その推移から利益の獲得能力を読み取ることはできない。',false,
 '誤り。ICRは分子に利益を用いるので、利息の支払能力と同時に利益を稼ぐ力も同時に確かめられる複合的な指標である。',7263),
('f5-164','2102','基礎','損益分岐点売上高は、固定費を（1－変動費率）で割って求めることができる。',true,
 '正しい。売上高＝固定費＋変動費率×売上高を売上高について解くと、損益分岐点売上高＝固定費÷（1－変動費率）となる。',7264),
('f5-165','2102','基礎','固定費が同じであれば、変動費率が低い企業ほど損益分岐点売上高は大きくなる。',false,
 '誤り。損益分岐点売上高＝固定費÷（1－変動費率）なので、変動費率が低いほど分母が大きくなり、損益分岐点売上高は小さくなる。',7265),
('f5-166','2102','標準','損益分岐点売上高は営業利益がゼロとなる売上高であり、営業黒字を確保するために超えなければならない売上の水準を意味する。',true,
 '正しい。ここでの費用は売上原価と販売費及び一般管理費の合計であり、収益直線と費用直線の交点が損益分岐点となる。',7266),
('f5-167','2102','基礎','損益分岐点比率は実際の売上高を損益分岐点売上高で割って求め、この比率が高いほど減収に対する耐性があるといえる。',false,
 '誤り。損益分岐点比率＝損益分岐点売上高÷実際の売上高であり、低いほど営業赤字に陥りにくく、減収に対する耐性がある。',7267),
('f5-168','2102','標準','固定費240、変動費率60%、実際の売上高800の企業の損益分岐点比率は75%である。',true,
 '正しい。損益分岐点売上高は240÷（1－0.6）＝600なので、損益分岐点比率＝600÷800＝75%である。',7268),
('f5-169','2102','応用','固定費360、変動費率70%の企業が営業利益60を上げるのに必要となる売上高は1,200である。',false,
 '誤り。必要な売上高は（固定費360＋目標利益60）÷（1－0.7）＝1,400である。1,200は営業利益がゼロとなる損益分岐点売上高である。',7269),
('f5-170','2102','応用','ある期の売上高が500で営業損失が10、変動費率が80%の企業が、費用構造を変えずに翌期に営業利益20を確保するには、売上高が650必要である。',true,
 '正しい。固定費＝500－0.8×500－（－10）＝110となり、必要な売上高は（110＋20）÷（1－0.8）＝650である。',7270),
('f5-171','2102','標準','損益分岐点比率を引き下げるには、実際の売上高を増やすことのほか、固定費の削減や変動費率の引下げが有効である。',true,
 '正しい。分母の実際の売上高を増やすか、分子の損益分岐点売上高を小さくすればよく、後者には固定費の削減と変動費率の引下げが効く。',7271),
('f5-172','2102','標準','損益分岐点比率が70%の企業は、売上高が70%減少するまで営業黒字を維持できる。',false,
 '誤り。損益分岐点比率70%は、売上高が30%減少して現在の70%の水準になると営業利益がゼロになることを意味する。',7272),
('f5-173','2102','基礎','安全余裕度は、損益分岐点比率に1を加えた値として計算される。',false,
 '誤り。安全余裕度は1－損益分岐点比率であり、損益分岐点比率と表裏一体の指標である。',7273),
('f5-174','2102','標準','売上高を横軸、費用を縦軸にとった費用直線では、固定費が直線の傾きに、変動費率が縦軸との切片にあたる。',false,
 '誤り。費用＝固定費＋変動費率×売上高と表せるので、固定費が切片、変動費率が傾きにあたる。',7274),
('f5-175','2103','基礎','営業レバレッジは営業利益の変化率を売上高の変化率で割った倍率であり、1÷（1－損益分岐点比率）で表すことができる。',true,
 '正しい。売上高の小さな変動が営業利益段階で拡大される現象を、てこの作用になぞらえて営業レバレッジという。',7275),
('f5-176','2103','応用','損益分岐点比率が75%の企業で、費用構造を変えずに売上高が8%減少すると、営業利益は24%減少する。',false,
 '誤り。営業レバレッジは1÷（1－0.75）＝4倍なので、営業利益の減少率は8%×4＝32%である。',7276),
('f5-177','2103','標準','売上高が落ち込んでも固定費は減らないので、営業費用に占める固定費の割合が大きい企業ほど、減収時に営業利益が大きく落ち込む。',true,
 '正しい。費用構造は、不確実性リスクを拡大させる要因の1つである。',7277),
('f5-178','2103','標準','減収時に営業利益が売上高の減少率以上に落ち込むのは、変動費が売上高の減少に比例して減らないためである。',false,
 '誤り。変動費は売上高に比例して増減する。営業利益の落ち込みが増幅されるのは、売上高が減っても固定費が減らないためである。',7278),
('f5-179','2103','基礎','費用構造を比べると、損益分岐点比率が高い企業ほど営業レバレッジは低くなる。',false,
 '誤り。営業レバレッジ＝1÷（1－損益分岐点比率）なので、損益分岐点比率が高いほど営業レバレッジは高くなり、売上高の変化に対して営業利益が大きく変動する。',7279),
('f5-180','2103','応用','固定費300、変動費率50%、売上高1,000の企業で売上高が10%増加すると、営業利益は25%増加する。',true,
 '正しい。営業利益は1,000×0.5－300＝200、限界利益は500なので営業レバレッジは500÷200＝2.5倍となり、営業利益は10%×2.5＝25%増加する。',7280),
('f5-181','2103','標準','不確実性リスクを拡大させる要因には、景気変動に伴う売上高の変動、営業費用の構造、自己資本と他人資本の資本構成の3つがある。',true,
 '正しい。前の2つは事業の性質に起因するビジネスリスク、資本構成に関連して生じるものは財務リスクと呼ばれる。',7281),
('f5-182','2103','標準','食品や衣類などの生活必需品を扱う企業は景気変動の影響を受けやすく、半導体関連の企業は比較的影響を受けにくい。',false,
 '誤り。生活必需品を扱う企業は景気変動の影響を受けにくい。半導体市場はシリコンサイクルと呼ばれる景気変動で知られ、関連企業の売上高は景気の影響を直接受けやすい。',7282),
('f5-183','2103','応用','固定費400、変動費率60%、売上高1,200の企業の営業レバレッジは2倍である。',false,
 '誤り。限界利益は1,200×0.4＝480、営業利益は480－400＝80なので、営業レバレッジは480÷80＝6倍である。損益分岐点比率は1,000÷1,200で約83%と高い。',7283),
('f5-184','2103','標準','業績変動幅の大きさに着目する不確実性リスクは、業績の大幅な下振れで生じる倒産リスクを包含する、より広い概念である。',true,
 '正しい。他の条件が等しければ、不確実性リスクの大きい企業ほど倒産の可能性も高い。',7284),
('f5-185','2104','基礎','費用の合計額を固定費部分と変動費部分に分ける方法として、総費用法、最小2乗法、費目別法の3つがある。',true,
 '正しい。費用合計（売上原価＋販売費及び一般管理費）を分解することを固変分解という。',7285),
('f5-186','2104','基礎','総費用法では、収益の対前年変化額を費用の対前年変化額で割ることによって変動費率を求める。',false,
 '誤り。総費用法の変動費率は、費用の対前年変化額÷収益の対前年変化額である。費用の変化をとることで毎期一定の固定費が相殺される。',7286),
('f5-187','2104','応用','前期の売上高2,000・費用合計1,850、当期の売上高2,200・費用合計1,970の企業について総費用法を用いると、当期の固定費は650と推定される。',true,
 '正しい。変動費率は（1,970－1,850）÷（2,200－2,000）＝0.6、当期の変動費は0.6×2,200＝1,320なので、固定費＝1,970－1,320＝650である。',7287),
('f5-188','2104','標準','総費用法は固定費が時系列的に変化しないことを仮定しているため、その仮定が当てはまらないと、固定費がマイナスに推定されるなど適切な結果が得られないことがある。',true,
 '正しい。減価償却費などの固定費は投資や事業縮小により変化しうるため、総費用法の結果には注意が必要である。',7288),
('f5-189','2104','標準','四半期データに最小2乗法を適用して得た費用直線の切片は、そのまま年間の固定費の額として用いることができる。',false,
 '誤り。四半期データの切片は四半期ベースの固定費なので、4倍して年間の固定費を求める。年次データで推定した場合は4倍する必要はない。',7289),
('f5-190','2104','標準','最小2乗法で長期間のデータを用いると、設備投資に伴う減価償却費の変化分が固定費と誤認され、変動費率が過少に推定されやすい。',false,
 '誤り。長期のデータほど減価償却費や人件費の変化分を変動費と誤認するおそれがあり、変動費率が過大に、固定費が過少に推定される場合がある。',7290),
('f5-191','2104','標準','費目別法は、分析対象期間の費用構造が安定していることを前提とする方法であり、その点で総費用法や最小2乗法と共通している。',false,
 '誤り。総費用法と最小2乗法は費用構造の安定を前提とするが、費目別法は費用の内訳を性格に応じて分類するため、その前提を必要としない。適用可能なら積極的に採用すべきとされる。',7291),
('f5-192','2104','標準','製造原価の内訳が連結ベースで開示されているため、企業外部者でも製造業の企業に費目別法を容易に適用できる。',false,
 '誤り。製造原価の内訳は連結では開示されていないうえ、単体の製造原価明細書も開示が免除されたため、外部者が製造業に費目別法を適用するのは難しい。',7292),
('f5-193','2104','基礎','商業を営む企業に費目別法を適用する場合、他社から購入した商品の原価である売上原価は、全額を変動費として扱ってよい。',true,
 '正しい。販売費及び一般管理費は、開示された内訳の性格に応じて変動費と固定費に分類する。',7293),
('f5-194','2104','応用','8四半期分のデータで売上高の平均が30,000、費用の平均が28,000、推定された変動費率が0.4の企業の年間の固定費は16,000である。',false,
 '誤り。四半期の変動費は0.4×30,000＝12,000、四半期の固定費は28,000－12,000＝16,000なので、年間の固定費は4倍の64,000である。',7294),
('f5-195','2105','基礎','他人資本の利子は事前の契約で金額が固定されているため、業績が悪化した局面では利益への重荷となり、当期純利益を大きく減らす。',true,
 '正しい。反対に業績が良いときは、決められた額を払えば済むという利点がある。',7295),
('f5-196','2105','標準','自己資本と他人資本の構成に起因して生じる業績の不確実性は、ビジネスリスクと呼ばれる。',false,
 '誤り。資本構成から生じるリスクは財務リスクと呼ばれる。事業内容と費用構造に起因するリスクがビジネスリスクと呼ばれる。',7296),
('f5-197','2105','応用','総資本1,000（負債800、自己資本200）、負債利子率5%の企業で、不振時の営業利益が20の場合、税引前ROEは－10%となる。',true,
 '正しい。支払利息は800×5%＝40なので、税引前純利益は20－40＝－20、税引前ROEは－20÷200＝－10%である。ROAは2%である。',7297),
('f5-198','2105','応用','総資本2,000（負債1,200、自己資本800）、負債利子率4%、営業利益140の企業の税引前ROEは、ROAと同じ7%である。',false,
 '誤り。支払利息は1,200×4%＝48なので、税引前ROE＝（140－48）÷800＝11.5%である。ROA7%が利子率4%を上回るため、ROEはROAを上回る。',7298),
('f5-199','2105','標準','総資本に占める他人資本の割合が高い企業ほど、景気変動に伴うROAの変化がROEの段階でより大きく増幅される。',true,
 '正しい。他人資本が持つこの増幅作用は財務レバレッジと呼ばれ、他人資本の比重が高いほど強く表れる。',7299),
('f5-200','2105','標準','財務レバレッジが作用すると、景気の波による利益の振れが均されるので、利益の先行きを予測する際の不確実性は小さくなる。',false,
 '誤り。財務レバレッジが働くと景気変動などによる利益の振れが一段と大きくなり、将来利益の予測はより不確実になる。',7300)
on conflict (id) do update set point_code=excluded.point_code, level=excluded.level, stem=excluded.stem, answer=excluded.answer,
  explanation=excluded.explanation, sort=excluded.sort, active=true;
